INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96782, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奖项", "is_correct": true, "explanation": "正确答案。奖项，jiǎng xiàng，指设立的奖励名目或类别。"}, {"text": "假象", "is_correct": false, "explanation": "jiǎ xiàng 去掉了 jiǎng 的韵尾 ng，意思是表面的假相。"}, {"text": "景象", "is_correct": false, "explanation": "jǐng xiàng 的韵母是 ing，与 jiǎng 的 iang 不同，意思是景色或情景。"}, {"text": "想象", "is_correct": false, "explanation": "xiǎng xiàng 声母是 x，与 jiǎng 的 j 不同，声调相同，意思是想象。"}], "explanations": {"奖项": "正确答案。奖项，jiǎng xiàng，指设立的奖励名目或类别。", "假象": "jiǎ xiàng 去掉了 jiǎng 的韵尾 ng，意思是表面的假相。", "景象": "jǐng xiàng 的韵母是 ing，与 jiǎng 的 iang 不同，意思是景色或情景。", "想象": "xiǎng xiàng 声母是 x，与 jiǎng 的 j 不同，声调相同，意思是想象。"}, "sentence_index": null, "correct_answer": "奖项"}, "level_3": {"options": [{"text": "奖项", "is_correct": true, "explanation": "奖项可以以人名命名，“这个奖项以一位老科学家的名字命名”语义完整。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能被“命名”为设立的奖励名目，句意荒谬。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是可以以人名命名的奖励名目，句意荒谬。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内心状态，不能以人名命名为奖励名目，句意荒谬。"}], "explanations": {"奖项": "奖项可以以人名命名，“这个奖项以一位老科学家的名字命名”语义完整。", "天气": "语义：“天气”不能被“命名”为设立的奖励名目，句意荒谬。", "作业": "语义：“作业”不是可以以人名命名的奖励名目，句意荒谬。", "心情": "语义：“心情”是内心状态，不能以人名命名为奖励名目，句意荒谬。"}, "sentence_index": 6, "correct_answer": "奖项"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把奖项花光了。", "explanation": "这里应该用〈奖金〉。奖项是奖励的名目，不是钱，不能“花光”。"}, {"text": "奖项擦得很亮。", "explanation": "这里应该用〈奖杯〉。奖项不是实物，擦得发亮的应是奖杯。"}, {"text": "他把奖项挂在了客厅的墙上。", "explanation": "这里应该用〈奖状〉。奖项是抽象的奖励名目，不能挂在墙上，挂的应是奖状。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校为学生设立了一个很奖项。", "corrected_sentence": "学校为学生设立了一个新奖项。", "error_description": "修饰“奖项”应用形容词“新”，副词“很”不能直接修饰名词。“一个很奖项”错误。正确：学校为学生设立了一个新奖项。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个奖项去年颁发着三次。", "corrected_sentence": "这个奖项去年颁发过三次。", "error_description": "表示曾经发生过的经历要用助词“过”，“着”表示动作持续的状态，不能用于过去的次数。“颁发着三次”错误。正确：这个奖项去年颁发过三次。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
