INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96783, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96783, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "所有的，只要是这一类都这样。", "primary_collocate": null, "pronunciation": "fán shì", "ipa": "fan˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "凡是水果，这家店里都有卖。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是会游泳的孩子，请到左边来。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是小动物，我儿子都特别喜欢。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是迟到的人，都要在门口登记。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是中国的节日，我们班都会庆祝。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是看过这本书的人，都说好看。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是这家书店的新书，他都会买。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是认真学习的学生，老师都会表扬。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是红色的衣服，妹妹都想买。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是带着孩子的客人，可以先上车。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "凡是：所有属于某一类的都如此，后面常接“都／一律”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96783, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "只是", "is_correct": false, "explanation": "语义：“只是”表示仅仅，与“这家店里都有卖”的全部范围相矛盾。"}, {"text": "并非", "is_correct": false, "explanation": "语义：“并非”否定整个类别，与后半句“都有卖”的肯定判断相矛盾。"}, {"text": "也是", "is_correct": false, "explanation": "语义：“也是”表示并列，不表示同属一类的全部，与“凡是”的范围义不合。"}, {"text": "凡是", "is_correct": true, "explanation": "正确答案。“凡是”表示所有属于某一类的都如此，后接“都”。"}], "explanations": {"只是": "语义：“只是”表示仅仅，与“这家店里都有卖”的全部范围相矛盾。", "并非": "语义：“并非”否定整个类别，与后半句“都有卖”的肯定判断相矛盾。", "也是": "语义：“也是”表示并列，不表示同属一类的全部，与“凡是”的范围义不合。", "凡是": "正确答案。“凡是”表示所有属于某一类的都如此，后接“都”。"}, "sentence_index": 0, "correct_answer": "凡是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "凡是小王，都要在门口登记。", "explanation": "这里不宜用〈凡是〉。凡是指属于某一类的全部，不能用于单独的人名；指某一个人要直接说“小王”。"}, {"text": "凡是三个迟到的人，都要在门口登记。", "explanation": "这里不宜用〈凡是〉。凡是指某一类中无例外，不能限定具体的数量；指这三个人要直接说“这三个迟到的人”。"}, {"text": "凡是今天，都要在门口登记。", "explanation": "这里不宜用〈凡是〉。凡是指一类人或事物，不能用来指一段时间；说“今天”要直接说“今天都要在门口登记”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96783, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只有", "is_correct": false, "explanation": "语义：“只有”表示唯一条件，常与“才”呼应，不与“都”构成全体范围。"}, {"text": "虽然", "is_correct": false, "explanation": "语法：“虽然”是连词，表示让步，后面要接分句，不能直接接名词短语“这家书店的新书”。"}, {"text": "还是", "is_correct": false, "explanation": "语义：“还是”表示选择或持续，不能限定一类事物的全部范围，与“都会买”不合。"}, {"text": "凡是", "is_correct": true, "explanation": "正确答案。“凡是”表示属于某一类的全部，与后面的“都”呼应。"}], "explanations": {"只有": "语义：“只有”表示唯一条件，常与“才”呼应，不与“都”构成全体范围。", "虽然": "语法：“虽然”是连词，表示让步，后面要接分句，不能直接接名词短语“这家书店的新书”。", "还是": "语义：“还是”表示选择或持续，不能限定一类事物的全部范围，与“都会买”不合。", "凡是": "正确答案。“凡是”表示属于某一类的全部，与后面的“都”呼应。"}, "sentence_index": 6, "correct_answer": "凡是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "凡是北京，可以先上车。", "explanation": "这里不宜用〈凡是〉。凡是指一类人或事物，不能指向某一个地点；说某地来的客人要直接说“北京来的客人可以先上车”。"}, {"text": "凡是这位带着孩子的客人，可以先上车。", "explanation": "这里不宜用〈凡是〉。凡是指一类人或事物，不能单指某一个人；指这位要直接说“这位带着孩子的客人”。"}, {"text": "凡是两位带着孩子的客人，可以先上车。", "explanation": "这里不宜用〈凡是〉。凡是指某一类中无例外，不能限定具体的数量；指这两位要直接说“这两位带着孩子的客人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "凡是新鲜的水果，我妈妈爱买。", "corrected_sentence": "凡是新鲜的水果，我妈妈都爱买。", "error_description": "错误：句中漏掉了与「凡是」呼应的「都」。「凡是……」之后通常用「都」呼应，应说「我妈妈都爱买」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "凡是他喜欢的书，都他买了。", "corrected_sentence": "凡是他喜欢的书，他都买了。", "error_description": "“都”应放在主语“他”之后、动词“买了”之前，说“他都买了”；放在主语之前说“都他买了”是语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
