INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96784, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示在某个范围内无例外。", "primary_collocate": null, "pronunciation": "fán shì", "ipa": "fan˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "凡是学过的字，他都记得很清楚。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是我认识的人，都知道这件事。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是周末的活动，她都愿意参加。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是新来的同学，老师都会认真欢迎。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是在这里工作的人，都要先学安全知识。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是妈妈做的菜，我都爱吃。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是他说过的话，我都记在本子上。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是下雨的日子，爸爸都开车送我上学。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市凡是有名的饭店，他都去吃过。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "凡是进教室的人，都要把手机关掉。", "target_word": "凡是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "凡是：副词，限定范围，范围内无例外，常与“都”呼应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，不能限定范围，也不与“都”呼应构成全体义。"}, {"text": "从未", "is_correct": false, "explanation": "语义：“从未”否定了“学过”，与句中“学过的字”的前提相矛盾。"}, {"text": "也是", "is_correct": false, "explanation": "语义：“也是”表示并列，不表示限定范围内无例外，与“都”的全部含义不合。"}, {"text": "凡是", "is_correct": true, "explanation": "正确答案。“凡是”限定范围，范围内无例外，与“都”呼应。"}], "explanations": {"竟然": "语义：“竟然”表示出乎意料，不能限定范围，也不与“都”呼应构成全体义。", "从未": "语义：“从未”否定了“学过”，与句中“学过的字”的前提相矛盾。", "也是": "语义：“也是”表示并列，不表示限定范围内无例外，与“都”的全部含义不合。", "凡是": "正确答案。“凡是”限定范围，范围内无例外，与“都”呼应。"}, "sentence_index": 0, "correct_answer": "凡是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "凡是三个新来的同学，老师都会认真欢迎。", "explanation": "这里不宜用〈凡是〉。凡是指某一类中无一例外，不能限定具体的数量；指这三个人要直接说“这三个新来的同学”。"}, {"text": "凡是小王，老师都会认真欢迎。", "explanation": "这里不宜用〈凡是〉。凡是指一类人或事物，不能用于单独的人名；指某一个人要直接说“小王”。"}, {"text": "凡是北京，老师都去过。", "explanation": "这里不宜用〈凡是〉。凡是指同一类的全部，不能指向某一个具体的地点；说某个地方要直接说“北京”，如“老师都去过北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只有", "is_correct": false, "explanation": "语义：“只有”表示唯一条件，常与“才”呼应，不与“都”构成全体范围。"}, {"text": "并非", "is_correct": false, "explanation": "语义：“并非”否定整个判断，与后半句“都记在本子上”的肯定语气相矛盾。"}, {"text": "虽然", "is_correct": false, "explanation": "语法：“虽然”是连词，表示让步，后面要接分句，不能直接接名词短语。"}, {"text": "凡是", "is_correct": true, "explanation": "正确答案。“凡是”限定一类范围，范围内无例外，与“都”呼应。"}], "explanations": {"只有": "语义：“只有”表示唯一条件，常与“才”呼应，不与“都”构成全体范围。", "并非": "语义：“并非”否定整个判断，与后半句“都记在本子上”的肯定语气相矛盾。", "虽然": "语法：“虽然”是连词，表示让步，后面要接分句，不能直接接名词短语。", "凡是": "正确答案。“凡是”限定一类范围，范围内无例外，与“都”呼应。"}, "sentence_index": 6, "correct_answer": "凡是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "凡是我，都要把手机关掉。", "explanation": "这里不宜用〈凡是〉。凡是指一类人，不能用于说话人自己这一个人；指“我”要直接说“我”。"}, {"text": "凡是一班，都要把手机关掉。", "explanation": "这里不宜用〈凡是〉。凡是指某一类的全部，不能指向某一个具体班级；说某个班要直接说“一班”，如“一班的同学都要把手机关掉”。"}, {"text": "凡是两个进教室的人，都要把手机关掉。", "explanation": "这里不宜用〈凡是〉。凡是指某一类中无一例外，不能限定为“两个”；指这两个人要直接说“这两个进教室的人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "凡是他去过的地方，都我想去看看。", "corrected_sentence": "凡是他去过的地方，我都想去看看。", "error_description": "“都”应放在主语“我”之后、动词之前，即“我都想去看看”；放在“我”之前是语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "凡是来晚的同学，要都在门口登记。", "corrected_sentence": "凡是来晚的同学，都要在门口登记。", "error_description": "“都”应放在主语之后、助动词“要”之前，说“都要在门口登记”；说成“要都在门口登记”，“都”的位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
