INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96785, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引出麻烦事来。", "primary_collocate": null, "pronunciation": "shēng shì", "ipa": "ʂɤŋ˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "你乱说话，只会生事。", "target_word": "生事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事处理不好，容易生事。", "target_word": "生事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别给家里生事。", "target_word": "生事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一句玩笑话，竟然生事了。", "target_word": "生事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多管闲事只会给自己生事。", "target_word": "生事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那张照片发到网上，很容易生事。", "target_word": "生事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕你这样做会生事。", "target_word": "生事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想因为钱的事生事。", "target_word": "生事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信要是寄出去，恐怕会生事。", "target_word": "生事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这种脾气，迟早会生事。", "target_word": "生事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "言行不当而引出麻烦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bb7a24-95b6-4973-9e99-6f71c56b88be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96785, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生事", "is_correct": true, "explanation": "shēng shì，意思是引出麻烦事来。"}, {"text": "省事", "is_correct": false, "explanation": "shěng shì（第三声）与 shēng shì（第一声）声调不同，意思是省力、省麻烦。"}, {"text": "生食", "is_correct": false, "explanation": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是生的食物。"}, {"text": "盛世", "is_correct": false, "explanation": "shèng shì（第四声）与 shēng shì 第一个音节声调不同，意思是兴盛的时代。"}], "explanations": {"生事": "shēng shì，意思是引出麻烦事来。", "省事": "shěng shì（第三声）与 shēng shì（第一声）声调不同，意思是省力、省麻烦。", "生食": "第二个音节 shí（第二声）与 shì（第四声）声调不同，意思是生的食物。", "盛世": "shèng shì（第四声）与 shēng shì 第一个音节声调不同，意思是兴盛的时代。"}, "sentence_index": null, "correct_answer": "生事"}, "level_3": {"options": [{"text": "生事", "is_correct": true, "explanation": "引出麻烦，与“你乱说话”的后果相符。"}, {"text": "数钱", "is_correct": false, "explanation": "语义：“数钱”与“乱说话”没有因果关系，语境不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与“乱说话”毫无关联，不能作为它的结果。"}, {"text": "挂号", "is_correct": false, "explanation": "搭配：“挂号”是到医院办理的手续，不能接在“只会”后面表示乱说话的后果。"}], "explanations": {"生事": "引出麻烦，与“你乱说话”的后果相符。", "数钱": "语义：“数钱”与“乱说话”没有因果关系，语境不通。", "游泳": "语义：“游泳”与“乱说话”毫无关联，不能作为它的结果。", "挂号": "搭配：“挂号”是到医院办理的手续，不能接在“只会”后面表示乱说话的后果。"}, "sentence_index": 0, "correct_answer": "生事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次主动生事，帮老师把会场布置好了。", "explanation": "这里应该用〈帮忙〉。生事是贬义词，指惹是生非，不能用来形容主动帮人做事。"}, {"text": "这台电脑昨晚突然生事，把文件全删了。", "explanation": "这里应该用〈出故障〉。出故障指机器本身出了问题；生事指人的言行引出麻烦，主语不能是机器。"}, {"text": "这家饭馆的厨师很会生事，菜做得很香。", "explanation": "这里应该用〈会做菜〉。生事是贬义词，指惹是生非，不能用来夸厨师的手艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96785, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生事", "is_correct": true, "explanation": "惹出麻烦，与“我怕你这样做”的担心相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“这样做”没有因果关系，句子不成立。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“这样做”无关，“我怕你这样做会吃饭”语义不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“这样做”不能与“唱歌”构成后果上的搭配关系。"}], "explanations": {"生事": "惹出麻烦，与“我怕你这样做”的担心相符。", "睡觉": "语义：“睡觉”与“这样做”没有因果关系，句子不成立。", "吃饭": "语义：“吃饭”与“这样做”无关，“我怕你这样做会吃饭”语义不通。", "唱歌": "搭配：“这样做”不能与“唱歌”构成后果上的搭配关系。"}, "sentence_index": 6, "correct_answer": "生事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在路上摔了一跤，竟然生事了。", "explanation": "这里应该用〈出意外〉。生事指言行引出麻烦，不指身体上的意外；摔跤这类情况应说〈出意外〉。"}, {"text": "孩子考了满分，全家人都高兴得生事。", "explanation": "这里应该用〈欢喜〉。生事指惹是生非，不是表示情绪的词，表示全家欢喜不能用生事。"}, {"text": "他跑得很快，第一个冲过终点，大家都为他生事。", "explanation": "这里应该用〈欢呼〉。生事指惹出麻烦，用来表示为人庆贺与原意相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96785, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一开口就容易生事事。", "corrected_sentence": "他一开口就容易生事。", "error_description": "错误形式多写了一个“事”，正确形式为“生事”。“生事”是两字动宾式词语，中间不能再加“事”，正确形式为“容易生事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96785, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子总是把生事，老师都很头疼。", "corrected_sentence": "这个孩子总是生事，老师都很头疼。", "error_description": "错误形式多用了“把”，“把”字句要求“把”后接宾语再接动词，“把生事”不成句。“生事”是不及物的动宾词语，不能放在“把”后面，正确形式为“总是生事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "无名：没有名气，不为人所知，与“出名”的意思相反。"}, {"text": "安静", "is_correct": false, "explanation": "安静说声音小或没有动静，与“出名”的意思没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜说价钱低，是“贵”的反义词，与“出名”的意思无关。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚说明白、不模糊，与“出名”的意思无关。"}], "correct_answer": "无名", "explanations": {"无名": "无名：没有名气，不为人所知，与“出名”的意思相反。", "安静": "安静说声音小或没有动静，与“出名”的意思没有反义关系。", "便宜": "便宜说价钱低，是“贵”的反义词，与“出名”的意思无关。", "清楚": "清楚说明白、不模糊，与“出名”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "无名：没有名气，不为人所知，与“出名”的意思相反。"}, {"text": "昂贵", "is_correct": false, "explanation": "昂贵说价格高，与“出名”的意思无关。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮说外貌好看，与“出名”的意思无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙说表面不光滑，与“出名”的意思无关。"}], "correct_answer": "无名", "explanations": {"无名": "无名：没有名气，不为人所知，与“出名”的意思相反。", "昂贵": "昂贵说价格高，与“出名”的意思无关。", "漂亮": "漂亮说外貌好看，与“出名”的意思无关。", "粗糙": "粗糙说表面不光滑，与“出名”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有名；为众人所知（多指人因才能或事迹而名声在外）。", "primary_collocate": null, "pronunciation": "chū míng", "ipa": "ʈʂʰu˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他唱歌很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在我们学校很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年纪不大，却已经很出名了。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的书让他很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小男孩一夜之间就出名了。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想当歌星，也想出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生在城里很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踢球踢得好，所以很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太出名，很少有人认识他。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个演员在国外也很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出名了", "label": "体标"}], "register": "中性", "sense_fingerprint": "人因才能或事迹而被很多人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafe1b09-91b9-4c69-99c2-755cd2b95889') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出名", "is_correct": true, "explanation": "正确：出名 chū míng，意思是很多人都知道某人或某物。"}, {"text": "书名", "is_correct": false, "explanation": "shū（第一声）与 chū（第一声）声母不同（sh 与 ch），意思是书的名字。"}, {"text": "出门", "is_correct": false, "explanation": "mén 与 míng 韵母不同（-en 与 -ing），意思是外出。"}, {"text": "除名", "is_correct": false, "explanation": "chú（第二声）与 chū（第一声）声调不同，意思是从名册上除去名字。"}], "explanations": {"出名": "正确：出名 chū míng，意思是很多人都知道某人或某物。", "书名": "shū（第一声）与 chū（第一声）声母不同（sh 与 ch），意思是书的名字。", "出门": "mén 与 míng 韵母不同（-en 与 -ing），意思是外出。", "除名": "chú（第二声）与 chū（第一声）声调不同，意思是从名册上除去名字。"}, "sentence_index": null, "correct_answer": "出名"}, "level_3": {"options": [{"text": "出名", "is_correct": true, "explanation": "出名：很多人都知道他，符合“他唱歌很出名”的句意。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：矮说身材的高低，不说唱歌的名气，与“唱歌”搭不上。"}, {"text": "饿", "is_correct": false, "explanation": "语义：饿说想吃东西的身体状态，与唱歌无关，句子不通。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：便宜说价钱低，不能用来说唱歌的水平或名气。"}], "explanations": {"出名": "出名：很多人都知道他，符合“他唱歌很出名”的句意。", "矮": "体貌：矮说身材的高低，不说唱歌的名气，与“唱歌”搭不上。", "饿": "语义：饿说想吃东西的身体状态，与唱歌无关，句子不通。", "便宜": "搭配：便宜说价钱低，不能用来说唱歌的水平或名气。"}, "sentence_index": 0, "correct_answer": "出名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次比赛的表现很出名。", "explanation": "这里应该用〈出色〉。出名指人或事物被大家所知，说表现的优劣要用出色。"}, {"text": "这种饼干的价格很出名。", "explanation": "这里应该用〈便宜〉。出名说的是为众人所知，价格的高低要用便宜、贵等。"}, {"text": "这次考试他的成绩很出名。", "explanation": "这里应该用〈出众〉。出名说的是为众人所知，成绩的超群要用出众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出名", "is_correct": true, "explanation": "出名：很多人知道这位医生，符合句意。"}, {"text": "咸", "is_correct": false, "explanation": "语义：咸说味道，不能用来形容医生在城里的名声。"}, {"text": "远", "is_correct": false, "explanation": "搭配：远说距离，不能用来说人在城里是否有名。"}, {"text": "白", "is_correct": false, "explanation": "体貌：白说肤色，与医生在城里的名声无关。"}], "explanations": {"出名": "出名：很多人知道这位医生，符合句意。", "咸": "语义：咸说味道，不能用来形容医生在城里的名声。", "远": "搭配：远说距离，不能用来说人在城里是否有名。", "白": "体貌：白说肤色，与医生在城里的名声无关。"}, "sentence_index": 6, "correct_answer": "出名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位医生的手术技术很出名，可是病人不多，也没人知道他。", "explanation": "这里不能用〈出名〉。出名就是很多人都知道，后面却说“没人知道他”，前后矛盾；说技术好要用“高明”。"}, {"text": "这件衣服的颜色很出名。", "explanation": "这里应该用〈鲜艳〉。出名说人被众人所知，说颜色好看要用鲜艳、漂亮等。"}, {"text": "他今天的心情很出名。", "explanation": "这里应该用〈愉快〉。出名说人被众人所知，心情的好坏要用愉快、高兴等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一位很出名老师。", "corrected_sentence": "这是一位很出名的老师。", "error_description": "错误：“很出名老师”漏掉了“的”。正确：“很出名的老师”。“很”加形容词修饰名词时，形容词后通常要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee925ac6-791c-4c36-8350-ffbb5718d542') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
