INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96789, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个东西靠在一起，接在一起。", "primary_collocate": null, "pronunciation": "xiāng lián", "ipa": "ɕiɑŋ˥ lian˧˥", "syllable_count": 2, "sentences": [{"text": "这两个房间的门是相连的。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个小岛由一座长桥相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的院子和邻居家的院子相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河和那个大湖相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两节火车车厢紧紧相连着。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山和山相连，一眼看不到头。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教学楼和图书馆用走廊相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的两块地相连，中间没有围墙。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两条路在村口相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两张桌子相连，坐十个人没问题。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "相连：动词，两个具体的东西紧挨着、接在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96789, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相连", "is_correct": true, "explanation": "正确答案。两个东西靠在一起、接在一起。"}, {"text": "相恋", "is_correct": false, "explanation": "xiāng liàn（第四声）与 lián（第二声）只有第二个音节声调不同，意思是互相恋爱，不是接在一起。"}, {"text": "项链", "is_correct": false, "explanation": "xiàng liàn 与 xiāng lián 两个音节的声调都不同，意思是颈上戴的装饰品。"}, {"text": "香甜", "is_correct": false, "explanation": "tián 与 lián 只有声母不同（t 与 l），意思是甜美，与“连在一起”无关。"}], "explanations": {"相连": "正确答案。两个东西靠在一起、接在一起。", "相恋": "xiāng liàn（第四声）与 lián（第二声）只有第二个音节声调不同，意思是互相恋爱，不是接在一起。", "项链": "xiàng liàn 与 xiāng lián 两个音节的声调都不同，意思是颈上戴的装饰品。", "香甜": "tián 与 lián 只有声母不同（t 与 l），意思是甜美，与“连在一起”无关。"}, "sentence_index": null, "correct_answer": "相连"}, "level_3": {"options": [{"text": "相连", "is_correct": true, "explanation": "正确答案。门与门紧挨着、接在一起，是本义。"}, {"text": "相识", "is_correct": false, "explanation": "语义：相识指人与人之间认识，不能用来形容门。"}, {"text": "相逢", "is_correct": false, "explanation": "语义：相逢指人与人遇见，门不能相逢。"}, {"text": "相守", "is_correct": false, "explanation": "语义：相守指人长久地在一起，门不能“相守”。"}], "explanations": {"相连": "正确答案。门与门紧挨着、接在一起，是本义。", "相识": "语义：相识指人与人之间认识，不能用来形容门。", "相逢": "语义：相逢指人与人遇见，门不能相逢。", "相守": "语义：相守指人长久地在一起，门不能“相守”。"}, "sentence_index": 0, "correct_answer": "相连"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的心永远相连。", "explanation": "这里的“相连”指心意相通，是抽象用法；本词条的本义是两个具体的东西靠在一起、接在一起，这句用的不是本义。"}, {"text": "电脑和手机通过网络相连。", "explanation": "这里指通过网络建立联系，是另一个义项。电脑和手机并没有靠在一起、接在一起。"}, {"text": "两个国家的经济紧密相连。", "explanation": "这里指经济上互相依存，是抽象义项，不是具体东西挨在一起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相连", "is_correct": true, "explanation": "正确答案。走廊把两座楼连在一起，是本义。"}, {"text": "相爱", "is_correct": false, "explanation": "语义：相爱指人之间的感情，不用于建筑之间。"}, {"text": "相逢", "is_correct": false, "explanation": "语义：相逢指人与人遇见，教学楼和图书馆不能相逢。"}, {"text": "相遇", "is_correct": false, "explanation": "搭配：相遇用于人或事件碰面，不能说“用走廊相遇”。"}], "explanations": {"相连": "正确答案。走廊把两座楼连在一起，是本义。", "相爱": "语义：相爱指人之间的感情，不用于建筑之间。", "相逢": "语义：相逢指人与人遇见，教学楼和图书馆不能相逢。", "相遇": "搭配：相遇用于人或事件碰面，不能说“用走廊相遇”。"}, "sentence_index": 6, "correct_answer": "相连"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台打印机通过无线网络和电脑相连。", "explanation": "这里指通过网络建立连接，是另一个义项；打印机和电脑并没有靠在一起、接在一起。"}, {"text": "他和老同学的命运相连，谁也离不开谁。", "explanation": "这里指命运上的联系，属于抽象义项，不是具体东西靠在一起。"}, {"text": "这两个想法相连，互相印证。", "explanation": "想法是抽象的，这里是思想相通的意思，不是具体物体接在一起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个院子着相连着，中间没有围墙。", "corrected_sentence": "这两个院子相连着，中间没有围墙。", "error_description": "“着”放错了位置。“相连”前面不能加“着”，持续状态的“着”只放在动词后面，应说“相连着”，不说“着相连着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两条路很相连，车可以直接开过去。", "corrected_sentence": "这两条路相连，车可以直接开过去。", "error_description": "程度副词“很”不能修饰“相连”。“相连”表示接在一起的结果，不能分程度，应去掉“很”，说“这两条路相连”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
