INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96790, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "互相连接在一起。", "primary_collocate": null, "pronunciation": "xiāng lián", "ipa": "ɕiɑŋ˥ lian˧˥", "syllable_count": 2, "sentences": [{"text": "电脑和手机通过网络相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的心永远相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些城市靠高铁相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的经济紧密相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两台服务器通过专线相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界各地的人因为互联网而相连。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱情和责任是紧紧相连的。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个问题紧紧相连，不能分开看。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音箱和电视相连着，声音很大。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个系统通过数据线相连，信息可以互通。", "target_word": "相连", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "相连：动词，双方通过线路、网络、关系等互相连接", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96790, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相连", "is_correct": true, "explanation": "正确答案。通过线路、网络或关系互相连接。"}, {"text": "相恋", "is_correct": false, "explanation": "xiāng liàn（第四声）与 lián（第二声）只有第二个音节声调不同，意思是互相恋爱。"}, {"text": "项链", "is_correct": false, "explanation": "xiàng liàn 与 xiāng lián 两个音节的声调都不同，意思是颈上戴的装饰品。"}, {"text": "香甜", "is_correct": false, "explanation": "tián 与 lián 只有声母不同（t 与 l），意思是甜美。"}], "explanations": {"相连": "正确答案。通过线路、网络或关系互相连接。", "相恋": "xiāng liàn（第四声）与 lián（第二声）只有第二个音节声调不同，意思是互相恋爱。", "项链": "xiàng liàn 与 xiāng lián 两个音节的声调都不同，意思是颈上戴的装饰品。", "香甜": "tián 与 lián 只有声母不同（t 与 l），意思是甜美。"}, "sentence_index": null, "correct_answer": "相连"}, "level_3": {"options": [{"text": "相连", "is_correct": true, "explanation": "正确答案。电脑和手机通过网络互相连接。"}, {"text": "相识", "is_correct": false, "explanation": "语义：相识指人与人认识，设备之间不能相识。"}, {"text": "相爱", "is_correct": false, "explanation": "语义：相爱专指人之间的感情，不用于设备。"}, {"text": "相守", "is_correct": false, "explanation": "搭配：相守指人长久地在一起，不说电脑和手机“相守”。"}], "explanations": {"相连": "正确答案。电脑和手机通过网络互相连接。", "相识": "语义：相识指人与人认识，设备之间不能相识。", "相爱": "语义：相爱专指人之间的感情，不用于设备。", "相守": "搭配：相守指人长久地在一起，不说电脑和手机“相守”。"}, "sentence_index": 0, "correct_answer": "相连"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家和学校相连，中间隔着一条马路。", "explanation": "这里应该用〈相邻〉。相连指两者接在一起、没有间隔；相邻只是挨着，中间可以有距离。句中“中间隔着一条马路”与“相连”矛盾。"}, {"text": "这对双胞胎的外形相连。", "explanation": "这里应该用〈相似〉。相似指外形、性质接近，用于比较像不像；相连指接在一起，不能用来形容外形。"}, {"text": "我和同桌相连三年了。", "explanation": "这里应该用〈相处〉。相连说的是事物之间的接合或联系，“和同桌相连三年”搭配不当，应说“和同桌相处三年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相连", "is_correct": true, "explanation": "正确答案。爱情和责任紧密联系在一起。"}, {"text": "相逢", "is_correct": false, "explanation": "语义：相逢指人与人遇见，不用来描述爱情和责任。"}, {"text": "相距", "is_correct": false, "explanation": "搭配：相距说的是距离，不说“紧紧相距”。"}, {"text": "相遇", "is_correct": false, "explanation": "语义：相遇指碰面，不能用来描述两种抽象事物的关系。"}], "explanations": {"相连": "正确答案。爱情和责任紧密联系在一起。", "相逢": "语义：相逢指人与人遇见，不用来描述爱情和责任。", "相距": "搭配：相距说的是距离，不说“紧紧相距”。", "相遇": "语义：相遇指碰面，不能用来描述两种抽象事物的关系。"}, "sentence_index": 6, "correct_answer": "相连"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两座岛屿相连千里，彼此看不见。", "explanation": "这里应该用〈相隔〉。相隔指两地中间有距离；相连指接在一起。句中“彼此看不见”也与“相连”矛盾。"}, {"text": "两人的意见完全相连，谁也不让谁。", "explanation": "这里应该用〈相左〉。“意见相左”才表示意见不同；“意见相连”不是自然说法，且与“谁也不让谁”的关系不符。"}, {"text": "他们俩相连十年，却分开住在两个城市。", "explanation": "这里应该用〈相爱〉。相爱指两人之间有爱情；“他们俩相连十年”不是自然说法，相连不能这样带时间段来表示两人的感情关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电脑通过数据线和显示器相连了着。", "corrected_sentence": "这台电脑通过数据线和显示器相连。", "error_description": "“相连”后已带“了”，不能再加“着”。同一动词后不能同时用两个动态助词，应去掉“了着”，说“这台电脑通过数据线和显示器相连”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两家公司的网络很相连，资料可以共享。", "corrected_sentence": "这两家公司的网络已经相连，资料可以共享。", "error_description": "“相连”是动词，不能受程度副词“很”修饰。应说“已经相连”，表示状态已经形成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
