INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96791, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把文章或照片印在报纸上给大家看。", "primary_collocate": null, "pronunciation": "kān dēng", "ipa": "kʰan˥ təŋ˥", "syllable_count": 2, "sentences": [{"text": "报纸刊登了一张很大的照片。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片昨天刊登在报纸第一版。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的作文刊登在校报上，大家都很高兴。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者写的文章已经刊登了。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸刊登了那位运动员获奖的消息。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这张照片刊登在报纸上。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的一篇散文曾经刊登在本地的报纸上。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上刊登的照片让很多人感动。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条消息刊登后，很多人打来电话。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的第一篇文章刊登在周末版上。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刊登了", "label": "完成体"}, {"form": "刊登过", "label": "经历体"}, {"form": "刊登着", "label": "持续体"}], "register": "书面语", "sense_fingerprint": "文章照片印在报纸上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2d840b2-e5d9-4a1d-acf2-765ae14bc06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刊登", "is_correct": true, "explanation": "“刊登”指把照片印在报纸上，这里指报纸登出一张大照片。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，不能唱照片。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于食物，不能说煮照片。"}, {"text": "颁布", "is_correct": false, "explanation": "搭配：“颁布”用于法律、政策，不能说颁布照片。"}], "explanations": {"刊登": "“刊登”指把照片印在报纸上，这里指报纸登出一张大照片。", "唱": "语义：“唱”指发声演唱，不能唱照片。", "煮": "搭配：“煮”用于食物，不能说煮照片。", "颁布": "搭配：“颁布”用于法律、政策，不能说颁布照片。"}, "sentence_index": 0, "correct_answer": "刊登"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂刊登了一万份宣传册。", "explanation": "这里应该用〈印刷〉。刊登指在报刊上登载内容，印制大批宣传册要用“印刷”。"}, {"text": "街上刊登了很多海报。", "explanation": "这里应该用〈张贴〉。刊登只用于在报刊上登载内容，把海报贴在街上要用“张贴”。"}, {"text": "他到派出所刊登了身份证。", "explanation": "这里应该用〈登记〉。刊登是在报刊上登载，办理身份证等手续要用“登记”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刊登", "is_correct": true, "explanation": "“刊登”指在报刊上登载，这里指散文登在本地的报纸上。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”用于车辆，不能说驾驶在报纸上。"}, {"text": "播放", "is_correct": false, "explanation": "语义：“播放”指播送影音，报纸上不能播放散文。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”用于食物，不能说吃在报纸上。"}], "explanations": {"刊登": "“刊登”指在报刊上登载，这里指散文登在本地的报纸上。", "驾驶": "搭配：“驾驶”用于车辆，不能说驾驶在报纸上。", "播放": "语义：“播放”指播送影音，报纸上不能播放散文。", "吃": "搭配：“吃”用于食物，不能说吃在报纸上。"}, "sentence_index": 6, "correct_answer": "刊登"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司刊登了新股票。", "explanation": "这里应该用〈发行〉。股票由公司发行，不能说刊登；刊登只指在报刊上登载内容。"}, {"text": "电台每天刊登天气预报。", "explanation": "这里应该用〈广播〉。电台播送内容要用“广播”，刊登只用于报刊。"}, {"text": "出版社每年刊登几百本书。", "explanation": "这里应该用〈出版〉。书籍要用“出版”，刊登指在报刊上登载内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那篇文章上周刊登过在晚报上。", "corrected_sentence": "那篇文章上周刊登在晚报上。", "error_description": "错误：“刊登过在”；正确：“刊登在”。“刊登”后接“在＋处所”时，中间不能加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的第一篇文章刊登周末版上了。", "corrected_sentence": "她的第一篇文章刊登在周末版上了。", "error_description": "错误：漏掉了“在”。正确：“刊登在……上”，表示登载的处所要用介词“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
