INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96792, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在报刊上登载。", "primary_collocate": null, "pronunciation": "kān dēng", "ipa": "kʰan˥ təŋ˥", "syllable_count": 2, "sentences": [{"text": "这家报纸刊登了一则招聘广告。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的文章下个月会在杂志上刊登。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸今天刊登了天气预报。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的诗寄给报社，希望能刊登。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份杂志刊登过很多名人的访谈。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家公司想在报纸上刊登一个广告。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的晚报刊登了市长的讲话。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社决定刊登这位读者的来信。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，报纸上刊登着一条寻人启事。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为版面不够，这篇文章没有刊登。", "target_word": "刊登", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刊登了", "label": "完成体"}, {"form": "刊登过", "label": "经历体"}, {"form": "刊登着", "label": "持续体"}], "register": "书面语", "sense_fingerprint": "报刊登载内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2d840b2-e5d9-4a1d-acf2-765ae14bc06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
