INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96793, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把较长的名称省去部分字后得到的简短说法。", "primary_collocate": null, "pronunciation": "shěng chēng", "ipa": "ʂɤŋ˨˩ tʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "“北大”是“北京大学”的省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个长名字有一个省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“奥运会”是什么的省称？", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说“高铁”是“高速铁路”的省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个省称比全名好记多了。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“人大”是“人民代表大会”的省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写短信时，我们常用省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道“北京师范大学”的省称吗？", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的名字太长，大家都用省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“地铁”是“地下铁道”的省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "省称：名词，较长名称省去部分字后得到的简短说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96793, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省称", "is_correct": true, "explanation": "正确答案。把较长的名称说得短一点。"}, {"text": "声称", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）只有声调不同，意思是公开宣称。"}, {"text": "生成", "is_correct": false, "explanation": "两个音节的声调都与 shěng chēng 不同，意思是产生、形成。"}, {"text": "省城", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）只有第二个音节声调不同，意思是省会城市。"}, {"text": "圣城", "is_correct": false, "explanation": "两个音节的声调都与 shěng chēng 不同，意思是圣洁的城市。"}], "explanations": {"省称": "正确答案。把较长的名称说得短一点。", "声称": "shēng（第一声）与 shěng（第三声）只有声调不同，意思是公开宣称。", "生成": "两个音节的声调都与 shěng chēng 不同，意思是产生、形成。", "省城": "chéng（第二声）与 chēng（第一声）只有第二个音节声调不同，意思是省会城市。", "圣城": "两个音节的声调都与 shěng chēng 不同，意思是圣洁的城市。"}, "sentence_index": null, "correct_answer": "省称"}, "level_3": {"options": [{"text": "省称", "is_correct": true, "explanation": "正确答案。北大是北京大学的省称。"}, {"text": "地址", "is_correct": false, "explanation": "语义：北大是简称，不是北京大学的地址。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“北京大学的翻译”不能指北大这个简称。"}, {"text": "书名", "is_correct": false, "explanation": "语义：北京大学是机构名，不是书的名字。"}], "explanations": {"省称": "正确答案。北大是北京大学的省称。", "地址": "语义：北大是简称，不是北京大学的地址。", "翻译": "搭配：“北京大学的翻译”不能指北大这个简称。", "书名": "语义：北京大学是机构名，不是书的名字。"}, "sentence_index": 0, "correct_answer": "省称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "广东的省称是广东省。", "explanation": "广东省是完整的名称，不是把名称变短，所以它不是省称。省称指较短的说法。"}, {"text": "“高速铁路”是“高铁”的省称。", "explanation": "方向搞反了。高铁是较短的说法，高速铁路是全称，省称应放在短的一方。"}, {"text": "“北大”这个省称比“北京大学”还长。", "explanation": "“北大”比“北京大学”短，句中说它更长，与省称的含义（把名称说得更短）相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省称", "is_correct": true, "explanation": "正确答案。写短信时常用较短的说法。"}, {"text": "书签", "is_correct": false, "explanation": "语义：书签用于标记书页，与写短信无关。"}, {"text": "信封", "is_correct": false, "explanation": "语义：信封用来装信件，不是写短信时使用的东西。"}, {"text": "名片", "is_correct": false, "explanation": "搭配：写短信时不说“常用名片”。"}], "explanations": {"省称": "正确答案。写短信时常用较短的说法。", "书签": "语义：书签用于标记书页，与写短信无关。", "信封": "语义：信封用来装信件，不是写短信时使用的东西。", "名片": "搭配：写短信时不说“常用名片”。"}, "sentence_index": 6, "correct_answer": "省称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“地铁”是“交通工具”的省称。", "explanation": "交通工具是一个大类，不是地铁的全称，所以“地铁”不是它的省称。"}, {"text": "“他”是“他们”的省称。", "explanation": "“他们”不是名称，省称指名称的简化，代词不能算作省称。"}, {"text": "“地铁”这个省称比“地下铁道”还长，大家都嫌它太繁琐。", "explanation": "“地铁”比“地下铁道”短，句中说它更长，与省称的含义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“北师大”是“北京师范大学”省称。", "corrected_sentence": "“北师大”是“北京师范大学”的省称。", "error_description": "省略了结构助词“的”。“X是Y的省称”的句式要求“的”，应说“北京师范大学的省称”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个长名字已经有了一省称。", "corrected_sentence": "这个长名字已经有了一个省称。", "error_description": "数量词“一”后面漏了量词“个”。名词“省称”前要用“一个”，不能只说“一省称”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
