INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96794, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名称的简称，多指省份的简称。", "primary_collocate": null, "pronunciation": "shěng chēng", "ipa": "ʂɤŋ˨˩ tʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "“粤”是广东的省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四川的省称是“川”或者“蜀”。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车牌上的第一个汉字通常是省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“沪”是上海的省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖南的省称是什么？", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道河南的省称吗？", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“浙”是浙江的省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道“闽”是哪个省的省称。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山东的省称是“鲁”。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陕西的省称是“陕”或“秦”。", "target_word": "省称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "省称：名词，多指各省、市的单字简称，如“粤”“川”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e36a8cdb-5406-47d1-930e-7fc5be5a3f6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_wa