INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96794, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省称", "is_correct": true, "explanation": "正确答案。省份名称的简称。"}, {"text": "声称", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）只有声调不同，意思是公开宣称。"}, {"text": "生成", "is_correct": false, "explanation": "两个音节的声调都与 shěng chēng 不同，意思是产生、形成。"}, {"text": "省城", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）只有第二个音节声调不同，意思是省会城市。"}, {"text": "圣城", "is_correct": false, "explanation": "两个音节的声调都与 shěng chēng 不同，意思是圣洁的城市。"}], "explanations": {"省称": "正确答案。省份名称的简称。", "声称": "shēng（第一声）与 shěng（第三声）只有声调不同，意思是公开宣称。", "生成": "两个音节的声调都与 shěng chēng 不同，意思是产生、形成。", "省城": "chéng（第二声）与 chēng（第一声）只有第二个音节声调不同，意思是省会城市。", "圣城": "两个音节的声调都与 shěng chēng 不同，意思是圣洁的城市。"}, "sentence_index": null, "correct_answer": "省称"}, "level_3": {"options": [{"text": "省称", "is_correct": true, "explanation": "正确答案。粤是广东的省称。"}, {"text": "首府", "is_correct": false, "explanation": "语义：首府是省级行政中心城市，粤不是城市名。"}, {"text": "全称", "is_correct": false, "explanation": "语义：粤是简称，不是广东的全称。"}, {"text": "特产", "is_correct": false, "explanation": "搭配：粤是名称，不能说“广东的特产”来指代它。"}], "explanations": {"省称": "正确答案。粤是广东的省称。", "首府": "语义：首府是省级行政中心城市，粤不是城市名。", "全称": "语义：粤是简称，不是广东的全称。", "特产": "搭配：粤是名称，不能说“广东的特产”来指代它。"}, "sentence_index": 0, "correct_answer": "省称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“上海”是“沪”的省称。", "explanation": "方向搞反了。沪是上海的简称，上海是全称；省称应放在短的一方，应说“沪”是上海的省称。"}, {"text": "“沪”是一种快餐的省称。", "explanation": "“快餐”不是省份或地区的名称，“沪”也不是它的简称，把省称用在这里说不通。"}, {"text": "“沪”比“上海”还长，它是上海的省称。", "explanation": "“沪”只有一个字，比“上海”短；句中说它更长，与省称的含义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDE