INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省称", "is_correct": true, "explanation": "正确答案。浙是浙江的省称。"}, {"text": "省会", "is_correct": false, "explanation": "语义：省会指省的首府城市，浙不是城市名。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言指地方话，浙不是一种方言。"}, {"text": "名胜", "is_correct": false, "explanation": "搭配：名胜指名胜古迹，不用来指省份名称的简称。"}], "explanations": {"省称": "正确答案。浙是浙江的省称。", "省会": "语义：省会指省的首府城市，浙不是城市名。", "方言": "语义：方言指地方话，浙不是一种方言。", "名胜": "搭配：名胜指名胜古迹，不用来指省份名称的简称。"}, "sentence_index": 6, "correct_answer": "省称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“陕西”是“陕”的省称。", "explanation": "方向搞反了。陕是简称，陕西是全称，省称应放在短的一方。"}, {"text": "陕西的省称是陕西省。", "explanation": "陕西省是完整的名称，不是较短的说法，所以它不是省称。"}, {"text": "陕西的省称是“西北”。", "explanation": "西北是地理区域，不是陕西的名称简化，所以不能作为它的省称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“湘”是湖南地省称。", "corrected_sentence": "“湘”是湖南的省称。", "error_description": "修饰名词的定语要用结构助词“的”，不能用“地”。“地”用于修饰动词，应说“湖南的省称”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“鄂”湖北的省称。", "corrected_sentence": "“鄂”是湖北的省称。", "error_description": "判断句“X是Y的省称”中漏了动词“是”。应说：“鄂”是湖北的省称，不能省去“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8140f619-b278-48da-a937-99d9324c9fd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
