INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96795, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96795, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "会动的画，小朋友爱看的故事。", "primary_collocate": null, "pronunciation": "dòng màn", "ipa": "tʊŋ˥˩ man˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟放学回家，先看一个小时动漫。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都爱看动漫里的小动物。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末晚上，我陪女儿看了一部动漫。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动漫的故事很有意思，小朋友都喜欢。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动漫里的小猫会说话，还会唱歌。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说看动漫的时间不能太长。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候最爱看的动漫是《猫和老鼠》。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里正在放一部新动漫。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的书包上画着他喜欢的动漫人物。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完动漫以后，孩子们开心地笑了。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "動漫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会动的画面讲的故事，孩子爱看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d51479-38c9-402d-8933-0c454435b4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96795, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以观看的作品，“先看一个小时石头”不成立。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“看”不能与“饭”搭配，吃饭要说“吃”。"}, {"text": "动漫", "is_correct": true, "explanation": "正确：“先看一个小时动漫”指看会动的画和故事，语义通顺。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是可以观看的内容，不能“看一个小时”。"}], "explanations": {"石头": "语义：石头不是可以观看的作品，“先看一个小时石头”不成立。", "饭": "搭配：“看”不能与“饭”搭配，吃饭要说“吃”。", "动漫": "正确：“先看一个小时动漫”指看会动的画和故事，语义通顺。", "冰箱": "语义：冰箱是家电，不是可以观看的内容，不能“看一个小时”。"}, "sentence_index": 0, "correct_answer": "动漫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我买了一个动漫，我每天抱着睡觉。", "explanation": "这里应该用〈玩具〉。能买来抱着睡觉的是玩具，动漫是用来看的作品。"}, {"text": "这个动漫很软，躺上去很舒服。", "explanation": "这里应该用〈沙发〉。能躺上去的是沙发，动漫是用来看的作品。"}, {"text": "这款动漫需要很快的手速。", "explanation": "这里应该用〈游戏〉。需要手速操作的是游戏，动漫是用来观看的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96795, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不能说“最爱看的蔬菜是《猫和老鼠》”。"}, {"text": "粥", "is_correct": false, "explanation": "搭配：“粥”要说“喝”或“吃”，不能与“看”搭配。"}, {"text": "动漫", "is_correct": true, "explanation": "正确：“最爱看的动漫是《猫和老鼠》”指看的作品，语义通顺。"}, {"text": "床", "is_correct": false, "explanation": "语义：床是家具，不是可以观看的内容。"}], "explanations": {"蔬菜": "语义：蔬菜是食物，不能说“最爱看的蔬菜是《猫和老鼠》”。", "粥": "搭配：“粥”要说“喝”或“吃”，不能与“看”搭配。", "动漫": "正确：“最爱看的动漫是《猫和老鼠》”指看的作品，语义通顺。", "床": "语义：床是家具，不是可以观看的内容。"}, "sentence_index": 6, "correct_answer": "动漫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们拼完动漫以后，开心地笑了。", "explanation": "这里应该用〈拼图〉。拼的是拼图，动漫是用来看的。"}, {"text": "孩子们吃完动漫以后，开心地笑了。", "explanation": "这里应该用〈蛋糕〉。吃的是蛋糕，动漫不能吃。"}, {"text": "孩子们烤完动漫以后，开心地笑了。", "explanation": "这里应该用〈面包〉。烤的是面包，动漫不能烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96795, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天看了一首动漫。", "corrected_sentence": "我昨天看了一部动漫。", "error_description": "量词错误：“动漫”作品应用量词“部”，不能用“首”（“首”用于歌曲、诗词）。应说「看了一部动漫」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96795, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每周末都看了完一部动漫。", "corrected_sentence": "我们每周末都看完一部动漫。", "error_description": "“了”位置错误：“看完”是动补结构，“了”不能插在“看”和“完”之间；此处直接说「看完一部动漫」，不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
