INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动画和漫画的合称。", "primary_collocate": null, "pronunciation": "dòng màn", "ipa": "tʊŋ˥˩ man˥˩", "syllable_count": 2, "sentences": [{"text": "他喜欢动漫，不但看动画，也看漫画。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动漫包括动画和漫画两种。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们社团的同学都很喜欢动漫。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本的动漫在世界上很有名。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房间里放满了动漫和游戏的东西。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动漫不只是给孩子看的，大人也爱看。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天放学后都要看动漫。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有个社团，专门聊动漫。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就爱动漫，长大后想当画家。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在有很多电影是根据动漫拍的。", "target_word": "动漫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "動漫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动画和漫画两类作品的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7d51479-38c9-402d-8933-0c454435b4a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饮料", "is_correct": false, "explanation": "搭配：“看”不能与“饮料”搭配，“他喜欢饮料，不但看动画”不通。"}, {"text": "名称", "is_correct": false, "explanation": "语义：名称是事物的叫法，不是可以喜欢或观看的作品。"}, {"text": "动漫", "is_correct": true, "explanation": "正确：“动漫”是动画和漫画的合称，与“不但看动画，也看漫画”相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是用来品尝的，不能说“不但看动画，也看漫画”。"}], "explanations": {"饮料": "搭配：“看”不能与“饮料”搭配，“他喜欢饮料，不但看动画”不通。", "名称": "语义：名称是事物的叫法，不是可以喜欢或观看的作品。", "动漫": "正确：“动漫”是动画和漫画的合称，与“不但看动画，也看漫画”相符。", "味道": "语义：味道是用来品尝的，不能说“不但看动画，也看漫画”。"}, "sentence_index": 0, "correct_answer": "动漫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部动漫要用油炒。", "explanation": "这里应该用〈菜〉。要用油炒的是菜，动漫是用来看的作品，不能下锅。"}, {"text": "这位动漫的作品很有名。", "explanation": "这里应该用〈漫画家〉。动漫是作品的合称，不能指人，指画漫画的人要说漫画家。"}, {"text": "他每天用动漫刷牙。", "explanation": "这里应该用〈牙膏〉。刷牙用的是牙膏，动漫是用来看的作品，不能用来刷牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星期", "is_correct": false, "explanation": "搭配：“看”不能与“星期”搭配，星期是时间词，不是可以观看的内容。"}, {"text": "动漫", "is_correct": true, "explanation": "正确：“每天放学后都要看动漫”指看动画或漫画作品，语义通顺。"}, {"text": "拖鞋", "is_correct": false, "explanation": "搭配：“看”不能与“拖鞋”搭配，拖鞋是穿的东西，不是可以观看的内容。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午是时间，不能被观看。"}], "explanations": {"星期": "搭配：“看”不能与“星期”搭配，星期是时间词，不是可以观看的内容。", "动漫": "正确：“每天放学后都要看动漫”指看动画或漫画作品，语义通顺。", "拖鞋": "搭配：“看”不能与“拖鞋”搭配，拖鞋是穿的东西，不是可以观看的内容。", "中午": "语义：中午是时间，不能被观看。"}, "sentence_index": 6, "correct_answer": "动漫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个动漫可以坐一千人。", "explanation": "这里应该用〈剧场〉。能坐一千人的是剧场，动漫是作品，不是地方。"}, {"text": "妹妹每天早上用动漫洗脸。", "explanation": "这里应该用〈毛巾〉。洗脸用的是毛巾，动漫是动画和漫画作品，不能用来洗脸。"}, {"text": "这个动漫有很多游乐设施。", "explanation": "这里应该用〈游乐园〉。有游乐设施的是游乐园，动漫不是场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他收藏了一只动漫。", "corrected_sentence": "他收藏了一套动漫。", "error_description": "量词错误：“只”用于动物等，不能用来计量动漫作品。收藏动漫作品可用“套”或“部”，此处改为「收藏了一套动漫」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现在动漫了很流行。", "corrected_sentence": "现在动漫很流行。", "error_description": "“了”的位置错误：描述“动漫很流行”的状态不需要“了”，多加的“了”放在“动漫”后面语序不对。应说「现在动漫很流行」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8cd54115-a325-4a05-9199-f73abc513a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
