INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用手机发送的简短文字信息。", "primary_collocate": null, "pronunciation": "duǎn xìn", "ipa": "tuan˨˩˦ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "银行给我发来一条短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我收到一条短信，说快递到了。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天都收到好几条陌生人发来的短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条短信是公司发的通知。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员用短信告诉我取件地址。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机收不到短信了。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把那条短信给我看看。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他删过很多旧短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短信里写着开会的时间。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一响，我就看短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "垃圾短信", "label": "复合"}], "register": "口语", "sense_fingerprint": "短信：手机发送的简短文字信息，如通知、验证码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e8e5b6b-41e6-4dbe-82c6-698d5104ef7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短信", "is_correct": true, "explanation": "正确。“发来”的对象是信息，“条”是短信的量词。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不能由银行“发来”。"}, {"text": "蛇", "is_correct": false, "explanation": "搭配：“发来”用于信息和货物，不用于活的动物。"}, {"text": "船", "is_correct": false, "explanation": "语义：船不能被“发来”给人，句子说的是通知信息。"}], "explanations": {"短信": "正确。“发来”的对象是信息，“条”是短信的量词。", "河": "语义：河不能由银行“发来”。", "蛇": "搭配：“发来”用于信息和货物，不用于活的动物。", "船": "语义：船不能被“发来”给人，句子说的是通知信息。"}, "sentence_index": 0, "correct_answer": "短信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上都画短信。", "explanation": "这里应该用〈图画〉。“画”搭配图画，短信是文字，不能画。"}, {"text": "他用手机拍了一条短信。", "explanation": "这里应该用〈照片〉。“拍”搭配照片、视频，短信不能被拍。"}, {"text": "我昨天收到一只短信。", "explanation": "这里误把短信当成〈动物〉那样用“只”计量。“只”用于动物等，短信是文字，应用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短信", "is_correct": true, "explanation": "正确。“把……给我看看”的对象是可以拿来给人看的文字信息。"}, {"text": "命", "is_correct": false, "explanation": "语义：“命”指生命，不能拿来给我看。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不能被拿来给我看。"}, {"text": "溪", "is_correct": false, "explanation": "语义：溪不能被拿来给我看。"}], "explanations": {"短信": "正确。“把……给我看看”的对象是可以拿来给人看的文字信息。", "命": "语义：“命”指生命，不能拿来给我看。", "河": "语义：河不能被拿来给我看。", "溪": "语义：溪不能被拿来给我看。"}, "sentence_index": 6, "correct_answer": "短信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天把一条短信装进了箱子。", "explanation": "这里误把短信当成〈物品〉来装。“装”搭配有形的物品，短信是文字，不能装进箱子。"}, {"text": "他在舞台上唱了一条短信。", "explanation": "这里应该用〈歌曲〉。“唱”搭配歌曲，短信是文字，不能唱。"}, {"text": "他每周末都下短信。", "explanation": "这里应该用〈棋〉。“下”搭配棋类，短信不能下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天收到一块短信，说包裹到了。", "corrected_sentence": "我昨天收到一条短信，说包裹到了。", "error_description": "“短信”的量词应用“条”，不能用“块”（“块”用于块状的东西）。正确：我昨天收到一条短信，说包裹到了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把那只短信转给我。", "corrected_sentence": "请把那条短信转给我。", "error_description": "量词错误：“短信”的量词用“条”，不用“只”（“只”用于动物等）。正确：请把那条短信转给我。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96799, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现在", "is_correct": true, "explanation": "“现在”与“原先”在时间上相对，分别指当前和以前的情况，构成反义。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”是家具名词，与“原先”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”是自然事物名词，与“原先”不构成反义。"}, {"text": "山峰", "is_correct": false, "explanation": "“山峰”是地理名词，与“原先”没有反义关系。"}], "correct_answer": "现在", "explanations": {"现在": "“现在”与“原先”在时间上相对，分别指当前和以前的情况，构成反义。", "桌子": "“桌子”是家具名词，与“原先”没有反义关系。", "河流": "“河流”是自然事物名词，与“原先”不构成反义。", "山峰": "“山峰”是地理名词，与“原先”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96799, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现在", "is_correct": true, "explanation": "“现在”与“原先”在时间上相对，分别指当前和以前的情况，构成反义。"}, {"text": "书包", "is_correct": false, "explanation": "“书包”是物品名词，与“原先”没有反义关系。"}, {"text": "雨水", "is_correct": false, "explanation": "“雨水”是自然现象名词，与“原先”不构成反义。"}, {"text": "石头", "is_correct": false, "explanation": "“石头”是物体名词，与“原先”没有反义关系。"}], "correct_answer": "现在", "explanations": {"现在": "“现在”与“原先”在时间上相对，分别指当前和以前的情况，构成反义。", "书包": "“书包”是物品名词，与“原先”没有反义关系。", "雨水": "“雨水”是自然现象名词，与“原先”不构成反义。", "石头": "“石头”是物体名词，与“原先”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96799, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在现在以前，本来的时候。", "primary_collocate": null, "pronunciation": "yuán xiān", "ipa": "ɥɛn˧˥ ɕjɛn˥˥", "syllable_count": 2, "sentences": [{"text": "这里的变化很大，和原先完全不一样。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把房间收拾得和原先一样。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还是喜欢原先的老房子。", "target_word": "原先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店比原先干净多了。", "target_word": "原先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在的价格已经不是原先的价格了。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司搬走以后，原先的办公室空着。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把椅子放回原先的位置。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语比原先好多了。", "target_word": "原先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她还住在原先的那个小区。", "target_word": "原先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过修理，这辆车跟原先一样好。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指现在以前本来的状态或样子，常作定语或与“和／比／跟”连用，如“原先的位置”“和原先一样”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca46de64-fa79-4631-af35-c977a98316fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96799, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原先", "is_correct": true, "explanation": "原先指现在以前的状态，与“变化很大”所描述的前后对比相符，句意通顺。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指尚未发生的时间，而句中的“变化”已经发生，两者不能作比较。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“年纪”指人的岁数，不能用来与一个地方的变化状态作比较。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”指称呼，与“变化很大”这一描述无关，句意不通。"}], "explanations": {"原先": "原先指现在以前的状态，与“变化很大”所描述的前后对比相符，句意通顺。", "将来": "语义：“将来”指尚未发生的时间，而句中的“变化”已经发生，两者不能作比较。", "年纪": "搭配：“年纪”指人的岁数，不能用来与一个地方的变化状态作比较。", "名字": "语义：“名字”指称呼，与“变化很大”这一描述无关，句意不通。"}, "sentence_index": 0, "correct_answer": "原先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "原先吃完饭以后，他去散步。", "explanation": "这里应该用〈然后〉。“原先”指现在以前的状态，不能用来表示先后相继的动作。"}, {"text": "原先你就是小王啊！", "explanation": "这里应该用〈原来〉，表示恍然发现真相的语气。“原先”只说现在以前的状态，不能表达恍然大悟的语气。"}, {"text": "原先我们下个月再见面吧。", "explanation": "这里应该用〈以后〉。“原先”指现在以前的情况，不能用来安排将来的事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96799, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原先", "is_correct": true, "explanation": "原先指原来的位置，与“放回”要求回到原处的意思相符。"}, {"text": "现在", "is_correct": false, "explanation": "语义：“放回”要求恢复到原来的地方，而“现在的位置”指当前所在，两者矛盾。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“位置”可以搭配物体或地点，“人口”指人的数量，不能与“位置”搭配。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”是一段时间，不指空间位置，句意不通。"}], "explanations": {"原先": "原先指原来的位置，与“放回”要求回到原处的意思相符。", "现在": "语义：“放回”要求恢复到原来的地方，而“现在的位置”指当前所在，两者矛盾。", "人口": "搭配：“位置”可以搭配物体或地点，“人口”指人的数量，不能与“位置”搭配。", "下午": "语义：“下午”是一段时间，不指空间位置，句意不通。"}, "sentence_index": 6, "correct_answer": "原先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "原先这份工作会更顺利。", "explanation": "这里应该用〈今后〉。“原先”指现在以前的情况，不能用来描述将来的状态。"}, {"text": "原先我们会修好这里的路。", "explanation": "这里应该用〈明年〉。“原先”指过去的状态，不能用来说尚未发生的修路计划。"}, {"text": "原先这座城市会更美。", "explanation": "这里应该用〈未来〉。“原先”只指现在以前的情况，不能用于未来的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96799, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间还是原先样子。", "corrected_sentence": "这个房间还是原先的样子。", "error_description": "“原先”作定语修饰“样子”时，中间要加“的”，应说“原先的样子”。漏掉“的”，句子不符合规范的说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96799, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家小店的门口还是原先得模样。", "corrected_sentence": "那家小店的门口还是原先的模样。", "error_description": "“原先”作定语修饰“模样”，中间应用助词“的”，写成“原先得模样”误用了“得”。“得”不能表示定语关系，应说“原先的模样”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
