INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96800, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "起初；先前。", "primary_collocate": null, "pronunciation": "yuán xiān", "ipa": "ɥɛn˧˥ ɕjɛn˥˥", "syllable_count": 2, "sentences": [{"text": "原先我不喜欢吃辣，现在天天吃。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他原先住在北京，后来搬到了上海。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我原先以为今天会下雨。", "target_word": "原先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "原先这里是一片小树林。", "target_word": "原先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她原先不会游泳，现在游得很好。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们原先打算坐火车去。", "target_word": "原先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "原先大家都不同意，后来慢慢同意了。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他原先在银行工作，现在开了一家饭馆。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟原先很怕狗，现在天天陪它玩。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路原先很窄，后来修宽了。", "target_word": "原先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在动词或句首作状语，表示起初、先前的情况，后面常有“后来／现在”对比，如“原先住在北京，后来搬走了”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca46de64-fa79-4631-af35-c977a98316fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原先", "is_correct": true, "explanation": "“原先”作副词，表示起初的情况，与后句“现在天天吃”形成前后对比。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作进行中，不能修饰“不喜欢”这类心理状态，句意不通。"}, {"text": "常常", "is_correct": false, "explanation": "语义：“常常”表示反复发生，不能说明由不喜欢到现在天天吃的转变。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”多修饰即刻发生的动作，不能修饰“不喜欢”这类持续的心理状态。"}], "explanations": {"原先": "“原先”作副词，表示起初的情况，与后句“现在天天吃”形成前后对比。", "正在": "语义：“正在”表示动作进行中，不能修饰“不喜欢”这类心理状态，句意不通。", "常常": "语义：“常常”表示反复发生，不能说明由不喜欢到现在天天吃的转变。", "立刻": "搭配：“立刻”多修饰即刻发生的动作，不能修饰“不喜欢”这类持续的心理状态。"}, "sentence_index": 0, "correct_answer": "原先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "原先如果你来，我们就去吃饭。", "explanation": "这里应该去掉〈原先〉。“原先”指现在以前实际存在的状况，不能用在“如果……就……”这样的假设句里。"}, {"text": "原先你快回来吧！", "explanation": "这里应该用〈现在〉。“原先”指过去的情况，不能用于当下的催促。"}, {"text": "原先现在这里是一片公园。", "explanation": "这里应该只用〈现在〉。“原先”指现在以前，与“现在”矛盾，不能并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原先", "is_correct": true, "explanation": "“原先”作副词，表示起初的情况，与后句“后来慢慢同意了”的转变相符。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一直如此，与后句“后来慢慢同意了”的转变矛盾。"}, {"text": "赶快", "is_correct": false, "explanation": "语义：“赶快”表示迅速行动，不能修饰“不同意”这种态度，句意不通。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”多用于即将发生的动作，不能修饰“都不同意”这种已经存在的态度。"}], "explanations": {"原先": "“原先”作副词，表示起初的情况，与后句“后来慢慢同意了”的转变相符。", "始终": "语义：“始终”表示一直如此，与后句“后来慢慢同意了”的转变矛盾。", "赶快": "语义：“赶快”表示迅速行动，不能修饰“不同意”这种态度，句意不通。", "马上": "搭配：“马上”多用于即将发生的动作，不能修饰“都不同意”这种已经存在的态度。"}, "sentence_index": 6, "correct_answer": "原先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "原先请大家马上让路！", "explanation": "这里应该用〈现在〉。“原先”指过去的情况，不能用于当下的即时指令。"}, {"text": "原先将来这条路会很宽。", "explanation": "这里应该只用〈将来〉。“原先”指过去，与“将来”矛盾，不能并用。"}, {"text": "原先我明年会去国外读书。", "explanation": "这里应该去掉〈原先〉，直接说〈明年〉。“原先”指过去，不能和将来的时间“明年”一起用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的原先很胖，现在瘦了。", "corrected_sentence": "他原先很胖，现在瘦了。", "error_description": "“原先”是副词，前面不能加结构助词“的”。应说“他原先很胖”，“他的原先很胖”中“的”用法错误，不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈原先原先在医院上班，后来调到了学校。", "corrected_sentence": "我妈妈原先在医院上班，后来调到了学校。", "error_description": "“原先”在句中重复出现了两次，应只用一次。正确说法是“我妈妈原先在医院上班”，“原先原先”属于重复错误，不合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
