INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96801, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96801, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在学校里要学的一门一门的课。", "primary_collocate": null, "pronunciation": "kē mù", "ipa": "kʰɤ˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "你最喜欢哪一门科目？", "target_word": "科目", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们学校一共有八门科目。", "target_word": "科目", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数学是我最难的科目。", "target_word": "科目", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个学期他选了三门科目。", "target_word": "科目", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试以前，我要复习所有的科目。", "target_word": "科目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，语文是最重要的科目。", "target_word": "科目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪门科目的作业最多？", "target_word": "科目", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明的体育科目成绩很好。", "target_word": "科目", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她这次考试的三个科目都及格了。", "target_word": "科目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢英语这个科目，因为单词太多。", "target_word": "科目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "考试科目", "label": "复合"}, {"form": "选修科目", "label": "复合"}, {"form": "门", "label": "量词"}], "register": "中性", "sense_fingerprint": "学校里要学的一门门课程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba7539fe-b5aa-4d48-a3b7-ff2bf389d79f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96801, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科目", "is_correct": true, "explanation": "正确。“门”是学科的量词，“哪一门科目”问的是学校里要学的课程。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是学校里要学的课程，与“最喜欢哪一门”无关。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“门”计量学科和课程，不能计量人，所以不说“哪一门老师”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“门”不计量颜色，“哪一门颜色”不成立，应说“哪一种颜色”。"}], "explanations": {"科目": "正确。“门”是学科的量词，“哪一门科目”问的是学校里要学的课程。", "天气": "语义：天气不是学校里要学的课程，与“最喜欢哪一门”无关。", "老师": "搭配：“门”计量学科和课程，不能计量人，所以不说“哪一门老师”。", "颜色": "搭配：“门”不计量颜色，“哪一门颜色”不成立，应说“哪一种颜色”。"}, "sentence_index": 0, "correct_answer": "科目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都带着科目上学。", "explanation": "这里应该用〈课本〉。课本是可以带在身上的书，科目是学习的学科，不是实物，不能带着上学。"}, {"text": "她今年加入了两个科目。", "explanation": "这里应该用〈社团〉。加入的是社团或组织，科目是学习的学科，不能用“加入”。"}, {"text": "他每天晚上都看科目。", "explanation": "这里应该用〈节目〉。看的是节目，科目是学习的学科，不能用“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96801, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科目", "is_correct": true, "explanation": "正确。“哪门科目”指学校的课程，“门”是学科的量词。"}, {"text": "老师", "is_correct": false, "explanation": "搭配：“门”计量学科，不能计量人，“哪门老师”不成立。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的场所，不是学科，问“哪门教室的作业最多”没有意义。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜与作业无关，不是学校里要学的课程。"}], "explanations": {"科目": "正确。“哪门科目”指学校的课程，“门”是学科的量词。", "老师": "搭配：“门”计量学科，不能计量人，“哪门老师”不成立。", "教室": "语义：教室是上课的场所，不是学科，问“哪门教室的作业最多”没有意义。", "饭菜": "语义：饭菜与作业无关，不是学校里要学的课程。"}, "sentence_index": 6, "correct_answer": "科目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天放学后要写科目。", "explanation": "这里应该用〈作业〉。“写”的对象是作业，科目是学习的学科，不能用来写。"}, {"text": "同学们在科目上认真听讲。", "explanation": "这里应该用〈课堂〉。“在课堂上听讲”指上课的地方和场合；科目是学习的学科，不能说“在科目上听讲”。"}, {"text": "我们今天做了一个科目。", "explanation": "这里应该用〈实验〉。做的是活动，科目是学科，不是可以做的事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96801, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些科目们都很难学。", "corrected_sentence": "这些科目都很难学。", "error_description": "“科目”指学校的课程，是无生命的事物，不能加“们”表示复数；应说“这些科目”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96801, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这学期要学两本科目。", "corrected_sentence": "他这学期要学两门科目。", "error_description": "“科目”指学校的课程，量词应用“门”，不能用“本”（“本”多用于书册）；应说“两门科目”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
