INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "账目的分类项目。", "primary_collocate": null, "pronunciation": "kē mù", "ipa": "kʰɤ˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "会计要把每笔钱记到对应的科目里。", "target_word": "科目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工资应该记在哪个科目？", "target_word": "科目", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔费用的科目写错了。", "target_word": "科目", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你看一下账本上的科目。", "target_word": "科目", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会计科目分为资产、负债和成本等。", "target_word": "科目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公用品的钱属于管理费用这个科目。", "target_word": "科目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收入和支出要分成不同的科目。", "target_word": "科目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在账本里列了十个收入科目。", "target_word": "科目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个科目的余额是五千元。", "target_word": "科目", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "财务人员按科目整理发票，再交给经理。", "target_word": "科目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "会计科目", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "会计账目的分类项目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba7539fe-b5aa-4d48-a3b7-ff2bf389d79f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科目", "is_correct": true, "explanation": "正确。科目指账目的分类项目，记账时要把每笔款项记入对应的科目。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是账目的分类，钱不能记到厨房里。"}, {"text": "树林", "is_correct": false, "explanation": "语义：树林是自然环境，与会计记账无关，不能作为款项的归属。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开门的工具，不是账目的分类，钱不能记到钥匙里。"}], "explanations": {"科目": "正确。科目指账目的分类项目，记账时要把每笔款项记入对应的科目。", "厨房": "语义：厨房是做饭的地方，不是账目的分类，钱不能记到厨房里。", "树林": "语义：树林是自然环境，与会计记账无关，不能作为款项的归属。", "钥匙": "语义：钥匙是开门的工具，不是账目的分类，钱不能记到钥匙里。"}, "sentence_index": 0, "correct_answer": "科目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这笔钱要存入客户的科目。", "explanation": "这里应该用〈账户〉。存款要存入账户；科目是账目的分类项目，不能用“存入”。"}, {"text": "会计每个月都给这个科目发工资。", "explanation": "这里应该用〈员工〉。工资发给人，科目是账目的分类，不能接收工资。"}, {"text": "字典里每个字都有一个科目。", "explanation": "这里应该用〈词条〉。词条是字典里解释字词的条目；科目是账目的分类，不能用来指字典中的条目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科目", "is_correct": true, "explanation": "正确。“分成不同的科目”指把收入和支出分到不同的账目分类里。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：收入和支出是账目的内容，不能分成不同的颜色。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“分成”后接的应是可以划分的类别，“分成不同的座位”与“收入和支出”搭配不当。"}, {"text": "语言", "is_correct": false, "explanation": "语义：收入和支出是财务内容，与语言无关，不能分成不同的语言。"}], "explanations": {"科目": "正确。“分成不同的科目”指把收入和支出分到不同的账目分类里。", "颜色": "语义：收入和支出是账目的内容，不能分成不同的颜色。", "座位": "搭配：“分成”后接的应是可以划分的类别，“分成不同的座位”与“收入和支出”搭配不当。", "语言": "语义：收入和支出是财务内容，与语言无关，不能分成不同的语言。"}, "sentence_index": 6, "correct_answer": "科目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在财务科目上班。", "explanation": "这里应该用〈科室〉。科室是办公的部门，可以说“在财务科室上班”；科目是账目的分类，不能作为工作的地方。"}, {"text": "这本书的科目很详细。", "explanation": "这里应该用〈目录〉。目录列出书籍的章节和页码，科目指账目的分类，不能用来描述书的内容列表。"}, {"text": "这个科目下个月来公司面试。", "explanation": "这里应该用〈应聘者〉。应聘者是来面试的人，科目是账目的分类，不能来公司面试。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些科目们都要重新核对一遍。", "corrected_sentence": "这些科目都要重新核对一遍。", "error_description": "“科目”是账目的分类，是无生命的事物，不能加“们”表示复数；应说“这些科目”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会计整理了两本科目。", "corrected_sentence": "会计整理了两个科目。", "error_description": "“科目”指账目的分类，量词应用“个”，不能用“本”（“本”多用于书册）；应说“两个科目”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
