INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96803, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "还有另一个名字叫做。", "primary_collocate": null, "pronunciation": "yòu chēng", "ipa": "joʊ˥˩ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "西红柿又称番茄。", "target_word": "又称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆又称马铃薯。", "target_word": "又称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节又称过年。", "target_word": "又称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中秋节又称团圆节。", "target_word": "又称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大熊猫又称猫熊。", "target_word": "又称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米又称苞米。", "target_word": "又称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "泰山又称东岳。", "target_word": "又称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菠萝又称凤梨。", "target_word": "又称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "端午节又称端阳节。", "target_word": "又称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香菜又称芫荽。", "target_word": "又称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "还有另一个名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 荽 (Zipf 1.75)']::text[], '1f797344-34e1-4b24-8621-ea8ced756a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96803, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”的施事必须能拒绝别人，“西红柿”不能拒绝“番茄”，句子说不通。"}, {"text": "又称", "is_correct": true, "explanation": "正确：“又称”表示“还有另一个名字是”，符合“西红柿”和“番茄”之间的关系。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”的宾语应是数量或程度，不能说“增加番茄”这类事物名称。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”需要有感情的主语，“西红柿喜欢番茄”不成立。"}], "explanations": {"拒绝": "语义：“拒绝”的施事必须能拒绝别人，“西红柿”不能拒绝“番茄”，句子说不通。", "又称": "正确：“又称”表示“还有另一个名字是”，符合“西红柿”和“番茄”之间的关系。", "增加": "搭配：“增加”的宾语应是数量或程度，不能说“增加番茄”这类事物名称。", "喜欢": "语义：“喜欢”需要有感情的主语，“西红柿喜欢番茄”不成立。"}, "sentence_index": 0, "correct_answer": "又称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书又称三百页。", "explanation": "这里应该用〈有〉。“又称”只能引出事物的另一个名字，不能用来说明页数；表示具有多少页要用“有”。"}, {"text": "这个房间又称二十平方米。", "explanation": "这里应该用〈有〉。“又称”只能引出事物的另一个名字，不能用来说明面积；表示有多大要用“有”。"}, {"text": "这条路又称一公里。", "explanation": "这里应该用〈有〉。“又称”只能引出另一个名字，不能用来说明长度；表示有多长要用“有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抢夺", "is_correct": false, "explanation": "语义：“抢夺”的施事必须是能抢东西的人，“泰山抢夺东岳”说不通。"}, {"text": "又称", "is_correct": true, "explanation": "正确：“又称”表示“另有一个名字是”，“泰山”与“东岳”正是同一座山的两个名称。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”的宾语应是水平、质量，不能用地名“东岳”作宾语。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”的主语应是人，“泰山嫌弃东岳”不符合常理。"}], "explanations": {"抢夺": "语义：“抢夺”的施事必须是能抢东西的人，“泰山抢夺东岳”说不通。", "又称": "正确：“又称”表示“另有一个名字是”，“泰山”与“东岳”正是同一座山的两个名称。", "提高": "搭配：“提高”的宾语应是水平、质量，不能用地名“东岳”作宾语。", "嫌弃": "语义：“嫌弃”的主语应是人，“泰山嫌弃东岳”不符合常理。"}, "sentence_index": 6, "correct_answer": "又称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个西瓜又称十斤。", "explanation": "这里应该用〈有〉。“又称”只能引出另一个名字，不能用来说明重量；表示有多重要用“有”。"}, {"text": "这盒饼干又称十二块。", "explanation": "这里应该用〈有〉。“又称”只能引出另一个名字，不能用来说明数量；表示有多少要用“有”。"}, {"text": "这根绳子又称两米长。", "explanation": "这里应该用〈有〉。“又称”只能引出另一个名字，不能用来说明长度；表示有多长要用“有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地瓜又称叫红薯。", "corrected_sentence": "地瓜又称红薯。", "error_description": "错误形式：“又称”后面多加了动词“叫”。“又称”本身已表示“又叫做”，不能再叠加动词。正确形式：“地瓜又称红薯。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "长城又称了万里长城。", "corrected_sentence": "长城又称万里长城。", "error_description": "错误形式：“又称”后面多加了“了”。“又称”表示恒常的另一个名称，不能带“了”。正确形式：“长城又称万里长城。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
