INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96807, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叫很多人到一个地方来。", "primary_collocate": null, "pronunciation": "zhào jí", "ipa": "ʈʂɑʊ̯˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "消防队长召集队员们赶到火灾现场。", "target_word": "召集", "complexity_tier": "T3", "furigana": "xiāofáng duìzhǎng zhàojí duìyuánmen gǎndào huǒzāi xiànchǎng。", "sentence_source": "generated"}, {"text": "老王召集了十几位村民到村委会。", "target_word": "召集", "complexity_tier": "T3", "furigana": "lǎo wáng zhàojí le shíjǐ wèi cūnmín dào cūnwěihuì。", "sentence_source": "generated"}, {"text": "社区召集居民到活动中心听讲座。", "target_word": "召集", "complexity_tier": "T3", "furigana": "shèqū zhàojí jūmín dào huódòng zhōngxīn tīng jiǎngzuò。", "sentence_source": "generated"}, {"text": "总经理召集各部门负责人到会议室。", "target_word": "召集", "complexity_tier": "T3", "furigana": "zǒngjīnglǐ zhàojí gè bùmén fùzérén dào huìyìshì。", "sentence_source": "generated"}, {"text": "小李召集大家到操场上集合。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一喊，就召集了一群人。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师召集大家到楼下排队。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员召集附近的居民到安全地带集合。", "target_word": "召集", "complexity_tier": "T3", "furigana": "xiāofángyuán zhàojí fùjìn de jūmín dào ānquán dìdài jíhé。", "sentence_source": "generated"}, {"text": "爸爸召集亲戚们回老家过年。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练召集球员们到训练场集合。", "target_word": "召集", "complexity_tier": "T3", "furigana": "jiàoliàn zhàojí qiúyuánmen dào xùnliànchǎng jíhé。", "sentence_source": "generated"}], "morphological_forms": [{"form": "召集了", "label": "体标"}, {"form": "召集过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把许多人叫到某个地点来集合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca46de64-fa79-4631-af35-c977a98316fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96807, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "召集", "is_correct": true, "explanation": "正确。“召集”指把人叫到某地来，与“赶到火灾现场”相合。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语应是活动或组织，不能接“队员们赶到火灾现场”这样的小句。"}, {"text": "驱散", "is_correct": false, "explanation": "语义：“驱散”是使人四散，与“赶到火灾现场”的集中行动相反。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”是丢下不管，与消防队长带队员赶赴火灾现场的救援行动不符。"}], "explanations": {"召集": "正确。“召集”指把人叫到某地来，与“赶到火灾现场”相合。", "参加": "配价：“参加”的宾语应是活动或组织，不能接“队员们赶到火灾现场”这样的小句。", "驱散": "语义：“驱散”是使人四散，与“赶到火灾现场”的集中行动相反。", "抛弃": "语义：“抛弃”是丢下不管，与消防队长带队员赶赴火灾现场的救援行动不符。"}, "sentence_index": 0, "correct_answer": "召集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校召集了一场比赛，很多同学都来看。", "explanation": "这里应该用〈组织〉。召集的对象是人，比赛这类活动要说组织。"}, {"text": "他召集了很多邮票，每天都拿出来看。", "explanation": "这里应该用〈收藏〉。召集的对象是人，邮票这类物品要说收藏。"}, {"text": "社区召集了一块地修操场。", "explanation": "这里应该用〈选〉。召集的对象是人或会议，“一块地”要说选。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96807, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "召集", "is_correct": true, "explanation": "正确。“召集”指把人叫到某地来，与“到楼下排队”相合。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是场所或展览，不能以“大家”作宾语。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”是让人离开工作岗位，与“大家到楼下排队”的指令不符。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：“逃离”是躲开、离开，与排队集合的行为相反。"}], "explanations": {"召集": "正确。“召集”指把人叫到某地来，与“到楼下排队”相合。", "参观": "配价：“参观”的宾语是场所或展览，不能以“大家”作宾语。", "辞退": "语义：“辞退”是让人离开工作岗位，与“大家到楼下排队”的指令不符。", "逃离": "语义：“逃离”是躲开、离开，与排队集合的行为相反。"}, "sentence_index": 6, "correct_answer": "召集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教练召集了更衣室，把球衣叠好放进柜子。", "explanation": "这里应该用〈收拾〉。召集的对象是人，更衣室这类房间要说收拾。"}, {"text": "教练召集了散落的球，放回筐里。", "explanation": "这里应该用〈收拢〉。召集的对象是人，散落的球要说收拢。"}, {"text": "教练召集了一辆出租车送大家回家。", "explanation": "这里应该用〈叫〉。召集的对象是人，叫出租车要说叫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96807, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正召集了几位朋友到家里聚餐。", "corrected_sentence": "他正召集几位朋友到家里聚餐。", "error_description": "错误：“正召集了几位朋友”。“正”表示动作正在进行，与表示完成的“了”矛盾；应去掉“了”，说“他正召集几位朋友到家里聚餐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96807, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "教练召集得球员们到训练场集合。", "corrected_sentence": "教练召集了球员们到训练场集合。", "error_description": "错误：“召集得球员们”。“得”不能表示动作完成，表示完成应用“了”；正确是“召集了球员们到训练场集合”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
