INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96808, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通知人们聚集起来。", "primary_collocate": null, "pronunciation": "zhào jí", "ipa": "ʈʂɑʊ̯˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "学校召集全体老师开会。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理召集大家讨论新计划。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长召集村民商量修路的事。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长召集同学们去打扫教室。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司明天召集各部门负责人开会。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师召集了几个学生参加比赛。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们召集了会议，讨论这个问题。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长召集专家商量办法。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长召集学生代表谈话。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长召集队员们开始训练。", "target_word": "召集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "召集了", "label": "体标"}, {"form": "召集过", "label": "体标"}], "register": "书面", "sense_fingerprint": "负责人正式通知众人聚在一起开会或商量事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca46de64-fa79-4631-af35-c977a98316fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "召集", "is_correct": true, "explanation": "正确。“召集”指把人叫到一起，与“全体老师开会”相合。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语是活动或组织，不能以“全体老师”作宾语。"}, {"text": "驱散", "is_correct": false, "explanation": "语义：“驱散”是使人散开，与“开会”需要聚集相反。"}, {"text": "解散", "is_correct": false, "explanation": "语义：“解散”是让集体散开，与“全体老师开会”相矛盾。"}], "explanations": {"召集": "正确。“召集”指把人叫到一起，与“全体老师开会”相合。", "参加": "配价：“参加”的宾语是活动或组织，不能以“全体老师”作宾语。", "驱散": "语义：“驱散”是使人散开，与“开会”需要聚集相反。", "解散": "语义：“解散”是让集体散开，与“全体老师开会”相矛盾。"}, "sentence_index": 0, "correct_answer": "召集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们召集了一次春游，大家都很开心。", "explanation": "这里应该用〈组织〉。召集的对象是人或会议，春游这类活动要说组织。"}, {"text": "妈妈召集了一些旧衣服，准备送到山区。", "explanation": "这里应该用〈收集〉。召集的对象是人，旧衣服这类物品要说收集。"}, {"text": "他召集了一封信，寄给了朋友。", "explanation": "这里应该用〈写〉。召集的对象是人或会议，信件要说写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "召集", "is_correct": true, "explanation": "正确。“召集了会议”是常见搭配，符合“讨论这个问题”的语境。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”用于建筑、设施，不能说“拆除会议”。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的宾语是场所或展览，会议不能作参观的对象。"}, {"text": "抗议", "is_correct": false, "explanation": "语义：“抗议”表示反对，与“讨论这个问题”的正常会议不相符。"}], "explanations": {"召集": "正确。“召集了会议”是常见搭配，符合“讨论这个问题”的语境。", "拆除": "搭配：“拆除”用于建筑、设施，不能说“拆除会议”。", "参观": "配价：“参观”的宾语是场所或展览，会议不能作参观的对象。", "抗议": "语义：“抗议”表示反对，与“讨论这个问题”的正常会议不相符。"}, "sentence_index": 6, "correct_answer": "召集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他召集了散落在桌上的纸，整齐地放进文件夹。", "explanation": "这里应该用〈收拢〉。召集的对象是人或会议，散落在桌上的纸要说收拢。"}, {"text": "姐姐召集了房间，把玩具一件件摆好。", "explanation": "这里应该用〈收拾〉。召集不能用于房间，整理房间要说收拾。"}, {"text": "他召集了一些零钱，够付车费了。", "explanation": "这里应该用〈凑〉。召集的对象是人，零钱这类钱款要说凑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长召集得全体教师开会。", "corrected_sentence": "校长召集了全体教师开会。", "error_description": "错误：“召集得全体教师”。“得”不能表示动作完成，表示完成应用“了”；正确是“召集了全体教师开会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "队长把队员们召集起了来，开始训练。", "corrected_sentence": "队长把队员们召集了起来，开始训练。", "error_description": "错误形式：“召集起了来”。正确形式：“召集了起来”。“起来”是召集的结果补语，不能拆开；“了”应紧跟动词“召集”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
