INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96809, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "交钱，把别人的东西借来用一段时间。", "primary_collocate": null, "pronunciation": "zū lìn", "ipa": "tsu˥ lin˥˩", "syllable_count": 2, "sentences": [{"text": "我们租赁了一间小办公室。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月交钱租赁一辆车。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司租赁设备，不用自己买。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生可以租赁自行车，一天十元。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她租赁过一套房子，住了两年。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想租赁一台相机去旅行。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先交押金，再租赁帆船出海。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民租赁了别人的土地种菜。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们租赁一辆大车搬家。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租赁手机要先交钱，用完再还。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "租赁了", "label": "体标"}, {"form": "租赁过", "label": "体标"}, {"form": "租赁合同", "label": "复合词"}, {"form": "租賃", "label": "繁体"}], "register": "书面", "sense_fingerprint": "付钱借用他人物品一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c67bcbe8-38ec-4a35-acf2-3747b2cdd35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "租赁", "is_correct": true, "explanation": "租赁：付钱借用一段时间，与“一间小办公室”的使用语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃办公室”。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带宾语“办公室”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语应是歌曲，不能说“唱办公室”。"}], "explanations": {"租赁": "租赁：付钱借用一段时间，与“一间小办公室”的使用语境相符。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃办公室”。", "睡": "配价：“睡”是不及物动词，不能带宾语“办公室”。", "唱": "搭配：“唱”的宾语应是歌曲，不能说“唱办公室”。"}, "sentence_index": 0, "correct_answer": "租赁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朋友不收钱，我向他租赁了一辆自行车。", "explanation": "这里应该用〈借〉。租赁要付钱，句中说朋友不收钱，应用〈借〉。"}, {"text": "我向银行租赁了一笔钱，下个月还。", "explanation": "这里应该用〈贷款〉。租赁只用于物品的使用权，借钱要用〈贷款〉。"}, {"text": "这家公司租赁了一套员工培训课程，每年付一次费用。", "explanation": "这里应该用〈订购〉。租赁用于物品或场所的使用权，课程是服务，应说“订购”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "租赁", "is_correct": true, "explanation": "租赁：先交押金、付费使用帆船，与句中“交押金”相符。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”表示转让所有权，船卖掉以后就不能再出海，与句意矛盾。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮料，不能说“喝帆船”。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带宾语“帆船”。"}], "explanations": {"租赁": "租赁：先交押金、付费使用帆船，与句中“交押金”相符。", "卖": "语义：“卖”表示转让所有权，船卖掉以后就不能再出海，与句意矛盾。", "喝": "搭配：“喝”的宾语应是饮料，不能说“喝帆船”。", "笑": "配价：“笑”是不及物动词，不能带宾语“帆船”。"}, "sentence_index": 6, "correct_answer": "租赁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于租赁到了一份好工作。", "explanation": "这里应该用〈找〉。租赁只用于物品或场所，工作不能租赁，应用〈找〉。"}, {"text": "他把友情租赁给了别人。", "explanation": "这里应该用〈交〉。友情不能出租，应说“把友情交给了别人”。"}, {"text": "我们租赁了一个星期的好天气。", "explanation": "这里应该用〈享受〉。租赁用于物品或场所，天气不能租赁，应用〈享受〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想租赁了一辆自行车去公园。", "corrected_sentence": "我想租赁一辆自行车去公园。", "error_description": "体标错误：“想”表示意愿，后面不能直接接“了”，应去掉“了”。正确说法：我想租赁一辆自行车去公园。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每个月交一千块，租赁了一位邻居。", "corrected_sentence": "我每个月交一千块，租赁了一间公寓。", "error_description": "搭配错误：“租赁”的对象应是物品或场所，不能是人。正确说法：租赁了一间公寓。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
