INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96810, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以付租金的方式取得物品的使用权。", "primary_collocate": null, "pronunciation": "zū lìn", "ipa": "tsu˥ lin˥˩", "syllable_count": 2, "sentences": [{"text": "学校付租金，租赁了这块场地。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司按月付租金租赁仓库。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们租赁这台机器已经三年了。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂租赁了新设备，每年付租金。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们租赁那间店面开了咖啡馆。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店租赁着一栋旧楼。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他租赁了一块土地，每年按时交租金。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想租赁十辆车给员工用。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府租赁过这座大楼办公。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把租赁的车还给了公司。", "target_word": "租赁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "租赁了", "label": "体标"}, {"form": "租赁着", "label": "体标"}, {"form": "租赁过", "label": "体标"}, {"form": "租赁公司", "label": "复合词"}, {"form": "租賃", "label": "繁体"}], "register": "书面", "sense_fingerprint": "付租金取得物品使用权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c67bcbe8-38ec-4a35-acf2-3747b2cdd35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "租赁", "is_correct": true, "explanation": "租赁：学校付租金取得场地的使用权，与“付租金”相符。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”表示所有权，与句中“付租金”的使用关系矛盾。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”会获得所有权，与“付租金”的租用关系矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语应是歌曲，不能说“唱这块场地”。"}], "explanations": {"租赁": "租赁：学校付租金取得场地的使用权，与“付租金”相符。", "拥有": "语义：“拥有”表示所有权，与句中“付租金”的使用关系矛盾。", "购买": "语义：“购买”会获得所有权，与“付租金”的租用关系矛盾。", "唱": "搭配：“唱”的宾语应是歌曲，不能说“唱这块场地”。"}, "sentence_index": 0, "correct_answer": "租赁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朋友说不用付钱，我就租赁了他的书。", "explanation": "这里应该用〈借〉。租赁要付租金，句中说不用付钱，应用〈借〉。"}, {"text": "公司每月付工资，租赁了三名员工。", "explanation": "这里应该用〈雇〉。租赁用于物品或场所，雇人要用〈雇〉。"}, {"text": "工厂花钱租赁了新的管理经验，每年按时付租金。", "explanation": "这里应该用〈学习〉。租赁只用于有形物品或场所，管理经验是抽象的知识，应用〈学习〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "租赁", "is_correct": true, "explanation": "租赁：付租金取得土地的使用权，与“每年交租金”相符。"}, {"text": "卖", "is_correct": false, "explanation": "语义：卖出土地就不需要每年交租金，与句意矛盾。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮料，不能说“喝土地”。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带宾语“土地”。"}], "explanations": {"租赁": "租赁：付租金取得土地的使用权，与“每年交租金”相符。", "卖": "语义：卖出土地就不需要每年交租金，与句意矛盾。", "喝": "搭配：“喝”的宾语应是饮料，不能说“喝土地”。", "笑": "配价：“笑”是不及物动词，不能带宾语“土地”。"}, "sentence_index": 6, "correct_answer": "租赁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于租赁到了一份好工作。", "explanation": "这里应该用〈找〉。租赁只用于物品或场所，工作不能租赁，应用〈找〉。"}, {"text": "我们租赁了一段美好的回忆。", "explanation": "这里应该用〈留〉。回忆不能出租，应说“留下一段美好的回忆”。"}, {"text": "我每天都租赁一大口新鲜空气。", "explanation": "这里应该用〈呼吸〉。空气不是可以出租的物品，应用〈呼吸〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司每年付租金，租赁了一份报告。", "corrected_sentence": "这家公司每年付租金，租赁了一间仓库。", "error_description": "搭配错误：“租赁”的对象应是场所或物品，不能是“报告”。正确说法：租赁了一间仓库。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每年按时交租金，租赁给了一块草地。", "corrected_sentence": "他们每年按时交租金，租赁了一块草地。", "error_description": "语义错误：“租赁给”是出租方的动作，句中是承租方交租金，应去掉“给”。正确说法：租赁了一块草地。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
