INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96811, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "abstract", "definition": "在同一段时间。", "primary_collocate": null, "pronunciation": "tóng qī", "ipa": "tʰʊŋ˧˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "两场比赛同期举行。", "target_word": "同期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "展览和讲座同期举办。", "target_word": "同期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两部电影同期上映，观众很多。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的两个活动同期进行，我只能参加一个。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和哥哥同期出国留学。", "target_word": "同期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的花展和灯会同期开幕。", "target_word": "同期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月书店的两场活动同期开始。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个会议同期召开，酒店都住满了。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节期间，几个庙会同期举行。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个人同期进公司，关系很好。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "同期：副词，指几件事在同一段时间里发生，如同期举行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dce18cdf-2b41-42df-bd93-0b394f53e672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同期", "is_correct": true, "explanation": "同期是副词，表示几件事在同一段时间内发生，“两场比赛同期举行”符合句意。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词或状态，不修饰“举行”这类动作动词，“两场比赛很举行”不成立。"}, {"text": "挺", "is_correct": false, "explanation": "语域：“挺”是口语词，与本句的书面语不合；它同样不能修饰“举行”。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”不能直接修饰“举行”这类动作，“两场比赛非常举行”不说。"}], "explanations": {"同期": "同期是副词，表示几件事在同一段时间内发生，“两场比赛同期举行”符合句意。", "很": "搭配：“很”修饰形容词或状态，不修饰“举行”这类动作动词，“两场比赛很举行”不成立。", "挺": "语域：“挺”是口语词，与本句的书面语不合；它同样不能修饰“举行”。", "非常": "搭配：“非常”不能直接修饰“举行”这类动作，“两场比赛非常举行”不说。"}, "sentence_index": 0, "correct_answer": "同期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我同期喜欢音乐和体育。", "explanation": "这里应该用〈同时〉。同期指几件事在同一段时间里发生，人的爱好不是事件，应说“同时喜欢”。"}, {"text": "他们俩同期聪明，成绩都很好。", "explanation": "这里应该用〈同样〉。同期只表示时间上的同时，不能用来说两人的性质相同。"}, {"text": "这两张桌子同期的高度一模一样。", "explanation": "这里应该用〈相同〉。同期只表示时间上的同时，不能修饰“高度”；说两者一样要用〈相同〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同期", "is_correct": true, "explanation": "同期是副词，表示两场活动在同一时间开始，句中“同期开始”符合句意。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”多修饰形容词，不修饰“开始”，“太开始”不成立。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词或心理动词，不能说“十分开始”。"}, {"text": "一向", "is_correct": false, "explanation": "语义：“一向”表示长期的习惯，与“活动开始”这种一次性事件不合。"}], "explanations": {"同期": "同期是副词，表示两场活动在同一时间开始，句中“同期开始”符合句意。", "太": "搭配：“太”多修饰形容词，不修饰“开始”，“太开始”不成立。", "十分": "搭配：“十分”修饰形容词或心理动词，不能说“十分开始”。", "一向": "语义：“一向”表示长期的习惯，与“活动开始”这种一次性事件不合。"}, "sentence_index": 6, "correct_answer": "同期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和他同期的年龄都是二十岁。", "explanation": "这里应该用〈同龄〉。同期只表示时间上的同时，不能修饰“年龄”；两人年龄相同要说〈同龄〉。"}, {"text": "这两件衣服的颜色同期，都是红色。", "explanation": "这里应该用〈相同〉。同期只表示时间上的同时，不能说明颜色一样；颜色一样要用〈相同〉。"}, {"text": "他们俩同期的身高都是一米八。", "explanation": "这里应该用〈相同〉。同期只表示时间上的同时，不能修饰“身高”；说两人身高一样要用〈相同〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两家公司的同期成立。", "corrected_sentence": "这两家公司同期成立。", "error_description": "词性错误：“同期”是副词，只能直接修饰动词，前面不能加结构助词“的”。正确说法是“同期成立”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个展览很同期开幕。", "corrected_sentence": "这两个展览同期开幕。", "error_description": "副词叠加错误：“同期”前面不能再加“很”，“很同期”不成立。正确说法是“同期开幕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
