INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96812, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同一时期；去年的同一个时间。", "primary_collocate": null, "pronunciation": "tóng qī", "ipa": "tʰʊŋ˧˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "今年的销量比去年同期高。", "target_word": "同期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的雨水比去年同期多。", "target_word": "同期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年一月的游客比去年同期增加了不少。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与去年同期相比，价格没有变化。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年的利润是去年同期的两倍。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天的气温高于往年同期。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的客人比去年同期少了一半。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的客流量比去年同期多了两成。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司今年的营收比去年同期增长了不少。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个季度的出口比去年同期好得多。", "target_word": "同期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "去年同期", "label": "复合"}], "register": "书面语", "sense_fingerprint": "同期：名词，指同一时期，尤指去年的同一个时间，用于对比，如去年同期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dce18cdf-2b41-42df-bd93-0b394f53e672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96812, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同期", "is_correct": true, "explanation": "同期是名词，指去年的同一时间，与“去年”连用，“今年的销量比去年同期高”符合句意。"}, {"text": "前年", "is_correct": false, "explanation": "搭配：“前年”与“去年”都是具体年份，不能连用，“比去年前年高”不成话。"}, {"text": "往年", "is_correct": false, "explanation": "搭配：“去年”已指明一年，后面不能再接泛指多年的“往年”，“去年往年”不说。"}, {"text": "同年", "is_correct": false, "explanation": "搭配：“同年”指同一年，与“去年”的同一时间不是一回事，“比去年同年高”不说。"}], "explanations": {"同期": "同期是名词，指去年的同一时间，与“去年”连用，“今年的销量比去年同期高”符合句意。", "前年": "搭配：“前年”与“去年”都是具体年份，不能连用，“比去年前年高”不成话。", "往年": "搭配：“去年”已指明一年，后面不能再接泛指多年的“往年”，“去年往年”不说。", "同年": "搭配：“同年”指同一年，与“去年”的同一时间不是一回事，“比去年同年高”不说。"}, "sentence_index": 0, "correct_answer": "同期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项工作的同期准备很充分。", "explanation": "这里应该用〈前期〉。前期指一项工作开始的一段时间；同期表示同一时间，不能说明准备的先后阶段。"}, {"text": "这件衣服的同期是红色的。", "explanation": "这里应该用〈颜色〉。同期指时间，不能说明衣服是什么颜色。"}, {"text": "这本书的同期很有意思。", "explanation": "这里应该用〈内容〉。同期指同一时间，不能说明书里写了什么。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同期", "is_correct": true, "explanation": "同期是名词，指去年的同一时间，与“去年”连用，“比去年同期少了一半”符合句意。"}, {"text": "同步", "is_correct": false, "explanation": "语义：“同步”指步调一致、同时进行，不表示时段，“比去年同步”无法用来比较客人数量，句子不通。"}, {"text": "同情", "is_correct": false, "explanation": "语义：“同情”指对他人遭遇的怜悯，与客人数量和时间无关，“比去年同情少了一半”不通。"}, {"text": "季节", "is_correct": false, "explanation": "搭配：“季节”不是可以与“去年”直接对比的时段，“比去年季节少了一半”不说。"}], "explanations": {"同期": "同期是名词，指去年的同一时间，与“去年”连用，“比去年同期少了一半”符合句意。", "同步": "语义：“同步”指步调一致、同时进行，不表示时段，“比去年同步”无法用来比较客人数量，句子不通。", "同情": "语义：“同情”指对他人遭遇的怜悯，与客人数量和时间无关，“比去年同情少了一半”不通。", "季节": "搭配：“季节”不是可以与“去年”直接对比的时段，“比去年季节少了一半”不说。"}, "sentence_index": 6, "correct_answer": "同期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的同期很大，员工也很多。", "explanation": "这里应该用〈规模〉。同期指时间，不能说明公司的大小；谈公司大小要说〈规模〉。"}, {"text": "这个菜的同期太咸了。", "explanation": "这里应该用〈味道〉。同期指时间，不能说明菜咸不咸。"}, {"text": "他的同期很高，有一米九。", "explanation": "这里应该用〈个子〉。同期指时间，不能说明人的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的利润比去年同期高多。", "corrected_sentence": "今年的利润比去年同期高得多。", "error_description": "补语错误：比较句中表示差别大要说“形容词＋得多”，“高多”缺少“得”。正确说法是“比去年同期高得多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个季度的利润比去年很同期高了两成。", "corrected_sentence": "这个季度的利润比去年同期高了两成。", "error_description": "副词错误：“同期”是名词，不能用副词“很”修饰，“很”应去掉。正确说法是“比去年同期高了两成”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e1d7f5c-c87b-4fd9-b652-89523deade0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96813, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱下", "is_correct": true, "explanation": "“脱下”与“穿上”构成反义，指把衣服、鞋子从身上脱掉。"}, {"text": "打开", "is_correct": false, "explanation": "“打开”指使门、盒子等开放，与“穿上”不构成反义。"}, {"text": "拿起", "is_correct": false, "explanation": "“拿起”指用手把东西提起来，与“穿上”不构成反义。"}, {"text": "写下", "is_correct": false, "explanation": "“写下”指用笔把字记录下来，与“穿上”不构成反义。"}], "correct_answer": "脱下", "explanations": {"脱下": "“脱下”与“穿上”构成反义，指把衣服、鞋子从身上脱掉。", "打开": "“打开”指使门、盒子等开放，与“穿上”不构成反义。", "拿起": "“拿起”指用手把东西提起来，与“穿上”不构成反义。", "写下": "“写下”指用笔把字记录下来，与“穿上”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96813, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱下", "is_correct": true, "explanation": "“脱下”与“穿上”构成反义，指把衣服、鞋子从身上脱掉。"}, {"text": "收起", "is_correct": false, "explanation": "“收起”指把展开的东西收拢，与“穿上”不构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指发声演唱，与“穿上”不构成反义。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”指看书学习，与“穿上”不构成反义。"}], "correct_answer": "脱下", "explanations": {"脱下": "“脱下”与“穿上”构成反义，指把衣服、鞋子从身上脱掉。", "收起": "“收起”指把展开的东西收拢，与“穿上”不构成反义。", "唱歌": "“唱歌”指发声演唱，与“穿上”不构成反义。", "读书": "“读书”指看书学习，与“穿上”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96813, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把衣服或鞋子穿在身体上。", "primary_collocate": null, "pronunciation": "chuān shàng", "ipa": "ʈʂʰwan˥ ʂaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "外面很冷，你快穿上外套。", "target_word": "穿上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上新鞋去上学。", "target_word": "穿上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子穿上了红色的毛衣。", "target_word": "穿上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，请穿上雨鞋。", "target_word": "穿上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿上裙子，站在镜子前。", "target_word": "穿上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天冷了，我穿上厚衣服。", "target_word": "穿上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上运动鞋去跑步。", "target_word": "穿上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给弟弟穿上了小皮鞋。", "target_word": "穿上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你穿上这双鞋试试。", "target_word": "穿上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸穿上西装，要去开会。", "target_word": "穿上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿上了", "label": "完成体"}, {"form": "穿上过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把衣服鞋子穿到身上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2d840b2-e5d9-4a1d-acf2-765ae14bc06d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96813, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "穿上", "is_correct": true, "explanation": "“穿上”（chuān shàng）指把衣服、鞋子穿到身上。"}, {"text": "船上", "is_correct": false, "explanation": "chuán（第二声）与 chuān（第一声）声调不同，“船上”指在船里或船面上。"}, {"text": "窗上", "is_correct": false, "explanation": "chuāng 与 chuān 韵母不同（-ang 与 -an），“窗上”指窗户上。"}, {"text": "串上", "is_correct": false, "explanation": "chuàn（第四声）与 chuān（第一声）声调不同，“串上”指把东西穿成一串。"}], "explanations": {"穿上": "“穿上”（chuān shàng）指把衣服、鞋子穿到身上。", "船上": "chuán（第二声）与 chuān（第一声）声调不同，“船上”指在船里或船面上。", "窗上": "chuāng 与 chuān 韵母不同（-ang 与 -an），“窗上”指窗户上。", "串上": "chuàn（第四声）与 chuān（第一声）声调不同，“串上”指把东西穿成一串。"}, "sentence_index": null, "correct_answer": "穿上"}, "level_3": {"options": [{"text": "穿上", "is_correct": true, "explanation": "“穿上”指把外套穿到身上，符合“快穿上外套”的语境。"}, {"text": "脱下", "is_correct": false, "explanation": "语义：“脱下”与“穿上”相反，与“外面很冷”的语境矛盾。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等，不说戴外套。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”用于食物，不能说吃外套。"}], "explanations": {"穿上": "“穿上”指把外套穿到身上，符合“快穿上外套”的语境。", "脱下": "语义：“脱下”与“穿上”相反，与“外面很冷”的语境矛盾。", "戴": "搭配：“戴”用于帽子、眼镜等，不说戴外套。", "吃": "搭配：“吃”用于食物，不能说吃外套。"}, "sentence_index": 0, "correct_answer": "穿上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她穿上眼镜，开始看书。", "explanation": "这里应该用〈戴上〉。眼镜要用“戴”，“穿”只用于衣服、鞋袜等。"}, {"text": "她穿上耳环，准备出门。", "explanation": "这里应该用〈戴上〉。耳环要用“戴”，“穿”只用于衣服、鞋袜等。"}, {"text": "他穿上扣子，走了出去。", "explanation": "这里应该用〈扣上〉。扣子要用“扣”，不能用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validatio