INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96813, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "穿上", "is_correct": true, "explanation": "“穿上”（chuān shàng）指把衣服、鞋子穿到身上。"}, {"text": "闩上", "is_correct": false, "explanation": "shuān 与 chuān 声母不同（sh 与 ch），“闩上”指用门闩把门插上。"}, {"text": "床上", "is_correct": false, "explanation": "chuáng（第二声，-ang）与 chuān（第一声，-an）韵母和声调都不同，“床上”指在床的上面。"}, {"text": "揣上", "is_correct": false, "explanation": "chuāi 与 chuān 韵母不同（-uai 与 -uan），“揣上”指把东西放进怀里或口袋里带着。"}], "explanations": {"穿上": "“穿上”（chuān shàng）指把衣服、鞋子穿到身上。", "闩上": "shuān 与 chuān 声母不同（sh 与 ch），“闩上”指用门闩把门插上。", "床上": "chuáng（第二声，-ang）与 chuān（第一声，-an）韵母和声调都不同，“床上”指在床的上面。", "揣上": "chuāi 与 chuān 韵母不同（-uai 与 -uan），“揣上”指把东西放进怀里或口袋里带着。"}, "sentence_index": null, "correct_answer": "穿上"}, "level_3": {"options": [{"text": "穿上", "is_correct": true, "explanation": "“穿上”指把鞋穿到脚上，符合“穿上运动鞋去跑步”的语境。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指咽下食物，运动鞋不能吞。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”用于果实、花等，不能说摘运动鞋。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与运动鞋毫无关系。"}], "explanations": {"穿上": "“穿上”指把鞋穿到脚上，符合“穿上运动鞋去跑步”的语境。", "吞": "语义：“吞”指咽下食物，运动鞋不能吞。", "摘": "搭配：“摘”用于果实、花等，不能说摘运动鞋。", "唱": "语义：“唱”指发声演唱，与运动鞋毫无关系。"}, "sentence_index": 6, "correct_answer": "穿上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她穿上围巾，走出家门。", "explanation": "这里应该用〈围上〉。围巾要围在脖子上，用“围”，不用“穿”。"}, {"text": "他穿上书包去上学。", "explanation": "这里应该用〈背上〉。书包要用“背”，不能用“穿”。"}, {"text": "她穿上口红，对着镜子笑了。", "explanation": "这里应该用〈涂上〉。口红要用“涂”，不用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validati