INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96814, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "穿上", "is_correct": true, "explanation": "“穿上”（chuān shàng）指把衣物穿在身上。"}, {"text": "床上", "is_correct": false, "explanation": "chuáng（第二声，-ang）与 chuān（第一声，-an）韵母和声调都不同，“床上”指在床的上面。"}, {"text": "闩上", "is_correct": false, "explanation": "shuān 与 chuān 声母不同（sh 与 ch），“闩上”指用门闩把门插上。"}, {"text": "揣上", "is_correct": false, "explanation": "chuāi 与 chuān 韵母不同（-uai 与 -uan），“揣上”指把东西放进怀里或口袋里带着。"}], "explanations": {"穿上": "“穿上”（chuān shàng）指把衣物穿在身上。", "床上": "chuáng（第二声，-ang）与 chuān（第一声，-an）韵母和声调都不同，“床上”指在床的上面。", "闩上": "shuān 与 chuān 声母不同（sh 与 ch），“闩上”指用门闩把门插上。", "揣上": "chuāi 与 chuān 韵母不同（-uai 与 -uan），“揣上”指把东西放进怀里或口袋里带着。"}, "sentence_index": null, "correct_answer": "穿上"}, "level_3": {"options": [{"text": "穿上", "is_correct": true, "explanation": "“穿上”指把衣服穿到身上，符合“你穿上这件衣服真好看”的语境。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”用于果实、花等，不能说摘衣服。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于食物，不能说煮衣服。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹断，咬衣服与“好看”的语境矛盾。"}], "explanations": {"穿上": "“穿上”指把衣服穿到身上，符合“你穿上这件衣服真好看”的语境。", "摘": "搭配：“摘”用于果实、花等，不能说摘衣服。", "煮": "搭配：“煮”用于食物，不能说煮衣服。", "咬": "语义：“咬”指用牙齿夹断，咬衣服与“好看”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "穿上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿上手表，准备跑步。", "explanation": "这里应该用〈戴上〉。手表要用“戴”，不能用“穿”。"}, {"text": "她穿上扣子，走出房间。", "explanation": "这里应该用〈扣上〉。扣子要用“扣”，不能用“穿”。"}, {"text": "她穿上口红，拿起包出了门。", "explanation": "这里应该用〈涂上〉。口红要用“涂”，不用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2867c856-b912-4069-8f82-09127272c65c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, val