INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96815, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几个国家或团体说好了要互相帮忙。", "primary_collocate": null, "pronunciation": "tóng méng", "ipa": "tʰʊŋ³⁵ məŋ³⁵", "syllable_count": 2, "sentences": [{"text": "两个国家结成了同盟。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个同盟有三个成员国。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的同盟已经有很多年了。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个小国家组成了一个同盟。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个同盟的国家要互相帮忙。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两国之间有一个同盟。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个同盟让小国家觉得很安全。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国结成了同盟，以后互相帮忙。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个同盟后来没有了。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，历史上有很多同盟。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个同盟", "label": "量词"}, {"form": "同盟国", "label": "复合"}, {"form": "同盟军", "label": "复合"}], "register": "书面语", "sense_fingerprint": "国家或团体之间约定互相帮助的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '594414c6-35fb-4d2f-972b-7aa2cfad39ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96815, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同盟", "is_correct": true, "explanation": "同盟：几个国家互相帮忙的联合，可以“结成”，句意通顺。"}, {"text": "战争", "is_correct": false, "explanation": "搭配：“结成”后面接的是联合关系，“战争”不能被结成，搭配不当。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地方，不是国家之间的关系，句子说不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不能和国家结成关系。"}], "explanations": {"同盟": "同盟：几个国家互相帮忙的联合，可以“结成”，句意通顺。", "战争": "搭配：“结成”后面接的是联合关系，“战争”不能被结成，搭配不当。", "花园": "语义：花园是地方，不是国家之间的关系，句子说不通。", "课本": "语义：课本是书，不能和国家结成关系。"}, "sentence_index": 0, "correct_answer": "同盟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去同盟旅游。", "explanation": "这里应该用〈城市〉。同盟是国家或团体的联合，不是可以去旅游的地方。"}, {"text": "同盟每天早上六点起床上班。", "explanation": "这里应该用〈工人〉。同盟是国家或团体的联合，不会起床上班；上班的是人。"}, {"text": "两国发生了同盟。", "explanation": "这里应该用〈战争〉。同盟是国家之间的联合关系，不会“发生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96815, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同盟", "is_correct": true, "explanation": "同盟：几个国家互相帮忙的联合，能让小国家有安全感，句意通顺。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“牛奶”不能作保护国家安全的主语，搭配不当。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是图纸，不能让国家觉得安全。"}, {"text": "战火", "is_correct": false, "explanation": "语义：战火带来危险，和“很安全”相矛盾。"}], "explanations": {"同盟": "同盟：几个国家互相帮忙的联合，能让小国家有安全感，句意通顺。", "牛奶": "搭配：“牛奶”不能作保护国家安全的主语，搭配不当。", "地图": "语义：地图是图纸，不能让国家觉得安全。", "战火": "语义：战火带来危险，和“很安全”相矛盾。"}, "sentence_index": 6, "correct_answer": "同盟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同盟教学生数学。", "explanation": "这里应该用〈老师〉。同盟是国家或团体的联合，不会教课。"}, {"text": "同盟每天做饭。", "explanation": "这里应该用〈厨师〉。同盟不做饭。"}, {"text": "同盟给病人看病。", "explanation": "这里应该用〈医生〉。同盟不能给病人看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只同盟在战争中互相帮助。", "corrected_sentence": "这个同盟在战争中互相帮助。", "error_description": "错误在目标词的量词：“同盟”是团体，应该用“个”，不能用“只”。错误句是“这只同盟”，正确句是“这个同盟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同盟上的国家都很守信。", "corrected_sentence": "同盟里的国家都很守信。", "error_description": "错误在方位词：说团体内部应用“里”，应说“同盟里的国家”；“上”不表示团体的内部，“同盟上的国家”不自然。错误句是“同盟上的国家”，正确句是“同盟里的国家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
