INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96816, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为共同目的而结成的联合。", "primary_collocate": null, "pronunciation": "tóng méng", "ipa": "tʰʊŋ³⁵ məŋ³⁵", "syllable_count": 2, "sentences": [{"text": "工人们结成同盟，要求提高工资。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的同盟今天开会了。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两家公司结成了同盟。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了赢比赛，两个队结成同盟。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是为了环境保护才结成同盟的。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们组成同盟，一起卖水果。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个同盟的目的是帮助穷人。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司结成同盟，才能和大公司竞争。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同盟里的人都有共同的想法。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们很快就解散了同盟。", "target_word": "同盟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个同盟", "label": "量词"}, {"form": "同盟国", "label": "复合"}, {"form": "同盟军", "label": "复合"}], "register": "书面语", "sense_fingerprint": "人或团体为了共同目的联合起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '594414c6-35fb-4d2f-972b-7aa2cfad39ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同盟", "is_correct": true, "explanation": "同盟：为共同目的结成的联合，正好是工人们结成的关系。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能结成群体去要求提高工资。"}, {"text": "会议", "is_correct": false, "explanation": "搭配：“结成”后面不接“会议”，会议是活动，不是可以结成的关系。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是钱，工人不能把它结成一个群体，句子说不通。"}], "explanations": {"同盟": "同盟：为共同目的结成的联合，正好是工人们结成的关系。", "书包": "语义：书包是物品，不能结成群体去要求提高工资。", "会议": "搭配：“结成”后面不接“会议”，会议是活动，不是可以结成的关系。", "工资": "语义：工资是钱，工人不能把它结成一个群体，句子说不通。"}, "sentence_index": 0, "correct_answer": "同盟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同盟今天考试了。", "explanation": "这里应该用〈学生〉。同盟是为共同目的而结成的联合，不会参加考试；参加考试的是学生。"}, {"text": "我们去同盟上课。", "explanation": "这里应该用〈学校〉。同盟是为共同目的而联合的团体，不是上课的地方。"}, {"text": "他去同盟看病。", "explanation": "这里应该用〈医院〉。同盟不是看病的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同盟", "is_correct": true, "explanation": "同盟：为帮助穷人而结成的联合，它的目的可以是帮助穷人，句意通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有目的，不能用“的目的”来说明。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，不是有目的的团体，句子说不通。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字没有“目的”，不能作团体或计划的主语，句子说不通。"}], "explanations": {"同盟": "同盟：为帮助穷人而结成的联合，它的目的可以是帮助穷人，句意通顺。", "石头": "语义：石头没有目的，不能用“的目的”来说明。", "咖啡": "语义：咖啡是饮料，不是有目的的团体，句子说不通。", "数字": "语义：数字没有“目的”，不能作团体或计划的主语，句子说不通。"}, "sentence_index": 6, "correct_answer": "同盟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同盟每天早上吃两个鸡蛋。", "explanation": "这里应该用〈人〉。同盟是联合组织，不会吃东西；吃鸡蛋的是人。"}, {"text": "同盟里开满了花。", "explanation": "这里应该用〈花园〉。同盟是联合组织，不是开花的地方。"}, {"text": "同盟每天给学生上课。", "explanation": "这里应该用〈老师〉。同盟不给学生上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只同盟已经成立三年了。", "corrected_sentence": "这个同盟已经成立三年了。", "error_description": "错误在目标词的量词：“同盟”是团体，应该用“个”，不能用动物量词“只”。错误句是“这只同盟”，正确句是“这个同盟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同盟上的成员都很团结。", "corrected_sentence": "同盟里的成员都很团结。", "error_description": "错误在方位词：表示“同盟”内部的范围应说“同盟里”，不能说“同盟上”。“上”与团体类名词“同盟”搭配不当，正确形式是“同盟里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
