INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96817, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在很多东西里，选出最好的几个。", "primary_collocate": null, "pronunciation": "jīng xuǎn", "ipa": "tɕiŋ ɕɥɛn", "syllable_count": 2, "sentences": [{"text": "老师从很多照片里精选了五张。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑精选了十首好听的歌。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从全班作文中精选三篇。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你从这些书里精选几本。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从一百首诗里精选了十首。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈精选过一些旅行照片。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店每月从新书里精选十本，推荐给读者。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在从相册里精选照片。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想从这些歌里精选一首送你。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司从很多故事里精选了三个。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精选了", "label": "体标"}, {"form": "精选过", "label": "体标"}, {"form": "精选集", "label": "复合"}], "register": "中性", "sense_fingerprint": "从很多东西中选出最好的几个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2b2c253-1912-4008-90c3-ad21f0ccc4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96817, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精选", "is_correct": true, "explanation": "精选：从很多东西中选出最好的几个，正确答案。"}, {"text": "竞选", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是竞争选举，与“选出最好的”无关。"}, {"text": "惊险", "is_correct": false, "explanation": "xiǎn 与 xuǎn 只差介音（i 与 ü），意思是惊险。"}, {"text": "敬献", "is_correct": false, "explanation": "jìng xiàn 与 jīng xuǎn 声调和韵母都相近，意思是恭敬地献上，与“选出最好的”无关。"}], "explanations": {"精选": "精选：从很多东西中选出最好的几个，正确答案。", "竞选": "jìng（第四声）与 jīng（第一声）声调不同，意思是竞争选举，与“选出最好的”无关。", "惊险": "xiǎn 与 xuǎn 只差介音（i 与 ü），意思是惊险。", "敬献": "jìng xiàn 与 jīng xuǎn 声调和韵母都相近，意思是恭敬地献上，与“选出最好的”无关。"}, "sentence_index": null, "correct_answer": "精选"}, "level_3": {"options": [{"text": "精选", "is_correct": true, "explanation": "精选：挑出最好的几张，符合“从很多照片里”的句意。"}, {"text": "拍摄", "is_correct": false, "explanation": "搭配：“拍摄”指用相机摄取画面，不能与“从很多照片里”搭配。"}, {"text": "排列", "is_correct": false, "explanation": "搭配：“排列”指按顺序摆放，与“从很多照片里……了五张”搭配不通。"}, {"text": "送给", "is_correct": false, "explanation": "语义：“送给”指把东西交给别人，与“选出五张”的意思不符。"}], "explanations": {"精选": "精选：挑出最好的几张，符合“从很多照片里”的句意。", "拍摄": "搭配：“拍摄”指用相机摄取画面，不能与“从很多照片里”搭配。", "排列": "搭配：“排列”指按顺序摆放，与“从很多照片里……了五张”搭配不通。", "送给": "语义：“送给”指把东西交给别人，与“选出五张”的意思不符。"}, "sentence_index": 0, "correct_answer": "精选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他随便精选了几本书。", "explanation": "这里应该用〈挑选〉。精选强调精心挑出最好的，不能与“随便”搭配。"}, {"text": "他精选了三个小时的堵车。", "explanation": "这里应该用〈忍受〉。精选指从一组事物中挑出最好的，堵车不能被挑选，“忍受三个小时的堵车”才是正确说法。"}, {"text": "我精选了一下午的雨。", "explanation": "这里应该用〈淋〉。精选指从一组事物中挑出最好的，雨不能被挑选，“淋了一下午的雨”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96817, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精选", "is_correct": true, "explanation": "精选：从中挑出好的，符合“推荐给读者”的句意。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”与“推荐给读者”的意思矛盾。"}, {"text": "印刷", "is_correct": false, "explanation": "搭配：“印刷”不能与“从新书里”搭配，“从新书里印刷十本”说不通。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：烧毁了的书不能再推荐给读者。"}], "explanations": {"精选": "精选：从中挑出好的，符合“推荐给读者”的句意。", "删除": "语义：“删除”与“推荐给读者”的意思矛盾。", "印刷": "搭配：“印刷”不能与“从新书里”搭配，“从新书里印刷十本”说不通。", "烧毁": "语义：烧毁了的书不能再推荐给读者。"}, "sentence_index": 6, "correct_answer": "精选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们精选了所有的作业。", "explanation": "这里应该用〈批阅〉。精选只挑出一部分最好的，与“所有”矛盾；把全部作业都看一遍要用〈批阅〉。"}, {"text": "他精选了一座大山。", "explanation": "这里应该用〈翻过〉。精选要求从一组事物中挑出最好的，大山不能被挑选，“翻过一座大山”才是正确说法。"}, {"text": "他精选了一个晚上的觉。", "explanation": "这里应该用〈睡〉。精选指挑出最好的事物，不能用于睡觉这种动作，应说“睡了一个晚上的觉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很多书里精选了三本。", "corrected_sentence": "他从很多书里精选了三本。", "error_description": "“精选”前的处所要用介词引出，“从”或“在”均可。此句缺少介词，应说“从很多书里精选了三本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "编辑从很多稿子里精选得三篇。", "corrected_sentence": "编辑从很多稿子里精选了三篇。", "error_description": "体标错误：表示动作完成要用“了”，“得”是补语标记，“精选得三篇”不成立，应说“精选了三篇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
