INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96818, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从中精心挑选。", "primary_collocate": null, "pronunciation": "jīng xuǎn", "ipa": "tɕiŋ ɕɥɛn", "syllable_count": 2, "sentences": [{"text": "厨师精选了最新鲜的鱼。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为朋友精选了一件生日礼物。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈精选了最好的苹果送给奶奶。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校精选了一批好书给孩子们。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我精选了几张照片放进相册。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师为大家精选了练习题。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她花了一个下午精选衣服。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民精选了最好的种子。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他精选过很多好歌送给女朋友。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们精选了十个菜请客人吃。", "target_word": "精选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "精选了", "label": "体标"}, {"form": "精选过", "label": "体标"}, {"form": "精选集", "label": "复合"}], "register": "中性", "sense_fingerprint": "用心认真地挑选", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2b2c253-1912-4008-90c3-ad21f0ccc4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96818, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "精选", "is_correct": true, "explanation": "精选：挑出最好的东西，正确答案。"}, {"text": "竞选", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，意思是竞争选举。"}, {"text": "惊险", "is_correct": false, "explanation": "xiǎn 与 xuǎn 只差介音（i 与 ü），意思是惊险。"}, {"text": "精算", "is_correct": false, "explanation": "suàn 与 xuǎn 声母不同（s 与 x），意思是精确计算。"}], "explanations": {"精选": "精选：挑出最好的东西，正确答案。", "竞选": "jìng（第四声）与 jīng（第一声）声调不同，意思是竞争选举。", "惊险": "xiǎn 与 xuǎn 只差介音（i 与 ü），意思是惊险。", "精算": "suàn 与 xuǎn 声母不同（s 与 x），意思是精确计算。"}, "sentence_index": null, "correct_answer": "精选"}, "level_3": {"options": [{"text": "精选", "is_correct": true, "explanation": "精选：精心挑出最新鲜的鱼，符合句意。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”与“最新鲜”矛盾，不是挑选。"}, {"text": "腐烂", "is_correct": false, "explanation": "配价：“腐烂”是不及物动词，不能带宾语“鱼”。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带宾语“鱼”，“厨师笑了最新鲜的鱼”不成立。"}], "explanations": {"精选": "精选：精心挑出最新鲜的鱼，符合句意。", "丢弃": "语义：“丢弃”与“最新鲜”矛盾，不是挑选。", "腐烂": "配价：“腐烂”是不及物动词，不能带宾语“鱼”。", "笑": "配价：“笑”是不及物动词，不能带宾语“鱼”，“厨师笑了最新鲜的鱼”不成立。"}, "sentence_index": 0, "correct_answer": "精选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他随便精选了一件衣服。", "explanation": "这里把〈精选〉用成了“随意挑选”，应用〈挑选〉。精选强调精心挑出最好的，不能与“随便”搭配。"}, {"text": "妈妈精选了一堆垃圾扔掉。", "explanation": "这里应该用〈剔除〉。精选指精心挑出值得留下的好东西，把垃圾挑出扔掉要用“剔除”。"}, {"text": "老师精选了全班所有同学。", "explanation": "精选是从许多中挑出一部分最好的，“全班所有同学”是全部，没有挑选，与精选矛盾。可说“老师叫来了全班同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精选", "is_correct": true, "explanation": "精选：挑选，符合“花了一个下午”的句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不是挑选，“吃衣服”与句意不符。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带宾语“衣服”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”不能带宾语，“哭衣服”不成立。"}], "explanations": {"精选": "精选：挑选，符合“花了一个下午”的句意。", "吃": "语义：“吃”不是挑选，“吃衣服”与句意不符。", "睡": "配价：“睡”是不及物动词，不能带宾语“衣服”。", "哭": "配价：“哭”不能带宾语，“哭衣服”不成立。"}, "sentence_index": 6, "correct_answer": "精选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我精选了一个晚上的觉。", "explanation": "这里应该用〈睡〉。精选指挑出最好的事物，睡觉这种动作不能用精选，应说“睡了一个晚上的觉”。"}, {"text": "他精选了一下午的时间。", "explanation": "这里应该用〈度过〉。精选只能用于挑选事物，时间不能被挑选，应说“度过一下午”。"}, {"text": "我把空气精选了一遍。", "explanation": "这里应该用〈呼吸〉。精选指从中挑出最好的，空气不能被挑选；“呼吸了一口空气”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈院子里精选了几个苹果。", "corrected_sentence": "妈妈从院子里精选了几个苹果。", "error_description": "处所前缺少介词：应说“从（或在）院子里精选”，不能省略介词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她精选得三件衣服送给妈妈。", "corrected_sentence": "她精选了三件衣服送给妈妈。", "error_description": "体标错误：表示动作完成要用“了”，“得”是补语标记，“精选得三件衣服”不成立，应说“精选了三件衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
