INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96819, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "一点也不一样，用来说不是这样。", "primary_collocate": null, "pronunciation": "nǎ xiàng", "ipa": "na˨˩˦ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "事情哪像你说的那么简单。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试哪像你想的那么容易。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哪像大家说的那样坏。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活哪像电视里演的那样轻松。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店哪像网上说的那么好吃。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哪像你想的那么生气，别担心。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的老师哪像别人说的那么严。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现实哪像小说里写的那样美好。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事哪像他讲的那样有意思。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房间哪像别人说的那么乱。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "否定某人或某事与说法、想象的那样相同，意为并不是那样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e1032ad-a31c-4565-a75f-700a2b65743c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96819, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪像", "is_correct": true, "explanation": "“哪像”表示并不是那样，与“事情哪像你说的那么简单”的否定语气相符。"}, {"text": "显得", "is_correct": false, "explanation": "搭配：“显得”后接形容词或小句，不能直接带“你说的那么简单”作宾语。"}, {"text": "嫌", "is_correct": false, "explanation": "语义：“嫌”是对人或事的厌恶，与“事情”的客观情况描述不符。"}, {"text": "怪", "is_correct": false, "explanation": "语义：“怪”是责怪，与事情本身的难易程度无关。"}], "explanations": {"哪像": "“哪像”表示并不是那样，与“事情哪像你说的那么简单”的否定语气相符。", "显得": "搭配：“显得”后接形容词或小句，不能直接带“你说的那么简单”作宾语。", "嫌": "语义：“嫌”是对人或事的厌恶，与“事情”的客观情况描述不符。", "怪": "语义：“怪”是责怪，与事情本身的难易程度无关。"}, "sentence_index": 0, "correct_answer": "哪像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他长得哪像他爸爸，眼睛鼻子一模一样。", "explanation": "这里应该用〈很像〉。“哪像”表示并不是那样，这里说的是两人非常相像。"}, {"text": "天阴了，哪像要下雨，快带伞吧。", "explanation": "这里应该用〈好像〉。“哪像”表示否定，这里是推测要下雨。"}, {"text": "这孩子画的马哪像真的，太棒了！", "explanation": "这里应该用〈真像〉。句子在称赞画得像，“哪像”却表示一点也不像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪像", "is_correct": true, "explanation": "“哪像”表示并不像所说的那样，与“我们的老师……别人说的那么严”相符。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，后面须接形容词，不能直接接“别人说的那么严”。"}, {"text": "怕", "is_correct": false, "explanation": "语义：“怕”表示担心，与老师严格程度的客观评价不符。"}, {"text": "觉得", "is_correct": false, "explanation": "语义：“觉得”表示个人感受，与句子所陈述的比较不符。"}], "explanations": {"哪像": "“哪像”表示并不像所说的那样，与“我们的老师……别人说的那么严”相符。", "很": "语法：“很”是程度副词，后面须接形容词，不能直接接“别人说的那么严”。", "怕": "语义：“怕”表示担心，与老师严格程度的客观评价不符。", "觉得": "语义：“觉得”表示个人感受，与句子所陈述的比较不符。"}, "sentence_index": 6, "correct_answer": "哪像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事哪像很难，我们得多准备。", "explanation": "这里应该用〈好像〉。“哪像”表示并不是那样，这里是推测事情难。"}, {"text": "她笑起来哪像她妈妈，大家都这么说。", "explanation": "这里应该用〈很像〉。“大家都这么说”表示确实像，不能用否定的“哪像”。"}, {"text": "听声音，外面哪像有人在敲门。", "explanation": "这里应该用〈好像〉。这里是根据声音推测，不是否定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影哪像过你说的那么好看。", "corrected_sentence": "这部电影哪像你说的那么好看。", "error_description": "错误形式「哪像过你说的」，正确形式「哪像你说的」。“哪像”表示“一点也不像”，是否定用法，后面不能加动态助词“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店哪像了广告里说的那么便宜。", "corrected_sentence": "这家店哪像广告里说的那么便宜。", "error_description": "错误形式「哪像了广告里说的那么便宜」，正确形式「哪像广告里说的那么便宜」。“哪像”是否定用法，后面不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
