INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96820, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "反问语气，表示一点也不像。", "primary_collocate": null, "pronunciation": "nǎ xiàng", "ipa": "na˨˩˦ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他这样说话，哪像个当老师的？", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看你，哪像个学生？", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么脏的房间，哪像有人住？", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哪像五十岁的人，跑得那么快！", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你哪像生病的人，吃这么多！", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哪像外国人，汉语说得这么好！", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪像个家啊，到处都是东西。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这孩子哪像三岁，懂得这么多。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哪像个新手，做得真好！", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这儿哪像冬天，一点也不冷。", "target_word": "哪像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "用反问语气表示某人或某物一点也不像某种人或某种样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e1032ad-a31c-4565-a75f-700a2b65743c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪像", "is_correct": true, "explanation": "“哪像”用反问语气表示一点也不像当老师的，与“他这样说话”相符。"}, {"text": "做", "is_correct": false, "explanation": "搭配：“做个当老师的”不成立，“做”不能用来评判人的身份。"}, {"text": "有", "is_correct": false, "explanation": "语义：“有”表示拥有，与“他这样说话”的方式无关。"}, {"text": "当", "is_correct": false, "explanation": "语义：“当”表示担任，此处不能用来判断身份是否相符。"}], "explanations": {"哪像": "“哪像”用反问语气表示一点也不像当老师的，与“他这样说话”相符。", "做": "搭配：“做个当老师的”不成立，“做”不能用来评判人的身份。", "有": "语义：“有”表示拥有，与“他这样说话”的方式无关。", "当": "语义：“当”表示担任，此处不能用来判断身份是否相符。"}, "sentence_index": 0, "correct_answer": "哪像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和他哥哥哪像，大家都分不清。", "explanation": "这里应该用〈很像〉。“大家都分不清”说明两人很相像，不能用表示一点也不像的“哪像”。"}, {"text": "天这么黑，哪像要下雨了，快带伞。", "explanation": "这里应该用〈好像〉。这里是推测要下雨，不是反问否定。"}, {"text": "她长得哪像明星，走在街上常有人找她签名。", "explanation": "这里应该用〈真像〉。别人找她签名说明她确实像明星。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪像", "is_correct": true, "explanation": "“哪像”用反问语气表示一点也不像，与“哪像个家啊，到处都是东西”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“个家”搭配，“哪吃个家啊”不成立。"}, {"text": "充", "is_correct": false, "explanation": "搭配：“充”后不能直接接“个家”来做身份判断。"}, {"text": "弄", "is_correct": false, "explanation": "语义：“弄”表示做或制造，与对房间状况的评价不符。"}], "explanations": {"哪像": "“哪像”用反问语气表示一点也不像，与“哪像个家啊，到处都是东西”相符。", "吃": "搭配：“吃”不能与“个家”搭配，“哪吃个家啊”不成立。", "充": "搭配：“充”后不能直接接“个家”来做身份判断。", "弄": "语义：“弄”表示做或制造，与对房间状况的评价不符。"}, "sentence_index": 6, "correct_answer": "哪像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个孩子长得哪像，一看就是双胞胎。", "explanation": "这里应该用〈很像〉。“一看就是双胞胎”说明长得很像，不能用“哪像”。"}, {"text": "他哪像很累，说话都没力气。", "explanation": "这里应该用〈好像〉。“哪像”表示否定，这里是推测，要用“好像”。"}, {"text": "门口哪像有人在说话，你去看看。", "explanation": "这里应该用〈好像〉。这里是推测有人说话，不是反问否定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他哪像过个老板，穿得这么随便。", "corrected_sentence": "他哪像个老板，穿得这么随便。", "error_description": "错误形式「哪像过个老板」，正确形式「哪像个老板」。反问用的“哪像”后面不能加“过”；“个”与“老板”搭配，放在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子哪像了有人住，乱得不成样子。", "corrected_sentence": "这间屋子哪像有人住，乱得不成样子。", "error_description": "错误形式「哪像了有人住」，正确形式「哪像有人住」。“哪像”后面不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
