INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96821, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "县里管事的一个团体。", "primary_collocate": null, "pronunciation": "xiàn wěi", "ipa": "ɕjɛn˥˩ weɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "县委的人今天来学校看我们。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委在县里开了一个大会。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委决定在村里修一条路。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在县委工作了十年。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委的大楼就在河边。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委很关心农村的孩子。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委的会议开了一整天。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸去过县委办事。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委门口有很多人在排队。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委把这个好消息告诉了大家。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "县委书记", "label": "复合"}, {"form": "县委大楼", "label": "复合"}, {"form": "縣委", "label": "繁体"}], "register": "正式", "sense_fingerprint": "县里管事的团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '594414c6-35fb-4d2f-972b-7aa2cfad39ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "县委", "is_correct": true, "explanation": "县委：县里管事的团体，可以派人来学校看我们，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是团体，不能派人来学校看我们。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是团体，不能派人来学校看我们，句子说不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物件，不会派人来学校看我们。"}], "explanations": {"县委": "县委：县里管事的团体，可以派人来学校看我们，句意通顺。", "天气": "语义：天气不是团体，不能派人来学校看我们。", "月亮": "语义：月亮不是团体，不能派人来学校看我们，句子说不通。", "黑板": "语义：黑板是物件，不会派人来学校看我们。"}, "sentence_index": 0, "correct_answer": "县委"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是县委。", "explanation": "这里应该用〈县长〉。县委是机构，不能用来指一个人；“他是”后面要接表示人的名词。"}, {"text": "我们去县委买东西。", "explanation": "这里应该用〈县城〉。县委是管事的机构，不是卖东西的地方；去县城买东西才自然。"}, {"text": "县委今天下午去钓鱼。", "explanation": "这里应该用〈人〉。县委是机构，不会去钓鱼；去钓鱼的是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "县委", "is_correct": true, "explanation": "县委：县级党委，它的会议可以开一整天，句意通顺。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服是物品，不能开会，句子说不通。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然事物，不会召开会议。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是机构，不能召开会议，句子说不通。"}], "explanations": {"县委": "县委：县级党委，它的会议可以开一整天，句意通顺。", "衣服": "语义：衣服是物品，不能开会，句子说不通。", "河流": "语义：河流是自然事物，不会召开会议。", "月亮": "语义：月亮不是机构，不能召开会议，句子说不通。"}, "sentence_index": 6, "correct_answer": "县委"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "县委在医院给病人看病。", "explanation": "这里应该用〈医生〉。县委是机构，不能给病人看病。"}, {"text": "县委每天给学生上数学课。", "explanation": "这里应该用〈老师〉。县委是机构，不教课，句子里的“上数学课”只能由老师来做。"}, {"text": "县委在厨房里做饭。", "explanation": "这里应该用〈厨师〉。县委是机构，不会做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
