INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "中国共产党县级委员会的简称。", "primary_collocate": null, "pronunciation": "xiàn wěi", "ipa": "ɕjɛn˥˩ weɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "县委是党在县里的领导组织。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委开会研究了今年的工作。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党员要听县委的安排。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委召开了党员大会。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委给每个村都发了通知。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是县委的一名工作人员。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事要先报告县委。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委今年发展了十名新党员。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委的决定，党员都要照着做。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县委开了一次会，讨论农村的发展。", "target_word": "县委", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "县委书记", "label": "复合"}, {"form": "县委大楼", "label": "复合"}, {"form": "縣委", "label": "繁体"}], "register": "正式", "sense_fingerprint": "中国共产党县级委员会的简称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '594414c6-35fb-4d2f-972b-7aa2cfad39ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "县委", "is_correct": true, "explanation": "县委：中国共产党的县级委员会，正是党在县里的领导组织。"}, {"text": "党员", "is_correct": false, "explanation": "语义：党员指个人，不是组织，不能说“是党在县里的领导组织”。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸是媒体，不是领导机构，句子说不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是组织，不能作党在县里的领导组织，句子说不通。"}], "explanations": {"县委": "县委：中国共产党的县级委员会，正是党在县里的领导组织。", "党员": "语义：党员指个人，不是组织，不能说“是党在县里的领导组织”。", "报纸": "语义：报纸是媒体，不是领导机构，句子说不通。", "月亮": "语义：月亮不是组织，不能作党在县里的领导组织，句子说不通。"}, "sentence_index": 0, "correct_answer": "县委"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "县委今天去医院看牙。", "explanation": "这里应该用〈人〉。县委是组织，不会看牙；去医院看牙的是人。"}, {"text": "县委每天要睡十个小时。", "explanation": "这里应该用〈人〉。县委是组织，不会睡觉；睡十个小时的是人。"}, {"text": "县委在田里种地。", "explanation": "这里应该用〈农民〉。县委是组织，不会种地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "县委", "is_correct": true, "explanation": "县委：党的县级委员会，是需要先报告的机构，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能接受报告。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不能接受报告，句子说不通。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：“报告”的对象要是人或机构，“黑板”不能接受报告。"}], "explanations": {"县委": "县委：党的县级委员会，是需要先报告的机构，句意通顺。", "天气": "语义：天气是自然现象，不能接受报告。", "苹果": "语义：苹果是水果，不能接受报告，句子说不通。", "黑板": "搭配：“报告”的对象要是人或机构，“黑板”不能接受报告。"}, "sentence_index": 6, "correct_answer": "县委"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "县委帮病人打针。", "explanation": "这里应该用〈护士〉。县委是机构，不能给病人打针。"}, {"text": "县委在工厂里造机器。", "explanation": "这里应该用〈工人〉。县委是机构，不在工厂里造机器。"}, {"text": "县委写了一本小说。", "explanation": "这里应该用〈作家〉。县委是机构，不写小说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
