INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96823, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心地好，愿意帮助别人。", "primary_collocate": null, "pronunciation": "shàn liáng", "ipa": "ʂan˥˩ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她很善良，常常帮助邻居。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "善良的老人把饭分给了流浪猫。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个善良的人，总是愿意帮别人。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生善良又热心，大家都喜欢她。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "善良的小王每个周末都去看望老人。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈很善良，从不拒绝需要帮助的人。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心地善良，看到别人有困难就去帮忙。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "善良的司机停下车，送病人去医院。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她那么善良，一定会帮你的。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "善良的学生们把零花钱送给了山区的孩子。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "心地好，乐于帮助别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bb7a24-95b6-4973-9e99-6f71c56b88be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings 