INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96823, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "善良", "is_correct": true, "explanation": "shàn liáng，意思是心地好，乐于帮助别人。"}, {"text": "闪亮", "is_correct": false, "explanation": "shǎn liàng 第一个音节声调不同，第二个音节声调也不同，意思是发光、明亮。"}, {"text": "上梁", "is_correct": false, "explanation": "shàng liáng 第一个音节韵母 ang 与 an 不同，意思是架设房梁。"}, {"text": "山梁", "is_correct": false, "explanation": "shān liáng 第一个音节声调不同，意思是山脊。"}], "explanations": {"善良": "shàn liáng，意思是心地好，乐于帮助别人。", "闪亮": "shǎn liàng 第一个音节声调不同，第二个音节声调也不同，意思是发光、明亮。", "上梁": "shàng liáng 第一个音节韵母 ang 与 an 不同，意思是架设房梁。", "山梁": "shān liáng 第一个音节声调不同，意思是山脊。"}, "sentence_index": null, "correct_answer": "善良"}, "level_3": {"options": [{"text": "善良", "is_correct": true, "explanation": "心地好，乐于帮助别人，与“常常帮助邻居”一致。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与“常常帮助邻居”的行为相矛盾。"}, {"text": "冷漠", "is_correct": false, "explanation": "语义：“冷漠”表示不关心别人，与“常常帮助邻居”相悖。"}, {"text": "凶狠", "is_correct": false, "explanation": "搭配：“凶狠”形容性情暴戾，与“常常帮助邻居”的说法不搭。"}], "explanations": {"善良": "心地好，乐于帮助别人，与“常常帮助邻居”一致。", "懒惰": "语义：“懒惰”与“常常帮助邻居”的行为相矛盾。", "冷漠": "语义：“冷漠”表示不关心别人，与“常常帮助邻居”相悖。", "凶狠": "搭配：“凶狠”形容性情暴戾，与“常常帮助邻居”的说法不搭。"}, "sentence_index": 0, "correct_answer": "善良"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕很善良，大家都爱吃。", "explanation": "这里应该用〈好吃〉。善良指人的心地好，不能用来形容食物的味道。"}, {"text": "这台电脑很善良，从来不死机。", "explanation": "这里应该用〈可靠〉。善良指人的心地，不能用来形容机器的性能。"}, {"text": "这把雨伞很善良，下雨时总能把我遮得严严实实。", "explanation": "这里应该用〈管用〉。善良指人的心地，不能用来形容雨伞的功用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.