INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "善良", "is_correct": true, "explanation": "心地善良，与“看到别人有困难就去帮忙”一致。"}, {"text": "残忍", "is_correct": false, "explanation": "语义：“残忍”与“去帮忙”的行为相反，语境冲突。"}, {"text": "自私", "is_correct": false, "explanation": "语义：“自私”只顾自己，与“看到别人有困难就去帮忙”相矛盾。"}, {"text": "高傲", "is_correct": false, "explanation": "搭配：“心地”通常说品性善恶，一般不与“高傲”搭配。"}], "explanations": {"善良": "心地善良，与“看到别人有困难就去帮忙”一致。", "残忍": "语义：“残忍”与“去帮忙”的行为相反，语境冲突。", "自私": "语义：“自私”只顾自己，与“看到别人有困难就去帮忙”相矛盾。", "高傲": "搭配：“心地”通常说品性善恶，一般不与“高傲”搭配。"}, "sentence_index": 6, "correct_answer": "善良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把剪刀很善良，削水果很方便。", "explanation": "这里应该用〈好用〉。善良指人的心地好，不能用来形容工具的性能。"}, {"text": "这条路很善良，走起来很舒服。", "explanation": "这里应该用〈平坦〉。善良指人的心地，不能用来形容道路的状态。"}, {"text": "这盏灯很善良，夜里总是亮着。", "explanation": "这里应该用〈明亮〉。善良指人的心地，不能用来形容灯光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很善良善良，遇到困难的人总会主动帮忙。", "corrected_sentence": "他很善良，遇到困难的人总会主动帮忙。", "error_description": "错误形式多写了一次“善良”。“很”之后只需一个形容词，正确形式为“很善良”，删去多余的“善良”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一个善良好姑娘，常常给邻居送吃的。", "corrected_sentence": "她是一个善良的好姑娘，常常给邻居送吃的。", "error_description": "错误形式漏掉了“的”。“善良”作定语修饰名词时，后面须加“的”，正确形式为“善良的好姑娘”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
