INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96824, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心地纯正，没有恶意。", "primary_collocate": null, "pronunciation": "shàn liáng", "ipa": "ʂan˥˩ ljɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个孩子眼神善良，没有一点坏心。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他善良单纯，从来不会骗人。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的笑容很善良，让人放心。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "善良的人不会故意伤害别人。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话直，但心地善良。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别担心，她只是善良，没有恶意。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他天生善良，从不想害别人。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人善良的目光让孩子不再害怕。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太善良了，总是把别人往好处想。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "善良的她从来没有恨过谁。", "target_word": "善良", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "心地纯正，不怀恶意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bb7a24-95b6-4973-9e99-6f71c56b88be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_war