INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "善良", "is_correct": true, "explanation": "天生善良，与“从不想害别人”一致。"}, {"text": "阴险", "is_correct": false, "explanation": "语义：“阴险”表示暗中害人，与“从不想害别人”的意思相矛盾。"}, {"text": "歹毒", "is_correct": false, "explanation": "语义：“歹毒”指心肠狠毒、存心害人，与“从不想害别人”正相反。"}, {"text": "凶残", "is_correct": false, "explanation": "语义：“凶残”指残忍害人，与“从不想害别人”的语境冲突。"}], "explanations": {"善良": "天生善良，与“从不想害别人”一致。", "阴险": "语义：“阴险”表示暗中害人，与“从不想害别人”的意思相矛盾。", "歹毒": "语义：“歹毒”指心肠狠毒、存心害人，与“从不想害别人”正相反。", "凶残": "语义：“凶残”指残忍害人，与“从不想害别人”的语境冲突。"}, "sentence_index": 6, "correct_answer": "善良"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这颗糖很善良，吃起来甜甜的。", "explanation": "这里应该用〈甜〉。善良指心地纯正，不能用来形容糖的味道。"}, {"text": "这把椅子很善良，坐着很舒服。", "explanation": "这里应该用〈舒适〉。善良指心地纯正，不能用来形容椅子。"}, {"text": "这块地毯很善良，踩上去很舒服。", "explanation": "这里应该用〈柔软〉。善良指心地纯正，不能用来形容地毯的质地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的目光很善良善良，让人想靠近。", "corrected_sentence": "他的目光很善良，让人想靠近。", "error_description": "错误形式多写了一次“善良”。“很”之后只需一个形容词，正确形式为“很善良”，删去多余的“善良”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她善良得，从来没有恨过谁。", "corrected_sentence": "她善良得很，从来没有恨过谁。", "error_description": "错误形式缺少程度补语。“善良得”后须接补语，常用“善良得很”，正确形式为“善良得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8092a7e7-abc4-42ad-b201-2757b6bf4b2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
