INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96825, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体很胖、很圆的人。", "primary_collocate": null, "pronunciation": "pàng zi", "ipa": "pʰaŋ˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "那个胖子坐在最后一排。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候是个小胖子。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个胖子跑得很慢，可是很爱笑。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口站着一个又高又壮的胖子。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前是个胖子，现在很瘦了。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "胖子穿这件衣服太紧了。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个圆圆的胖子笑着走了过来。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车上有个胖子占了两个座位。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都叫他小胖子。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个胖子一口气吃了五个包子。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小胖子", "label": "复合"}], "register": "口语", "sense_fingerprint": "身体很胖很圆的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3663726-c4db-4604-891f-260c0732ed66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96825, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胖子", "is_correct": true, "explanation": "胖子：身体很胖、很圆的人。"}, {"text": "瓶子", "is_correct": false, "explanation": "píng（第二声）与 pàng（第四声）韵母不同（ing 与 ang），声调也不同，「瓶子」指装液体的容器。"}, {"text": "盘子", "is_correct": false, "explanation": "pán 与 pàng 韵尾不同（n 与 ng），「盘子」指盛放食物的器皿。"}, {"text": "房子", "is_correct": false, "explanation": "fáng（第二声）与 pàng（第四声）声母不同（f 与 p），「房子」指供人居住的地方。"}, {"text": "棒子", "is_correct": false, "explanation": "bàng 与 pàng 声母不同（b 与 p），「棒子」指棍子，北方也指玉米。"}], "explanations": {"胖子": "胖子：身体很胖、很圆的人。", "瓶子": "píng（第二声）与 pàng（第四声）韵母不同（ing 与 ang），声调也不同，「瓶子」指装液体的容器。", "盘子": "pán 与 pàng 韵尾不同（n 与 ng），「盘子」指盛放食物的器皿。", "房子": "fáng（第二声）与 pàng（第四声）声母不同（f 与 p），「房子」指供人居住的地方。", "棒子": "bàng 与 pàng 声母不同（b 与 p），「棒子」指棍子，北方也指玉米。"}, "sentence_index": null, "correct_answer": "胖子"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "搭配：“坐”要求有生命的人作主语，“石头”不能坐在最后一排。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会坐在最后一排，句子所指的应是人。"}, {"text": "胖子", "is_correct": true, "explanation": "胖子：身体很胖、很圆的人，能够坐在最后一排。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶不会坐在最后一排，与句意矛盾。"}], "explanations": {"石头": "搭配：“坐”要求有生命的人作主语，“石头”不能坐在最后一排。", "书包": "语义：书包不会坐在最后一排，句子所指的应是人。", "胖子": "胖子：身体很胖、很圆的人，能够坐在最后一排。", "垃圾桶": "语义：垃圾桶不会坐在最后一排，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "胖子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个胖子，瘦得皮包骨头。", "explanation": "这里前后矛盾：胖子指身体胖的人，不能与「瘦得皮包骨头」并列；形容身材瘦要说〈瘦子〉。"}, {"text": "这把椅子是个胖子，我们经常坐它。", "explanation": "这里把“胖子”用来指一件物品，是误用：胖子只指身体胖的人，指物应换成〈凳子〉这类物名。"}, {"text": "这本书是个胖子，有五百多页。", "explanation": "这里应该用〈厚〉。胖子只指身体胖的人，形容书页多要说书很〈厚〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96825, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "搭配：“笑着走过来”要求有生命的主语，椅子不能笑着走。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会笑着走过来，与句意矛盾。"}, {"text": "胖子", "is_correct": true, "explanation": "胖子：身体很胖、很圆的人，与“圆圆的”和“笑着走过来”相合。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜不会笑着走过来，与句意矛盾。"}], "explanations": {"椅子": "搭配：“笑着走过来”要求有生命的主语，椅子不能笑着走。", "窗户": "语义：窗户不会笑着走过来，与句意矛盾。", "胖子": "胖子：身体很胖、很圆的人，与“圆圆的”和“笑着走过来”相合。", "西瓜": "语义：西瓜不会笑着走过来，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "胖子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕是个胖子，一口气就吃完了。", "explanation": "这里应该用〈点心〉。胖子指人，不能指食物，指食物应说〈点心〉。"}, {"text": "他一口气吃了五个胖子。", "explanation": "这里应该用〈包子〉。胖子指人，不能作“吃”的宾语，吃的应是〈包子〉。"}, {"text": "他每天用胖子洗碗。", "explanation": "这里应该用〈洗碗布〉。胖子指人，不能当工具使用；洗碗要用〈洗碗布〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表哥小时候是只胖子，长大以后很瘦。", "corrected_sentence": "表哥小时候是个胖子，长大以后很瘦。", "error_description": "错误：量词“只”不用于指人。正确应为“个”，指人的“胖子”要用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站里走来一个圆圆地胖子。", "corrected_sentence": "车站里走来一个圆圆的胖子。", "error_description": "错误：修饰名词“胖子”的“圆圆”之后应用“的”，用“地”是修饰动词的结构。正确为“圆圆的胖子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
