INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体肥胖的人。", "primary_collocate": null, "pronunciation": "pàng zi", "ipa": "pʰaŋ˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "他是我们班最大的胖子。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "胖子也可以很快乐。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "胖子夏天特别怕热。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这个胖子要少吃肉。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟是个可爱的小胖子。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别笑他是胖子，那样不礼貌。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个胖子在公园里慢慢地跑步。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个胖子买了一大杯冰茶。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友以前是胖子，后来天天运动。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店有专门给胖子穿的大号衣服。", "target_word": "胖子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小胖子", "label": "复合"}], "register": "口语", "sense_fingerprint": "身体肥胖的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3663726-c4db-4604-891f-260c0732ed66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96826, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "胖子", "is_correct": true, "explanation": "胖子：身体肥胖的人。"}, {"text": "瓶子", "is_correct": false, "explanation": "píng（第二声）与 pàng（第四声）韵母不同（ing 与 ang），声调也不同，「瓶子」指装液体的容器。"}, {"text": "盘子", "is_correct": false, "explanation": "pán 与 pàng 韵尾不同（n 与 ng），「盘子」指盛放食物的器皿。"}, {"text": "房子", "is_correct": false, "explanation": "fáng（第二声）与 pàng（第四声）声母不同（f 与 p），「房子」指供人居住的地方。"}, {"text": "棒子", "is_correct": false, "explanation": "bàng 与 pàng 声母不同（b 与 p），「棒子」指棍子，北方也指玉米。"}], "explanations": {"胖子": "胖子：身体肥胖的人。", "瓶子": "píng（第二声）与 pàng（第四声）韵母不同（ing 与 ang），声调也不同，「瓶子」指装液体的容器。", "盘子": "pán 与 pàng 韵尾不同（n 与 ng），「盘子」指盛放食物的器皿。", "房子": "fáng（第二声）与 pàng（第四声）声母不同（f 与 p），「房子」指供人居住的地方。", "棒子": "bàng 与 pàng 声母不同（b 与 p），「棒子」指棍子，北方也指玉米。"}, "sentence_index": null, "correct_answer": "胖子"}, "level_3": {"options": [{"text": "矮子", "is_correct": false, "explanation": "体貌：“矮子”指身材矮，与“最大的”相矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“他”是人，不能是汽车，句子不成立。"}, {"text": "胖子", "is_correct": true, "explanation": "胖子：身体肥胖的人，指班里体型最大的人。"}, {"text": "书本", "is_correct": false, "explanation": "语义：“他”是班里的同学，不能是书本。"}], "explanations": {"矮子": "体貌：“矮子”指身材矮，与“最大的”相矛盾。", "汽车": "语义：“他”是人，不能是汽车，句子不成立。", "胖子": "胖子：身体肥胖的人，指班里体型最大的人。", "书本": "语义：“他”是班里的同学，不能是书本。"}, "sentence_index": 0, "correct_answer": "胖子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生说这个胖子很瘦，要多吃肉。", "explanation": "这里与“很瘦”矛盾：胖子指身体胖的人，说身材瘦要用〈瘦子〉。"}, {"text": "医生说这个胖子是一种水果，要少吃。", "explanation": "胖子指身体肥胖的人，不能指水果；指食物应说具体的〈水果〉名称。"}, {"text": "这块蛋糕是个胖子，要少吃。", "explanation": "胖子指人，这里用来指食物，指食物应说〈点心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包袱", "is_correct": false, "explanation": "搭配：“跑步”的主语须是人或动物，“包袱”不能跑步。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶不会在公园里跑步，与句意矛盾。"}, {"text": "胖子", "is_correct": true, "explanation": "胖子：身体肥胖的人，能在公园里慢慢地跑步。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不会跑步，与句意矛盾。"}], "explanations": {"包袱": "搭配：“跑步”的主语须是人或动物，“包袱”不能跑步。", "垃圾桶": "语义：垃圾桶不会在公园里跑步，与句意矛盾。", "胖子": "胖子：身体肥胖的人，能在公园里慢慢地跑步。", "花瓶": "语义：花瓶不会跑步，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "胖子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妹妹一口气吃掉了三个胖子。", "explanation": "这里应该用〈包子〉。胖子指人，不能作“吃”的宾语，吃的应是〈包子〉。"}, {"text": "这家店的衣服是个胖子，专门卖给孩子。", "explanation": "这里应该用〈大号〉。胖子指人，不能指衣服，形容衣服宽大要说〈大号〉。"}, {"text": "他每天用胖子擦桌子。", "explanation": "这里应该用〈抹布〉。胖子指人，不能当工具使用；擦桌子要用〈抹布〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟是班里最大胖子。", "corrected_sentence": "我弟弟是班里最大的胖子。", "error_description": "错误：“最大”修饰名词时，中间漏了“的”。正确应为“最大的胖子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只胖子买了一瓶冰水。", "corrected_sentence": "那个胖子买了一瓶冰水。", "error_description": "错误：指人的“胖子”应搭配量词“个”，不能用“只”。正确应为“那个胖子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
