INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96827, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "嘴巴里面。", "primary_collocate": null, "pronunciation": "zuǐ lǐ", "ipa": "tsweɪ˨˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "他嘴里有一块糖。", "target_word": "嘴里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子嘴里还有饭，不能说话。", "target_word": "嘴里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈让我把药放在嘴里。", "target_word": "嘴里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴里咬着一根草。", "target_word": "嘴里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟嘴里全是饼干。", "target_word": "嘴里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别把手指放进嘴里。", "target_word": "嘴里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我嘴里没有味道，什么都不想吃。", "target_word": "嘴里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗嘴里叼着一个球。", "target_word": "嘴里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她张开嘴，把水含在嘴里。", "target_word": "嘴里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭的时候，不要在嘴里放太多东西。", "target_word": "嘴里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嘴裡", "label": "繁体"}], "register": "口语", "sense_fingerprint": "嘴巴里面的地方，常指放东西或含东西的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f797344-34e1-4b24-8621-ea8ced756a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月亮里", "is_correct": false, "explanation": "语义：“月亮”不能装糖，“他月亮里有一块糖”说不通。"}, {"text": "嘴里", "is_correct": true, "explanation": "正确：“嘴里”指口腔内部，糖含在嘴巴里面，与句子语境相符。"}, {"text": "天空里", "is_correct": false, "explanation": "语义：“天空”不能装东西，“他天空里有一块糖”不成立。"}, {"text": "地球里", "is_correct": false, "explanation": "搭配：“有……糖”的处所应是能放东西或含东西的地方，“地球里”不这样搭配。"}], "explanations": {"月亮里": "语义：“月亮”不能装糖，“他月亮里有一块糖”说不通。", "嘴里": "正确：“嘴里”指口腔内部，糖含在嘴巴里面，与句子语境相符。", "天空里": "语义：“天空”不能装东西，“他天空里有一块糖”不成立。", "地球里": "搭配：“有……糖”的处所应是能放东西或含东西的地方，“地球里”不这样搭配。"}, "sentence_index": 0, "correct_answer": "嘴里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他嘴里挂着笑容。", "explanation": "这里应该用〈嘴边〉。“嘴里”指口腔内部，笑容挂在嘴的周围，要用“嘴边”。"}, {"text": "他嘴里贴着一块创可贴。", "explanation": "这里应该用〈嘴唇上〉。创可贴贴在嘴唇外面，“嘴里”指口腔内部，不能说贴在里面。"}, {"text": "他嘴里戴着耳机。", "explanation": "这里应该用〈耳朵里〉。耳机戴在耳朵里，“嘴里”指口腔内部，不能说戴在嘴里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轮胎", "is_correct": false, "explanation": "语义：“轮胎”不能闻到味道，“我轮胎没有味道”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不能感受味道，“我窗户没有味道”不符合语境。"}, {"text": "脚趾", "is_correct": false, "explanation": "搭配：“没有味道”说的是能闻到气味的器官或处所，“脚趾”一般不这样说。"}, {"text": "嘴里", "is_correct": true, "explanation": "正确：“嘴里”指口腔内部，味道在口中才能感受到，与“什么都不想吃”的语境相符。"}], "explanations": {"轮胎": "语义：“轮胎”不能闻到味道，“我轮胎没有味道”说不通。", "窗户": "语义：“窗户”不能感受味道，“我窗户没有味道”不符合语境。", "脚趾": "搭配：“没有味道”说的是能闻到气味的器官或处所，“脚趾”一般不这样说。", "嘴里": "正确：“嘴里”指口腔内部，味道在口中才能感受到，与“什么都不想吃”的语境相符。"}, "sentence_index": 6, "correct_answer": "嘴里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她嘴里涂着口红，很好看。", "explanation": "这里应该用〈嘴唇上〉。口红涂在嘴唇上，“嘴里”指口腔内部，不能涂在里面。"}, {"text": "这只猫嘴里戴着项圈。", "explanation": "这里应该用〈脖子上〉。项圈戴在脖子上，“嘴里”指口腔内部，不能说戴在嘴里。"}, {"text": "他嘴里系着一条领带。", "explanation": "这里应该用〈脖子上〉。领带系在脖子上，“嘴里”指口腔内部，不能说系在嘴里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶嘴里的含着一颗薄荷糖。", "corrected_sentence": "奶奶嘴里含着一颗薄荷糖。", "error_description": "错误形式：“嘴里”后多加了“的”，“的”后面没有中心词，句子不通。正确形式：“奶奶嘴里含着一颗薄荷糖。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宝宝嘴里里含着奶嘴。", "corrected_sentence": "宝宝嘴里含着奶嘴。", "error_description": "方位词重复：“嘴里”后多加了一个“里”，写成“嘴里里”。“嘴里”已含方位词“里”，应只说“嘴里”。正确形式：“宝宝嘴里含着奶嘴。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96831, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸", "is_correct": true, "explanation": "“吸”指把气体或液体吸进来，与“喷出”的方向相反，构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指奔跑的动作，与“喷”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指书写，与“喷”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”指入睡，与“喷”没有反义关系。"}], "correct_answer": "吸", "explanations": {"吸": "“吸”指把气体或液体吸进来，与“喷出”的方向相反，构成反义。", "跑": "“跑”指奔跑的动作，与“喷”没有反义关系。", "写": "“写”指书写，与“喷”没有反义关系。", "睡": "“睡”指入睡，与“喷”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96831, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸", "is_correct": true, "explanation": "“吸”指把气体或液体吸进来，与“喷出”的方向相反，构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指唱歌，与“喷”没有反义关系。"}, {"text": "读", "is_correct": false, "explanation": "“读”指阅读或朗读，与“喷”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "“走”指行走，与“喷”没有反义关系。"}], "correct_answer": "吸", "explanations": {"吸": "“吸”指把气体或液体吸进来，与“喷出”的方向相反，构成反义。", "唱": "“唱”指唱歌，与“喷”没有反义关系。", "读": "“读”指阅读或朗读，与“喷”没有反义关系。", "走": "“走”指行走，与“喷”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96831, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水或气一下子很快地射出来。", "primary_collocate": null, "pronunciation": "pēn", "ipa": "pʰən˥˥", "syllable_count": 1, "sentences": [{"text": "水管坏了，水一下子喷了出来。", "target_word": "喷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火山喷出了很多烟。", "target_word": "喷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鲸鱼喷出一股高高的水柱。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开瓶盖，可乐一下子喷出来了。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下的热水从石头缝里喷出来。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水龙头一开，水就喷得到处都是。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一用力，伤口的血喷了出来。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的水一直往上喷。", "target_word": "喷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽水摇过以后，一打开就会喷出来。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管子裂了，热气从里面喷了出来。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喷了", "label": "体标"}, {"form": "喷着", "label": "体标"}, {"form": "喷过", "label": "体标"}], "register": "中性", "sense_fingerprint": "水、血、气等从管口、缝隙或开口处突然猛地冲出来，主语是射出的东西或来源，常带“出来”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca46de64-fa79-4631-af35-c977a98316fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96831, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喷", "is_correct": true, "explanation": "喷 pēn（第一声）指水或气猛然射出，符合此义。"}, {"text": "盆", "is_correct": false, "explanation": "盆 pén（第二声）与喷的声调不同，意思是盆子。"}, {"text": "分", "is_correct": false, "explanation": "分 fēn 与 pēn 声母不同（f 与 p），意思是分开。"}, {"text": "奔", "is_correct": false, "explanation": "奔 bēn 与 pēn 声母不同（b 与 p），意思是奔跑。"}], "explanations": {"喷": "喷 pēn（第一声）指水或气猛然射出，符合此义。", "盆": "盆 pén（第二声）与喷的声调不同，意思是盆子。", "分": "分 fēn 与 pēn 声母不同（f 与 p），意思是分开。", "奔": "奔 bēn 与 pēn 声母不同（b 与 p），意思是奔跑。"}, "sentence_index": null, "correct_answer": "喷"}, "level_3": {"options": [{"text": "喷", "is_correct": true, "explanation": "“喷”表示水或气一下子猛地射出，与“一下子”和“出来”相符。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”是挖掘的动作，水不能被“挖”出来，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与水从管子里射出的情形毫无关联。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”需要刀具和被切的物体，液体不能被“切”出来。"}], "explanations": {"喷": "“喷”表示水或气一下子猛地射出，与“一下子”和“出来”相符。", "挖": "语义：“挖”是挖掘的动作，水不能被“挖”出来，句意不通。", "唱": "语义：“唱”指唱歌，与水从管子里射出的情形毫无关联。", "切": "搭配：“切”需要刀具和被切的物体，液体不能被“切”出来。"}, "sentence_index": 0, "correct_answer": "喷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把嘴里的果核喷到了垃圾桶里。", "explanation": "这里应该用〈吐〉。人有意把嘴里的果核弄出来，说“吐”；“喷”指东西受压力一下子猛地射出来，不用来说这种动作。"}, {"text": "眼泪慢慢喷下来。", "explanation": "这里应该用〈流〉。“喷”表示猛然射出，不能与“慢慢”搭配，也不能描述眼泪缓缓落下。"}, {"text": "水一滴一滴地喷下来。", "explanation": "这里应该用〈淌〉。“喷”表示猛然射出，不能形容一滴一滴慢慢落下的水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96831, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "喷", "is_correct": true, "explanation": "喷 pēn（第一声）指水或气猛然射出，符合此义。"}, {"text": "拼", "is_correct": false, "explanation": "拼 pīn 与 pēn 的元音不同，意思是拼合。"}, {"text": "攀", "is_correct": false, "explanation": "攀 pān 与 pēn 的元音不同，意思是攀登。"}, {"text": "烹", "is_correct": false, "explanation": "烹 pēng 与 pēn 韵尾不同（ng 与 n），意思是烹煮。"}], "explanations": {"喷": "喷 pēn（第一声）指水或气猛然射出，符合此义。", "拼": "拼 pīn 与 pēn 的元音不同，意思是拼合。", "攀": "攀 pān 与 pēn 的元音不同，意思是攀登。", "烹": "烹 pēng 与 pēn 韵尾不同（ng 与 n），意思是烹煮。"}, "sentence_index": null, "correct_answer": "喷"}, "level_3": {"options": [{"text": "喷", "is_correct": true, "explanation": "“喷”表示血猛地射出，与“一用力”和“出来”的情形相符。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”是用刀斧切断的动作，血不能被“砍”出来，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象通常是食物或药物，血不能被“吃”出来。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，与伤口流血的情形毫无关联。"}], "explanations": {"喷": "“喷”表示血猛地射出，与“一用力”和“出来”的情形相符。", "砍": "语义：“砍”是用刀斧切断的动作，血不能被“砍”出来，句意不通。", "吃": "搭配：“吃”的对象通常是食物或药物，血不能被“吃”出来。", "写": "语义：“写”指书写，与伤口流血的情形毫无关联。"}, "sentence_index": 6, "correct_answer": "喷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杯子里的水慢慢喷出来。", "explanation": "这里应该用〈溢〉。“喷”表示猛然射出，与“慢慢”矛盾，不能描述水缓缓溢出杯口。"}, {"text": "烟囱里慢慢喷出黑烟。", "explanation": "这里应该用〈冒〉。“喷”指强力射出，不能形容烟缓缓升起的样子。"}, {"text": "眼泪顺着脸颊喷下来。", "explanation": "这里应该用〈淌〉。“喷”表示猛烈射出，不能描述眼泪顺着脸颊慢慢流下的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个瓶子一打开，里面的泡沫就喷进来了。", "corrected_sentence": "这个瓶子一打开，里面的泡沫就喷出来了。", "error_description": "趋向补语用错。泡沫是从瓶内向外射出，应说“喷出来”；“喷进来”表示向内射入，方向相反，不符合句意。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暖气管道漏了，热水不停地喷出了来。", "corrected_sentence": "暖气管道漏了，热水不停地喷出来。", "error_description": "趋向补语“出来”是一个整体，中间不能插入“了”。“喷出了来”错误，应说“喷出来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
