INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96832, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "液体、气体等受压力而射出。", "primary_collocate": null, "pronunciation": "pēn", "ipa": "pʰən˥˥", "syllable_count": 1, "sentences": [{"text": "农民正在给果树喷药。", "target_word": "喷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人在墙上喷了一层白漆。", "target_word": "喷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她出门前在身上喷了一点香水。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员用水枪向大火喷水。", "target_word": "喷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车需要重新喷漆。", "target_word": "喷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在桌子上喷一点消毒水。", "target_word": "喷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天他每天给花园喷水。", "target_word": "喷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在衣服上喷了一点除味剂。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着小瓶子，往花上喷水。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生往他的喉咙里喷了一点药。", "target_word": "喷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喷了", "label": "体标"}, {"form": "喷着", "label": "体标"}, {"form": "喷过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人用喷壶、喷枪、水枪等工具把水、药、漆、香水等液体或气体射向某处，常带宾语，如“喷药”“喷漆”“喷水”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca46de64-fa79-4631-af35-c977a98316fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96832, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喷", "is_correct": true, "explanation": "喷 pēn（第一声）指人借助工具把液体射向某处，符合此义。"}, {"text": "盆", "is_correct": false, "explanation": "盆 pén（第二声）与喷的声调不同，意思是盆子。"}, {"text": "分", "is_correct": false, "explanation": "分 fēn 与 pēn 声母不同（f 与 p），意思是分开。"}, {"text": "奔", "is_correct": false, "explanation": "奔 bēn 与 pēn 声母不同（b 与 p），意思是奔跑。"}], "explanations": {"喷": "喷 pēn（第一声）指人借助工具把液体射向某处，符合此义。", "盆": "盆 pén（第二声）与喷的声调不同，意思是盆子。", "分": "分 fēn 与 pēn 声母不同（f 与 p），意思是分开。", "奔": "奔 bēn 与 pēn 声母不同（b 与 p），意思是奔跑。"}, "sentence_index": null, "correct_answer": "喷"}, "level_3": {"options": [{"text": "喷", "is_correct": true, "explanation": "“喷”指用工具把药液射向果树，“给果树喷药”是常见说法。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”是挖掘的动作，给果树用药不能用“挖”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与给果树施药的动作毫无关联。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃药”的对象通常是人或动物，不能说“给果树吃药”。"}], "explanations": {"喷": "“喷”指用工具把药液射向果树，“给果树喷药”是常见说法。", "挖": "语义：“挖”是挖掘的动作，给果树用药不能用“挖”。", "唱": "语义：“唱”指唱歌，与给果树施药的动作毫无关联。", "吃": "搭配：“吃药”的对象通常是人或动物，不能说“给果树吃药”。"}, "sentence_index": 0, "correct_answer": "喷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把牛奶喷进了杯子里。", "explanation": "这里应该用〈倒〉。“喷”指液体受压力射出，不能用来形容把牛奶缓缓倒进杯子。"}, {"text": "用布喷桌子。", "explanation": "这里应该用〈擦〉。“喷”的对象是液体或药剂，不能用布去“喷”桌子。"}, {"text": "用扫帚喷地。", "explanation": "这里应该用〈扫〉。“喷”的对象必须是液体或气体，扫帚用来扫地，不能用“喷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96832, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "喷", "is_correct": true, "explanation": "喷 pēn（第一声）指人借助工具把液体射向某处，符合此义。"}, {"text": "拼", "is_correct": false, "explanation": "拼 pīn 与 pēn 的元音不同，意思是拼合。"}, {"text": "攀", "is_correct": false, "explanation": "攀 pān 与 pēn 的元音不同，意思是攀登。"}, {"text": "烹", "is_correct": false, "explanation": "烹 pēng 与 pēn 韵尾不同（ng 与 n），意思是烹煮。"}], "explanations": {"喷": "喷 pēn（第一声）指人借助工具把液体射向某处，符合此义。", "拼": "拼 pīn 与 pēn 的元音不同，意思是拼合。", "攀": "攀 pān 与 pēn 的元音不同，意思是攀登。", "烹": "烹 pēng 与 pēn 韵尾不同（ng 与 n），意思是烹煮。"}, "sentence_index": null, "correct_answer": "喷"}, "level_3": {"options": [{"text": "喷", "is_correct": true, "explanation": "“喷”指用工具把水射向花园，与“给花园”和“喷水”的用法相符。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”是用刀斧切断的动作，不能用来给花园施水。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”需要线或布作宾语，不能与“水”搭配。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，与给花园浇水无关。"}], "explanations": {"喷": "“喷”指用工具把水射向花园，与“给花园”和“喷水”的用法相符。", "砍": "语义：“砍”是用刀斧切断的动作，不能用来给花园施水。", "织": "搭配：“织”需要线或布作宾语，不能与“水”搭配。", "写": "语义：“写”指书写，与给花园浇水无关。"}, "sentence_index": 6, "correct_answer": "喷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "往地上喷了一把种子。", "explanation": "这里应该用〈撒〉。“喷”的对象必须是液体或气体，种子是固体，不能用“喷”。"}, {"text": "用手喷门。", "explanation": "这里应该用〈敲〉。“喷”需要借助喷壶、喷枪等工具射出液体，不能用手去“喷”门。"}, {"text": "用剪刀喷纸。", "explanation": "这里应该用〈裁〉。“喷”指把液体或气体射出，不能用来形容裁纸的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人用喷枪给铁门漆喷。", "corrected_sentence": "工人用喷枪给铁门喷漆。", "error_description": "“喷漆”是动宾结构，动词“喷”在前、宾语“漆”在后。写成“漆喷”，动宾顺序颠倒，不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在门口给自行车不喷了一层黑漆。", "corrected_sentence": "他在门口给自行车喷了一层黑漆。", "error_description": "否定词“不”误加在动词“喷”前，与表示完成的体标“了”矛盾，原句表达的是一次已完成的肯定动作。应去掉“不”，说“喷了一层黑漆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
