INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96835, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人请过你，你也请他一次。", "primary_collocate": null, "pronunciation": "huí qǐng", "ipa": "xuei˧˥ tɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "上次他请我吃饭，这次我要回请他。", "target_word": "回请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你请过我一次，下周我回请你。", "target_word": "回请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事请我喝了咖啡，我想找机会回请。", "target_word": "回请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请客那天我没带钱，下次一定回请。", "target_word": "回请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师请过我们，我们打算回请她。", "target_word": "回请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友请我看了电影，我周末回请他。", "target_word": "回请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别客气，我下次回请你就是了。", "target_word": "回请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她上个月请我吃饭，我还没回请她。", "target_word": "回请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李明请我去他家玩，我得回请他一次。", "target_word": "回请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每次都请我，这回让我回请你吧。", "target_word": "回请", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回请了", "label": "体标"}, {"form": "回请过", "label": "体标"}], "register": "口语", "sense_fingerprint": "别人请客之后，自己也请对方一次作为回报", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e1032ad-a31c-4565-a75f-700a2b65743c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回请", "is_correct": true, "explanation": "“回请”指别人先请过你，你再请对方一次，与上文“上次他请我吃饭”相呼应。"}, {"text": "回头", "is_correct": false, "explanation": "语法：“回头”是不及物动词，后面不能直接带宾语“他”。"}, {"text": "报复", "is_correct": false, "explanation": "语义：报复是对伤害的还击，与“上次他请我吃饭”的友好行为不符。"}, {"text": "嫌弃", "is_correct": false, "explanation": "搭配：“嫌弃”表示厌恶，与“请吃饭”这种礼尚往来的语境不搭。"}], "explanations": {"回请": "“回请”指别人先请过你，你再请对方一次，与上文“上次他请我吃饭”相呼应。", "回头": "语法：“回头”是不及物动词，后面不能直接带宾语“他”。", "报复": "语义：报复是对伤害的还击，与“上次他请我吃饭”的友好行为不符。", "嫌弃": "搭配：“嫌弃”表示厌恶，与“请吃饭”这种礼尚往来的语境不搭。"}, "sentence_index": 0, "correct_answer": "回请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "客户帮我们解决了一个大难题，我们准备设宴回请他。", "explanation": "这里应该用〈答谢〉。回请是别人先请过自己，自己再请对方一次；客户并没有请过我们，表示感谢应该用答谢。"}, {"text": "售后人员每个月都会打电话，回请已经买过产品的老客户。", "explanation": "这里应该用〈回访〉。回访指再去或再打电话了解情况，不是请客；回请必须是以请客作为回报。"}, {"text": "远道而来的客人第一次来，我们用丰盛的晚餐回请他。", "explanation": "这里应该用〈款待〉。款待是主动热情地招待客人；客人是第一次来，没有请过我们，所以不能用回请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回请", "is_correct": true, "explanation": "“回请”表示以请客回报对方，与“你别客气”的客套语境相符。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”针对错误，与“你别客气”的礼尚往来语境不协调。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：惩罚是处罚犯错的人，与对方的好意完全不符。"}, {"text": "训斥", "is_correct": false, "explanation": "语域：训斥语气严厉，与“你别客气”的客套口吻不协调。"}], "explanations": {"回请": "“回请”表示以请客回报对方，与“你别客气”的客套语境相符。", "批评": "语义：“批评”针对错误，与“你别客气”的礼尚往来语境不协调。", "惩罚": "语义：惩罚是处罚犯错的人，与对方的好意完全不符。", "训斥": "语域：训斥语气严厉，与“你别客气”的客套口吻不协调。"}, "sentence_index": 6, "correct_answer": "回请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新员工刚报到，公司回请了他们一顿饭。", "explanation": "这里应该用〈宴请〉。宴请是主动设宴招待；新员工刚来，还没有请过公司，所以不能说回请。"}, {"text": "张经理刚来公司，我们就回请他来参观工厂。", "explanation": "这里应该用〈邀请〉。回请以对方先请过自己为前提；张经理刚来，并没有请过我们，应该用邀请。"}, {"text": "他住院那几天，我每天去医院回请他。", "explanation": "这里应该用〈探望〉。探望是去看望病人表示关心；回请是请对方吃饭等，不能用于去医院看人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上周回请了我们一个。", "corrected_sentence": "他上周回请了我们一次。", "error_description": "错误形式：回请了我们一个；正确形式：回请了我们一次。表示动作次数要用动量词“次”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经回请了他过。", "corrected_sentence": "我们已经回请过他了。", "error_description": "错误形式「回请了他过」，正确形式「回请过他了」。“过”紧跟动词，“了”放在句末，两者不能颠倒或同时放在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96837, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "商品经济", "is_correct": true, "explanation": "正确。商品经济以交换为目的，与自然经济自给自足、不交换的特点相反。"}, {"text": "农业", "is_correct": false, "explanation": "“农业”指一个产业，与“自然经济”不构成反义关系。"}, {"text": "森林", "is_correct": false, "explanation": "“森林”是具体事物，与“自然经济”不构成反义关系。"}, {"text": "教育", "is_correct": false, "explanation": "“教育”指培养人的活动，与“自然经济”不构成反义关系。"}], "correct_answer": "商品经济", "explanations": {"商品经济": "正确。商品经济以交换为目的，与自然经济自给自足、不交换的特点相反。", "农业": "“农业”指一个产业，与“自然经济”不构成反义关系。", "森林": "“森林”是具体事物，与“自然经济”不构成反义关系。", "教育": "“教育”指培养人的活动，与“自然经济”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96837, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "商品经济", "is_correct": true, "explanation": "正确。商品经济以交换为目的，与自然经济自给自足、不交换的特点相反。"}, {"text": "历史", "is_correct": false, "explanation": "“历史”指过去的事情，与“自然经济”不构成反义关系。"}, {"text": "语言", "is_correct": false, "explanation": "“语言”指交流的工具，与“自然经济”不构成反义关系。"}, {"text": "医院", "is_correct": false, "explanation": "“医院”是治病的机构，与“自然经济”不构成反义关系。"}], "correct_answer": "商品经济", "explanations": {"商品经济": "正确。商品经济以交换为目的，与自然经济自给自足、不交换的特点相反。", "历史": "“历史”指过去的事情，与“自然经济”不构成反义关系。", "语言": "“语言”指交流的工具，与“自然经济”不构成反义关系。", "医院": "“医院”是治病的机构，与“自然经济”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96837, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们自己种田织布，自己用，不拿去卖。", "primary_collocate": null, "pronunciation": "zì rán jīng jì", "ipa": "tsɨ˥˩ ʐan˧˥ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "古代农村大多是自然经济。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在自然经济里，人们自己种田织布。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然经济的特点是不拿东西去卖。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候的村子还过着自然经济的生活。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然经济下，农民吃的穿的都是自己做的。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，小时候家乡还是自然经济。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然经济让农民很少去市场买东西。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着城市发展，自然经济慢慢消失了。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，自然经济里的人不太需要钱。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了自然经济是怎么回事。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然經濟", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "农民自己生产自己用、不拿去卖的经济", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然经济", "is_correct": true, "explanation": "正确。自然经济指自给自足、不拿去卖的经济形式，正符合古代农村的情况。"}, {"text": "城市", "is_correct": false, "explanation": "语义：农村与城市相对，句子说的是农村大多是什么，不能是城市。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：农村的经济形态不能说成工厂，“古代农村”与“工厂”搭配不当。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教育机构，句子说的是农村的经济状况，学校说不通。"}], "explanations": {"自然经济": "正确。自然经济指自给自足、不拿去卖的经济形式，正符合古代农村的情况。", "城市": "语义：农村与城市相对，句子说的是农村大多是什么，不能是城市。", "工厂": "搭配：农村的经济形态不能说成工厂，“古代农村”与“工厂”搭配不当。", "学校": "语义：学校是教育机构，句子说的是农村的经济状况，学校说不通。"}, "sentence_index": 0, "correct_answer": "自然经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "改革以后，村子里大力发展自然经济。", "explanation": "这里应该用〈商品经济〉。自然经济是自给自足、不拿去交换的形式，不能“大力发展”，要说发展商品经济。"}, {"text": "他家的自然经济很困难。", "explanation": "这里应该用〈家庭经济〉。“自然经济”指一种经济形式，说一家人的经济状况困难要用“家庭经济”。"}, {"text": "这个县的自然经济很活跃。", "explanation": "这里应该用〈农村经济〉。“自然经济”指自给自足、不拿去卖的经济形式，谈不上“活跃”；说某地经济活跃，要用农村经济。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然经济", "is_correct": true, "explanation": "正确。句子说农民很少去市场买东西，正是自然经济不交换的特点。"}, {"text": "商品经济", "is_correct": false, "explanation": "语义：商品经济以交换为主，会让农民更常去市场，与“很少去市场”相反。"}, {"text": "大学", "is_correct": false, "explanation": "语义：大学不会使农民很少去市场，句子的意思说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "配价：“让”的主语要能致使某种情况，钢琴不能使农民做出这种行为。"}], "explanations": {"自然经济": "正确。句子说农民很少去市场买东西，正是自然经济不交换的特点。", "商品经济": "语义：商品经济以交换为主，会让农民更常去市场，与“很少去市场”相反。", "大学": "语义：大学不会使农民很少去市场，句子的意思说不通。", "钢琴": "配价：“让”的主语要能致使某种情况，钢琴不能使农民做出这种行为。"}, "sentence_index": 6, "correct_answer": "自然经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的自然经济发展得很快。", "explanation": "这里应该用〈市场经济〉。自然经济不以交换为目的，不能说“发展得很快”，应说市场经济。"}, {"text": "自然经济下，价格由国家决定。", "explanation": "这里应该用〈计划经济〉。自然经济不靠交换，谈不上价格，由国家定价的是计划经济。"}, {"text": "这个地区的自然经济靠旅游业带动。", "explanation": "这里应该用〈地方经济〉。“自然经济”指自给自足、不以交换为目的的经济形式；“地方经济”指一个地区的整体经济。靠旅游业带动的是交换型经济，自然经济不靠它带动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书上说，这一带曾是一只自然经济。", "corrected_sentence": "书上说，这一带曾是一种自然经济。", "error_description": "量词错误：“自然经济”是经济形式，量词应用“种”，不能用“只”。错句“一只自然经济”应改为“一种自然经济”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在书里读到过一只自然经济的形成。", "corrected_sentence": "我在书里读到过一种自然经济的形成。", "error_description": "量词错误：“自然经济”是经济形式，量词应用“种”，不能用“只”。错句“一只自然经济”应改为“一种自然经济”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96838, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "商品经济", "is_correct": true, "explanation": "正确。商品经济以交换为目的，与自然经济自给自足、不交换的特点相反。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”是自然地理事物，与“自然经济”不构成反义关系。"}, {"text": "书籍", "is_correct": false, "explanation": "“书籍”指印刷品，与“自然经济”不构成反义关系。"}, {"text": "医院", "is_correct": false, "explanation": "“医院”是治病的机构，与“自然经济”不构成反义关系。"}], "correct_answer": "商品经济", "explanations": {"商品经济": "正确。商品经济以交换为目的，与自然经济自给自足、不交换的特点相反。", "河流": "“河流”是自然地理事物，与“自然经济”不构成反义关系。", "书籍": "“书籍”指印刷品，与“自然经济”不构成反义关系。", "医院": "“医院”是治病的机构，与“自然经济”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96838, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "商品经济", "is_correct": true, "explanation": "正确。商品经济以交换为目的，与自然经济自给自足、不交换的特点相反。"}, {"text": "艺术", "is_correct": false, "explanation": "“艺术”指文化创作活动，与“自然经济”不构成反义关系。"}, {"text": "语言", "is_correct": false, "explanation": "“语言”指交流的工具，与“自然经济”不构成反义关系。"}, {"text": "工厂", "is_correct": false, "explanation": "“工厂”是生产场所，与“自然经济”不构成反义关系。"}], "correct_answer": "商品经济", "explanations": {"商品经济": "正确。商品经济以交换为目的，与自然经济自给自足、不交换的特点相反。", "艺术": "“艺术”指文化创作活动，与“自然经济”不构成反义关系。", "语言": "“语言”指交流的工具，与“自然经济”不构成反义关系。", "工厂": "“工厂”是生产场所，与“自然经济”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自给自足、不以交换为目的的经济形式。", "primary_collocate": null, "pronunciation": "zì rán jīng jì", "ipa": "tsɨ˥˩ ʐan˧˥ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "自然经济是一种自给自足的经济形式。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然经济不是为了交换而生产。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上我们学了自然经济和商品经济。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在自然经济中，家庭就是生产单位。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然经济的目的是满足自家的需要。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商品经济出现以后，自然经济就逐渐萎缩了。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个山村长期保留着自然经济的方式。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然经济和市场经济完全不同。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文写的是自然经济的形成。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然经济里，生产出来的东西主要自己用。", "target_word": "自然经济", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然經濟", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "自给自足、不为交换而生产的经济形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然经济", "is_correct": true, "explanation": "正确。自然经济指自给自足的经济形式，与句子的定义相符。"}, {"text": "农村", "is_correct": false, "explanation": "搭配：农村是地域，不是经济形式，“是一种……经济形式”要求名词指经济形态。"}, {"text": "教育", "is_correct": false, "explanation": "语义：教育不是自给自足的经济形式，与“自给自足”的意思相矛盾。"}, {"text": "工业", "is_correct": false, "explanation": "语义：工业以生产和交换为主，不能说是自给自足的经济形式。"}], "explanations": {"自然经济": "正确。自然经济指自给自足的经济形式，与句子的定义相符。", "农村": "搭配：农村是地域，不是经济形式，“是一种……经济形式”要求名词指经济形态。", "教育": "语义：教育不是自给自足的经济形式，与“自给自足”的意思相矛盾。", "工业": "语义：工业以生产和交换为主，不能说是自给自足的经济形式。"}, "sentence_index": 0, "correct_answer": "自然经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "改革以后，村子里的自然经济越来越发达。", "explanation": "这里应该用〈商品经济〉。自然经济不以交换为目的，不会“越来越发达”，应说商品经济。"}, {"text": "这个城市大力发展自然经济。", "explanation": "这里应该用〈市场经济〉。自然经济是不靠交换的形式，不能作为“大力发展”的对象。"}, {"text": "我们家的自然经济很困难。", "explanation": "这里应该用〈家庭经济〉。“自然经济”指经济形式，说一家人的经济状况困难要用“家庭经济”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然经济", "is_correct": true, "explanation": "正确。句子说山村长期延续的是自给自足的方式，与自然经济相符。"}, {"text": "工业化", "is_correct": false, "explanation": "语义：工业化是带来变化的发展过程，与“长期保留着”的旧方式相矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“保留着”后接“的方式”，手机不是可以保留的方式，搭配不当。"}, {"text": "城市化", "is_correct": false, "explanation": "语义：城市化会改变农村的生活，与“长期保留着”的旧方式冲突。"}], "explanations": {"自然经济": "正确。句子说山村长期延续的是自给自足的方式，与自然经济相符。", "工业化": "语义：工业化是带来变化的发展过程，与“长期保留着”的旧方式相矛盾。", "手机": "搭配：“保留着”后接“的方式”，手机不是可以保留的方式，搭配不当。", "城市化": "语义：城市化会改变农村的生活，与“长期保留着”的旧方式冲突。"}, "sentence_index": 6, "correct_answer": "自然经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个县的自然经济正在快速发展。", "explanation": "这里应该用〈农村经济〉。“自然经济”指自给自足、不以交换为目的的经济形式，不会“快速发展”，说某地经济快速发展要用农村经济。"}, {"text": "自然经济正在快速增长。", "explanation": "这里应该用〈国民经济〉。自然经济不以交换为目的，不谈“快速增长”，应说国民经济。"}, {"text": "我们要实行自然经济的管理制度。", "explanation": "这里应该用〈计划经济〉。“实行……管理制度”要说计划经济，自然经济不是管理制度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他研究的是一只自然经济。", "corrected_sentence": "他研究的是一种自然经济。", "error_description": "量词错误：“自然经济”是经济形式，量词应用“种”，不能用“只”。错句“一只自然经济”应改为“一种自然经济”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书专门讲一只自然经济的兴衰。", "corrected_sentence": "这本书专门讲一种自然经济的兴衰。", "error_description": "量词错误：“自然经济”是经济形式，量词应用“种”，不能用“只”。错句“一只自然经济”应改为“一种自然经济”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
