INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96839, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在中国国内卖的那一种东西。", "primary_collocate": null, "pronunciation": "guó xíng", "ipa": "kuo˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我买的是国行，不是港版。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台手机是国行的。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国行比国外版贵一点。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买国行，用着放心。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给我带了国行的相机。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的国行很便宜。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里只卖国行，没有进口的。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你买的是国行还是美版？", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国行有中文说明书。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国行在中国的商店都能买到。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國行", "label": "繁体"}, {"form": "国行版", "label": "复合"}], "register": "口语", "sense_fingerprint": "国行：在中国国内销售的那一种商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e8e5b6b-41e6-4dbe-82c6-698d5104ef7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国行", "is_correct": true, "explanation": "“国行”指在中国大陆销售的版本，与“港版”相对，句意通顺。"}, {"text": "港版", "is_correct": false, "explanation": "语义：句中已说“不是港版”，填入“港版”会自相矛盾。"}, {"text": "大米", "is_correct": false, "explanation": "搭配：“版”用于有版本区别的商品，大米没有版本之分，不能与“港版”对比。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以购买的东西，“我买的是……”后面接不上。"}], "explanations": {"国行": "“国行”指在中国大陆销售的版本，与“港版”相对，句意通顺。", "港版": "语义：句中已说“不是港版”，填入“港版”会自相矛盾。", "大米": "搭配：“版”用于有版本区别的商品，大米没有版本之分，不能与“港版”对比。", "空气": "语义：空气不是可以购买的东西，“我买的是……”后面接不上。"}, "sentence_index": 0, "correct_answer": "国行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台相机是国行的，是我在日本的商店买的。", "explanation": "这里应该用〈日版〉。国行指在中国国内卖的版本，在日本商店买的应说日版。"}, {"text": "这台游戏机是国行的，是我在韩国买的。", "explanation": "这里应该用〈韩版〉。国行指在中国国内卖的版本，在韩国买的应说韩版。"}, {"text": "这台手机是国行的，不能用中国的网络。", "explanation": "这里应该用〈国外版〉。国行指在中国大陆发行的版本，不能说它不能用中国的网络。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国行", "is_correct": true, "explanation": "“国行”指在中国大陆销售的版本，与后半句“没有进口的”相符。"}, {"text": "美版", "is_correct": false, "explanation": "语义：美版属于进口版本，与“没有进口的”矛盾。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“卖”的对象应是商品，不能说卖“友谊”。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天不是商店里可以卖的东西，句子不成立。"}], "explanations": {"国行": "“国行”指在中国大陆销售的版本，与后半句“没有进口的”相符。", "美版": "语义：美版属于进口版本，与“没有进口的”矛盾。", "友谊": "搭配：“卖”的对象应是商品，不能说卖“友谊”。", "春天": "语义：春天不是商店里可以卖的东西，句子不成立。"}, "sentence_index": 6, "correct_answer": "国行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台平板是国行的，只能在香港买。", "explanation": "这里应该用〈港版〉。国行指在中国国内卖的版本，这句说只能在香港买，应说港版。"}, {"text": "这款电视是国行的，要去美国的商店才能买到。", "explanation": "这里应该用〈美版〉。国行指在中国国内卖的版本，这句说要去美国才能买到，应说美版。"}, {"text": "这款耳机是国行的，只在国外卖。", "explanation": "这里应该用〈出口版〉。国行指在中国国内卖的版本，这句说只在国外卖，应说出口版。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
