INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96841, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "花很多力气，一直去做一件事。", "primary_collocate": null, "pronunciation": "zhì lì", "ipa": "tʂɨ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "他一生致力于教育工作。", "target_word": "致力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司致力于环境保护。", "target_word": "致力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她多年来致力于帮助穷人。", "target_word": "致力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们致力于让孩子们快乐地学习。", "target_word": "致力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们正在致力于研究新药。", "target_word": "致力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就致力于学好汉语。", "target_word": "致力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师致力于推广中文教育。", "target_word": "致力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府致力于提高大家的生活水平。", "target_word": "致力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸一直致力于这个小镇的发展。", "target_word": "致力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司致力于让客人满意。", "target_word": "致力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "致力于", "label": "常用搭配"}], "register": "书面", "sense_fingerprint": "长期花大力气专心做一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d88c77-461f-4c74-96b2-9f5f37a1c376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96841, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "致力", "is_correct": true, "explanation": "致力（zhìlì）：投入力量长期做某件事，即本词。"}, {"text": "直立", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是竖立、站直。"}, {"text": "治理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是管理、整治。"}, {"text": "自立", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），意思是不依赖他人。"}], "explanations": {"致力": "致力（zhìlì）：投入力量长期做某件事，即本词。", "直立": "zhí（第二声）与 zhì（第四声）声调不同，意思是竖立、站直。", "治理": "lǐ（第三声）与 lì（第四声）声调不同，意思是管理、整治。", "自立": "zì 与 zhì 声母不同（z 与 zh），意思是不依赖他人。"}, "sentence_index": null, "correct_answer": "致力"}, "level_3": {"options": [{"text": "致力", "is_correct": true, "explanation": "“致力于”表示长期投入力量，与“一生”和“教育工作”相配。"}, {"text": "厌倦", "is_correct": false, "explanation": "语义：“厌倦”表示不愿再做，与“一生”的长期投入相矛盾。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”表示不予重视，与“一生”的长期投入正相反。"}, {"text": "脱离", "is_correct": false, "explanation": "语义：“脱离”表示离开，与“一生”投身于教育工作的意思相反。"}], "explanations": {"致力": "“致力于”表示长期投入力量，与“一生”和“教育工作”相配。", "厌倦": "语义：“厌倦”表示不愿再做，与“一生”的长期投入相矛盾。", "忽视": "语义：“忽视”表示不予重视，与“一生”的长期投入正相反。", "脱离": "语义：“脱离”表示离开，与“一生”投身于教育工作的意思相反。"}, "sentence_index": 0, "correct_answer": "致力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场大雨致力于交通中断。", "explanation": "这里应该用〈致使〉。致力表示努力投入于某事，不能用来表示造成某种结果。"}, {"text": "我致力于明天去邮局寄信。", "explanation": "这里应该用〈打算〉。致力于指长期投入某项事业，一次性的寄信要用打算。"}, {"text": "我致力于每天吃三顿饭。", "explanation": "这里应该用〈坚持〉。致力于指长期投入某项事业，吃饭是日常习惯，不能用致力于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96841, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "致力", "is_correct": true, "explanation": "致力（zhìlì）：投入力量长期做某件事，即本词。"}, {"text": "势力", "is_correct": false, "explanation": "shì 与 zhì 声母不同（sh 与 zh），意思是权力和影响力量。"}, {"text": "斥力", "is_correct": false, "explanation": "chì 与 zhì 声母不同（ch 与 zh），意思是相互排斥的力。"}, {"text": "自力", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），意思是依靠自己的力量。"}], "explanations": {"致力": "致力（zhìlì）：投入力量长期做某件事，即本词。", "势力": "shì 与 zhì 声母不同（sh 与 zh），意思是权力和影响力量。", "斥力": "chì 与 zhì 声母不同（ch 与 zh），意思是相互排斥的力。", "自力": "zì 与 zhì 声母不同（z 与 zh），意思是依靠自己的力量。"}, "sentence_index": null, "correct_answer": "致力"}, "level_3": {"options": [{"text": "致力", "is_correct": true, "explanation": "“致力于”表示长期投入力量，与“推广中文教育”相配。"}, {"text": "反感", "is_correct": false, "explanation": "语义：“反感”表示厌恶，与老师推广中文教育的行为相反。"}, {"text": "排斥", "is_correct": false, "explanation": "语义：“排斥”表示拒绝接受，与“推广”的意图相反。"}, {"text": "回避", "is_correct": false, "explanation": "配价：“回避”后直接带宾语，不带“于”，句中结构不符。"}], "explanations": {"致力": "“致力于”表示长期投入力量，与“推广中文教育”相配。", "反感": "语义：“反感”表示厌恶，与老师推广中文教育的行为相反。", "排斥": "语义：“排斥”表示拒绝接受，与“推广”的意图相反。", "回避": "配价：“回避”后直接带宾语，不带“于”，句中结构不符。"}, "sentence_index": 6, "correct_answer": "致力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们致力于下午去洗车。", "explanation": "这里应该用〈安排〉。致力于指长期投入某项事业，下午去洗车只是一次性安排，不能用致力于。"}, {"text": "我致力于今晚去听一场音乐会。", "explanation": "这里应该用〈计划〉。致力于指长期投入某项事业，今晚去听音乐会是一次性安排，不能用致力于。"}, {"text": "他致力于做完今天的作业。", "explanation": "这里应该用〈完成〉。致力于指长期投入某项事业，今天的作业是一次性任务，不能用致力于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个组织多年来一直致力在扶贫。", "corrected_sentence": "这个组织多年来一直致力于扶贫。", "error_description": "“致力”后应接介词“于”，不能用“在”，应为“致力于扶贫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校一直致力于着培养学生。", "corrected_sentence": "这所学校一直致力于培养学生。", "error_description": "错误：“致力于”后面误加了“着”，写成“致力于着培养学生”。正确：“致力于培养学生”，“于”是介词，后面直接接要做的事，不能加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
