INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96843, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "都可以。", "primary_collocate": null, "pronunciation": "jūn kě", "ipa": "tɕyn⁵⁵ kʰɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "付钱用现金或手机均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周六或周日来均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色或蓝色均可，我两种都喜欢。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车或走路去均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名打电话或上网均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭或面条均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生和老师均可参加。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你写汉字或拼音均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上或晚上来均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用笔或用电脑写均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "列出几种选择，每一种都被允许", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '594414c6-35fb-4d2f-972b-7aa2cfad39ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96843, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均可", "is_correct": true, "explanation": "正确。“均可”表示几种选择都可以，与“现金或手机”的并列结构相符。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”是时间副词，必须修饰后面的动词，不能单独放在句末。"}, {"text": "曾经", "is_correct": false, "explanation": "语法：“曾经”表示过去有过某种经历，要修饰动词，不能单独结句，也不表示允许。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指不久以前的时间，不能表示几种付款方式都可以。"}], "explanations": {"均可": "正确。“均可”表示几种选择都可以，与“现金或手机”的并列结构相符。", "已经": "语法：“已经”是时间副词，必须修饰后面的动词，不能单独放在句末。", "曾经": "语法：“曾经”表示过去有过某种经历，要修饰动词，不能单独结句，也不表示允许。", "刚才": "语义：“刚才”指不久以前的时间，不能表示几种付款方式都可以。"}, "sentence_index": 0, "correct_answer": "均可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个人去，均可。", "explanation": "这里应用〈可以〉。〈均可〉需要并列的几种选择，句中只有一种情况，不能用“均可”。"}, {"text": "他很高兴，均可。", "explanation": "这里误把〈均可〉当成对心情的评价（意思是“行”）。〈均可〉表示几种选择都行，不能用来描述人的情绪。"}, {"text": "妈妈做的菜很好吃，均可。", "explanation": "这里误把〈均可〉当成对食物味道的评价（意思是“行”）。〈均可〉表示几种选择都行，不能用来评价味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "均可", "is_correct": true, "explanation": "正确。“均可”表示两类人都能参加，与句意相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与“都可以参加”的允许义不符。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”说的是巧合，不表示许可，与句意不符。"}, {"text": "好像", "is_correct": false, "explanation": "语义：“好像”表示推测，不用于说明参加资格，与句意不符。"}], "explanations": {"均可": "正确。“均可”表示两类人都能参加，与句意相符。", "竟然": "语义：“竟然”表示出乎意料，与“都可以参加”的允许义不符。", "恰好": "语义：“恰好”说的是巧合，不表示许可，与句意不符。", "好像": "语义：“好像”表示推测，不用于说明参加资格，与句意不符。"}, "sentence_index": 6, "correct_answer": "均可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事我已经做完，均可。", "explanation": "这里误把〈均可〉当成说明事情已经完成的词。〈均可〉只表示几种选择都行，不说明事情的完成情况。"}, {"text": "他跑得很快，均可。", "explanation": "这里误把〈均可〉当成评价速度的词（意思是“行”）。〈均可〉不用来描述动作的快慢。"}, {"text": "大家都很累，均可。", "explanation": "这里误把〈均可〉当成描述状态的词（意思是“行”）。〈均可〉不用来描述人的疲劳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "搭地铁或骑车去均可了。", "corrected_sentence": "搭地铁或骑车去均可。", "error_description": "错误：“均可”后面加了“了”。正确形式是“搭地铁或骑车去均可。”“均可”表示允许，是状态性的说法，不带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "男生和女生很均可报名。", "corrected_sentence": "男生和女生均可报名。", "error_description": "错误：程度副词“很”加在了“均可”前面。“均可”是副词，不能再被“很”修饰，正确形式是“男生和女生均可报名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
