INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96844, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "都可以；都行。", "primary_collocate": null, "pronunciation": "jūn kě", "ipa": "tɕyn⁵⁵ kʰɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "我们去公园或去商店均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时间由你定，上午下午均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买苹果或香蕉均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住大房间或小房间均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说吃中餐或西餐均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用哪种方法学习均可，只要多练习。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门票现在买或明天买均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们玩球或看书均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你坐前面或坐后面均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝茶或喝咖啡均可。", "target_word": "均可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "表示怎么选都行，说话人不挑剔", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '594414c6-35fb-4d2f-972b-7aa2cfad39ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均可", "is_correct": true, "explanation": "正确。“均可”表示去公园、去商店都行，说话人不挑剔。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”要修饰后面的动词，不能单独放在句末。"}, {"text": "曾经", "is_correct": false, "explanation": "语法：“曾经”表示过去的经历，要修饰动词，不能单独结句。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指时间，不能表示几种选择都可以。"}], "explanations": {"均可": "正确。“均可”表示去公园、去商店都行，说话人不挑剔。", "已经": "语法：“已经”要修饰后面的动词，不能单独放在句末。", "曾经": "语法：“曾经”表示过去的经历，要修饰动词，不能单独结句。", "刚才": "语义：“刚才”指时间，不能表示几种选择都可以。"}, "sentence_index": 0, "correct_answer": "均可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书很贵，均可。", "explanation": "这里误把〈均可〉当成评价价格的词（意思是“值”）。〈均可〉只表示几种选择都行，不用来说明价格。"}, {"text": "天气很冷，均可。", "explanation": "这里误把〈均可〉当成描述天气的词（意思是“行”）。〈均可〉不用来说明天气状况。"}, {"text": "他很聪明，均可。", "explanation": "这里误把〈均可〉当成评价能力的词（意思是“行”）。〈均可〉不用来评价人的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "均可", "is_correct": true, "explanation": "正确。“均可”表示两个时间买都行，与句意相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，要修饰后面的动作，不能单独结句。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示巧合，不表示两种选择都可以。"}, {"text": "好像", "is_correct": false, "explanation": "语义：“好像”表示推测，不能单独放在句末表示许可。"}], "explanations": {"均可": "正确。“均可”表示两个时间买都行，与句意相符。", "竟然": "语义：“竟然”表示出乎意料，要修饰后面的动作，不能单独结句。", "恰好": "语义：“恰好”表示巧合，不表示两种选择都可以。", "好像": "语义：“好像”表示推测，不能单独放在句末表示许可。"}, "sentence_index": 6, "correct_answer": "均可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我已经喝完了，均可。", "explanation": "这里误把〈均可〉当成说明动作已经完成的词。〈均可〉只表示几种选择都行，不表示动作的完成。"}, {"text": "他的咖啡很苦，均可。", "explanation": "这里误把〈均可〉当成评价味道的词（意思是“还行”）。〈均可〉只表示几种选择都行，不用来评价味道。"}, {"text": "房间里很安静，均可。", "explanation": "这里误把〈均可〉当成描述环境的词（意思是“行”）。〈均可〉不用来描述环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你选黑色或白色均可了。", "corrected_sentence": "你选黑色或白色均可。", "error_description": "错误：“均可”后面加了“了”。正确形式是“你选黑色或白色均可。”“均可”是状态性的允许说法，不带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周一或周二去很均可。", "corrected_sentence": "周一或周二去均可。", "error_description": "错误：程度副词“很”加在了“均可”前面。“均可”是副词，不能再被“很”修饰，正确形式是“周一或周二去均可”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f2b02a6-45b2-44fe-be21-316116f6b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
