INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96847, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做运动或者办活动用的一块空地。", "primary_collocate": null, "pronunciation": "chǎng dì", "ipa": "tʂʰaŋ˨˩˦ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这个场地很大，可以踢足球。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在学校的场地上跑步。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天的比赛场地还没有找好。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "租场地要花不少钱。", "target_word": "场地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在场地中间玩游戏。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块场地下雨以后很滑。", "target_word": "场地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司想找一个办活动的场地。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们正在打扫场地。", "target_word": "场地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个场地可以坐三百个人。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把场地布置得很漂亮。", "target_word": "场地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块场地", "label": "量词"}, {"form": "一片场地", "label": "量词"}, {"form": "场地费", "label": "复合"}, {"form": "場地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做运动或办活动用的空地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad778c81-0308-42c1-ae9b-f236d49633da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场地", "is_correct": true, "explanation": "场地指做运动或办活动用的空地，与“很大”和“踢足球”相符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是用来学习的书，不是能用来踢足球的地方。"}, {"text": "水平", "is_correct": false, "explanation": "搭配：说水平时用“高”或“低”，不说“很大”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，不能用来踢足球。"}], "explanations": {"场地": "场地指做运动或办活动用的空地，与“很大”和“踢足球”相符。", "课本": "语义：课本是用来学习的书，不是能用来踢足球的地方。", "水平": "搭配：说水平时用“高”或“低”，不说“很大”。", "窗户": "语义：窗户是墙上的开口，不能用来踢足球。"}, "sentence_index": 0, "correct_answer": "场地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛结束时，场地十分激动人心。", "explanation": "这里应该用〈场面〉。场面指眼前的情景，可以说“激动人心”；场地指做运动或办活动的空地，不能用来形容情景。"}, {"text": "在正式场地要穿得整齐一些。", "explanation": "这里应该用〈场合〉。“正式场合”是常见说法；场地指实际的空地，不能说“正式场地”。"}, {"text": "他在会上提出的场地很有价值。", "explanation": "这里应该用〈建议〉。建议指提出的意见；场地指做运动或办活动的空地，不能用来指意见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场地", "is_correct": true, "explanation": "场地指办活动用的空地，可以被“办活动的”修饰，也能被“找”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是办活动的地方，“办活动的手机”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“找”的对象是地方或人，不说找“天气”来办活动。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被找来办活动，句子说不通。"}], "explanations": {"场地": "场地指办活动用的空地，可以被“办活动的”修饰，也能被“找”。", "手机": "语义：手机不是办活动的地方，“办活动的手机”说不通。", "天气": "搭配：“找”的对象是地方或人，不说找“天气”来办活动。", "空气": "语义：空气不能被找来办活动，句子说不通。"}, "sentence_index": 6, "correct_answer": "场地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坚持自己的场地，不愿妥协。", "explanation": "这里应该用〈立场〉。立场指对问题的态度和观点；场地是实际的空地，不能用来指观点。"}, {"text": "这件事还有商量的场地。", "explanation": "这里应该用〈余地〉。余地指可以变通的空间；场地是做运动或办活动的空地，不能指可商量的余地。"}, {"text": "他在公司的场地很高。", "explanation": "这里应该用〈地位〉。地位指身份和位置的高低；场地是实际的空地，不能用来说人的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们场地里玩耍。", "corrected_sentence": "孩子们在场地里玩耍。", "error_description": "错误形式：“孩子们场地里玩耍”；正确形式：“孩子们在场地里玩耍”。“场地里”作地点状语，前面要加介词“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天在这只场地比赛。", "corrected_sentence": "我们明天在这块场地比赛。", "error_description": "错误形式：“这只场地”；正确形式：“这块场地”。场地是一块地，量词要用“块”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
