INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "进行活动或比赛的空地。", "primary_collocate": null, "pronunciation": "chǎng dì", "ipa": "tʂʰaŋ˨˩˦ ti˥˩", "syllable_count": 2, "sentences": [{"text": "场地里有很多踢球的孩子。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛场地离我家很近。", "target_word": "场地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨了，我们换了场地。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个场地不够大，放不下桌子。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们先去场地集合。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在空场地上练习跳舞。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们想订一个打篮球的场地。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的场地每天早上八点开门。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，大家检查了场地。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新场地比旧场地干净多了。", "target_word": "场地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块场地", "label": "量词"}, {"form": "一片场地", "label": "量词"}, {"form": "场地费", "label": "复合"}, {"form": "場地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "进行活动或比赛的空地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad778c81-0308-42c1-ae9b-f236d49633da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场地", "is_correct": true, "explanation": "场地指进行活动或比赛的空地，孩子们可以在这里踢球。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是存放食物的电器，里面不会有踢球的孩子。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，里面不能有踢球的孩子。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”是抽象的东西，不能说“性格里有孩子”。"}], "explanations": {"场地": "场地指进行活动或比赛的空地，孩子们可以在这里踢球。", "冰箱": "语义：冰箱是存放食物的电器，里面不会有踢球的孩子。", "窗户": "语义：窗户是墙上的开口，里面不能有踢球的孩子。", "性格": "搭配：“性格”是抽象的东西，不能说“性格里有孩子”。"}, "sentence_index": 0, "correct_answer": "场地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天早上去场地买菜。", "explanation": "这里应该用〈市场〉。市场是买卖东西的地方；场地是做运动或办活动的空地，不是买菜的地方。"}, {"text": "听到这个消息，他的场地很激动。", "explanation": "这里应该用〈情绪〉。情绪指人的心理状态，可以说“情绪激动”；场地指做运动或办活动的空地，不能用来形容人的心理。"}, {"text": "我们守住了场地，敌人没有前进一步。", "explanation": "这里应该用〈阵地〉。阵地指作战的地方；场地指做运动或办活动的空地，不用于战争。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场地", "is_correct": true, "explanation": "场地指进行比赛或活动的空地，“打篮球的”可以修饰它，也能被“订”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能用来打篮球，“打篮球的歌曲”说不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“订”的对象是具体的场所或服务，不说订“心情”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的功课，不能用来打篮球。"}], "explanations": {"场地": "场地指进行比赛或活动的空地，“打篮球的”可以修饰它，也能被“订”。", "歌曲": "语义：歌曲不能用来打篮球，“打篮球的歌曲”说不通。", "心情": "搭配：“订”的对象是具体的场所或服务，不说订“心情”。", "作业": "语义：作业是学生的功课，不能用来打篮球。"}, "sentence_index": 6, "correct_answer": "场地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块场地很肥沃，适合种小麦。", "explanation": "这里应该用〈土地〉。土地指可以种庄稼的地；场地是做运动或办活动的空地，不能用来说肥沃。"}, {"text": "大学毕业后，他想去外面闯出一片新场地。", "explanation": "这里应该用〈天地〉。“闯出一片新天地”指开创新的发展空间；场地只指实际的空地。"}, {"text": "他在剧中担任的场地很重要。", "explanation": "这里应该用〈角色〉。角色指人在某件事中所起的作用，可以说“角色很重要”；场地指做运动或办活动的空地，不能用来指作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运动员场地上热身。", "corrected_sentence": "运动员在场地上热身。", "error_description": "错误形式：“运动员场地上热身”；正确形式：“运动员在场地上热身”。“场地上”作地点状语，要用“在”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在这只场地里练习过两次。", "corrected_sentence": "我们在这片场地里练习过两次。", "error_description": "错误形式：“这只场地”；正确形式：“这片场地”。“场地”是面积较大的空地，应用量词“片”计量，“只”多用于动物等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
