INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96849, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始动手去做一件事。", "primary_collocate": null, "pronunciation": "zhuó shǒu", "ipa": "ʈʂwo˧˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个周末我要着手整理房间。", "target_word": "着手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先着手准备明天的会议吧。", "target_word": "着手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚着手写这本书。", "target_word": "着手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生已经着手检查病人了。", "target_word": "着手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你打算从哪里着手学习汉语？", "target_word": "着手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起着手解决这个问题。", "target_word": "着手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司着手做新的计划了。", "target_word": "着手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈昨天着手打扫厨房。", "target_word": "着手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很早就着手准备考试。", "target_word": "着手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该马上着手修这条路。", "target_word": "着手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "着手了", "label": "体标（了）"}, {"form": "着手过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "开始动手做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8adc1b-9d40-4b43-9a93-25a8a9f56bae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96849, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "着手", "is_correct": true, "explanation": "正确。着手（zhuó shǒu）指开始动手去做一件事。"}, {"text": "住手", "is_correct": false, "explanation": "住手读 zhù shǒu，与 zhuó shǒu 韵母（u/uo）和声调都不同，听起来相近。住手的意思是停下来，不是开始做。"}, {"text": "助手", "is_correct": false, "explanation": "助手读 zhù shǒu，与 zhuó shǒu 韵母（u/uo）和声调都不同，听起来相近。助手的意思是帮忙的人。"}, {"text": "驻守", "is_correct": false, "explanation": "驻守读 zhù shǒu，与 zhuó shǒu 韵母（u/uo）和声调都不同，听起来相近。驻守的意思是守卫在某地，不是开始做。"}], "explanations": {"着手": "正确。着手（zhuó shǒu）指开始动手去做一件事。", "住手": "住手读 zhù shǒu，与 zhuó shǒu 韵母（u/uo）和声调都不同，听起来相近。住手的意思是停下来，不是开始做。", "助手": "助手读 zhù shǒu，与 zhuó shǒu 韵母（u/uo）和声调都不同，听起来相近。助手的意思是帮忙的人。", "驻守": "驻守读 zhù shǒu，与 zhuó shǒu 韵母（u/uo）和声调都不同，听起来相近。驻守的意思是守卫在某地，不是开始做。"}, "sentence_index": null, "correct_answer": "着手"}, "level_3": {"options": [{"text": "着手", "is_correct": true, "explanation": "正确。“这个周末我要着手整理房间”表示准备动手去做，符合句意。"}, {"text": "动身", "is_correct": false, "explanation": "搭配：“动身”指出发去某地，不能接“整理房间”这样的事情。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“要”表达的主动打算相矛盾，句子读不通。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”的对象是人或成就，不能接“整理房间”。"}], "explanations": {"着手": "正确。“这个周末我要着手整理房间”表示准备动手去做，符合句意。", "动身": "搭配：“动身”指出发去某地，不能接“整理房间”这样的事情。", "讨厌": "语义：“讨厌”表示厌恶，与“要”表达的主动打算相矛盾，句子读不通。", "祝贺": "搭配：“祝贺”的对象是人或成就，不能接“整理房间”。"}, "sentence_index": 0, "correct_answer": "着手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气着手变冷了。", "explanation": "这里应该用〈开始〉。着手指人主动动手去做具体的事，天气变化不能用着手。"}, {"text": "他着手爱上了这座城市。", "explanation": "这里应该用〈开始〉。着手指人动手去办具体事务，爱上是逐渐产生的感情，不是可以动手去做的事，不能用着手。"}, {"text": "孩子着手长大了。", "explanation": "这里应该用〈开始〉。着手指人有计划地动手去做事，孩子的生长是自然过程，不能用着手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着手", "is_correct": true, "explanation": "正确。“公司着手做新的计划了”表示公司开始动手去做，符合句意。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能接“做新的计划”。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是人或帮助，不能接“做新的计划”。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：“歌颂”表示赞美，与“做新的计划”的客观叙述不符，句子读不通。"}], "explanations": {"着手": "正确。“公司着手做新的计划了”表示公司开始动手去做，符合句意。", "参观": "搭配：“参观”的对象是场所或展览，不能接“做新的计划”。", "感谢": "搭配：“感谢”的对象是人或帮助，不能接“做新的计划”。", "歌颂": "语义：“歌颂”表示赞美，与“做新的计划”的客观叙述不符，句子读不通。"}, "sentence_index": 6, "correct_answer": "着手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家着手欢迎新同学。", "explanation": "这里应该用〈开始〉。着手指动手去办具体事务，欢迎新同学是一次性的礼节动作，不能用着手。"}, {"text": "他同意了，着手点了点头。", "explanation": "这里应该用〈开始〉。着手指动手去办具体事务，点头是随手就能做的小动作，不能用着手。"}, {"text": "观众着手鼓掌了。", "explanation": "这里应该用〈开始〉。着手指有计划地动手去办具体事务，鼓掌是随时可以做的动作，不能用着手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚着手了准备行李。", "corrected_sentence": "他刚着手准备行李。", "error_description": "“了”位置错误：“着手”是一个整体动词，“了”不能插在“着手”和后面的动词之间。错误形式是“着手了准备行李”，正确形式是“着手准备行李”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂已经着手房子。", "corrected_sentence": "这家工厂已经着手装修房子。", "error_description": "“着手”后面必须接动词或动词短语，表示要开始做的动作。错误形式“着手房子”缺少动词，正确形式是“着手装修房子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96851, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96851, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96851, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事发生时看到的样子和情景。", "primary_collocate": null, "pronunciation": "chǎng miàn", "ipa": "ʈʂʰaŋ˨˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "车祸的场面太可怕了。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不敢看那个场面。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后的场面让人难过。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把当时的场面讲给我们听。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到火灾的场面，大家都很害怕。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个场面我在电视上看过。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天的场面，我到现在还记得。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球赛的最后一个场面特别精彩。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们抢着吃饭的场面很有意思。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了很多战斗的场面。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个场面", "label": "量词"}], "register": "通用", "sense_fingerprint": "事情发生时亲眼看到的样子和情景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96851, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场面", "is_correct": true, "explanation": "正确。句子说车祸发生时的情景太可怕，场面符合语境。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：湖泊是地理事物，不能是车祸的情景，句子的意思说不通。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味不能用于描述车祸现场，句子的意思说不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“可怕”可以形容情景，人的脾气不说“车祸的脾气”。"}], "explanations": {"场面": "正确。句子说车祸发生时的情景太可怕，场面符合语境。", "湖泊": "语义：湖泊是地理事物，不能是车祸的情景，句子的意思说不通。", "香味": "语义：香味不能用于描述车祸现场，句子的意思说不通。", "脾气": "搭配：“可怕”可以形容情景，人的脾气不说“车祸的脾气”。"}, "sentence_index": 0, "correct_answer": "场面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的场面很快地跑了过去。", "explanation": "这里应该用〈动作〉。“场面”指看到的情景，不能“跑”，要说动作。"}, {"text": "那位篮球运动员的场面很高。", "explanation": "这里应该用〈个子〉。“场面”指看到的情景，不能用来说人的身材；说人高矮要用个子。"}, {"text": "我想吃场面。", "explanation": "这里应该用〈米饭〉。“场面”指看到的情景，不能吃，要吃的是饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96851, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场面", "is_correct": true, "explanation": "正确。句子说那天的情景到现在还记得，场面符合语境。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法不是可以回忆的情景，句子的意思说不通。"}, {"text": "电费", "is_correct": false, "explanation": "语义：电费是账单上的金额，不是可以回忆的情景。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：海拔是地点的高度，不能说“那天的海拔”，与句子搭配不当。"}], "explanations": {"场面": "正确。句子说那天的情景到现在还记得，场面符合语境。", "语法": "语义：语法不是可以回忆的情景，句子的意思说不通。", "电费": "语义：电费是账单上的金额，不是可以回忆的情景。", "海拔": "搭配：海拔是地点的高度，不能说“那天的海拔”，与句子搭配不当。"}, "sentence_index": 6, "correct_answer": "场面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "场面延迟了两个小时。", "explanation": "这里应该用〈航班〉。“场面”不能“延迟”，延迟的是航班、会议等安排。"}, {"text": "场面上涨了，大家都很不满。", "explanation": "这里应该用〈价格〉。“场面”不能“上涨”，上涨的是价格。"}, {"text": "工资提高了百分之十，生活场面也提高了。", "explanation": "这里应该用〈水平〉。“场面”指看到的情景，不能“提高”；说生活变好要用“生活水平提高了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我看到了一条可怕的场面。", "corrected_sentence": "我看到了一个可怕的场面。", "error_description": "量词错误：“场面”的量词是“个”，“条”用于细长的东西，不能修饰场面。错句“一条可怕的场面”应改为“一个可怕的场面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我永远忘不了那条可怕的场面。", "corrected_sentence": "我永远忘不了那个可怕的场面。", "error_description": "量词错误：“场面”的量词是“个”，“条”用于细长的东西，不能修饰场面。错句“那条可怕的场面”应改为“那个可怕的场面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96852, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
