INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96852, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一定场合下呈现的情景。", "primary_collocate": null, "pronunciation": "chǎng miàn", "ipa": "ʈʂʰaŋ˨˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "婚礼的场面非常热闹。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开幕式的场面让我很感动。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他见过大场面，一点也不紧张。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个欢迎场面我永远忘不了。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上的场面有点儿尴尬。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里有一个很大的战争场面。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束时，场面十分感人。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评他的时候，场面很安静。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们唱歌的场面真可爱。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时一家人吃饭的场面最温暖。", "target_word": "场面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个场面", "label": "量词"}], "register": "通用", "sense_fingerprint": "某种场合中呈现出的气氛和情景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "场面", "is_correct": true, "explanation": "正确。句子说婚礼的情景非常热闹，场面符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能“热闹”，句子描述的是现场的情景和气氛。"}, {"text": "质量", "is_correct": false, "explanation": "搭配：“热闹”形容情景或气氛，不能与“质量”搭配。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业与婚礼的热闹情景无关，句子说不通。"}], "explanations": {"场面": "正确。句子说婚礼的情景非常热闹，场面符合语境。", "价格": "语义：价格不能“热闹”，句子描述的是现场的情景和气氛。", "质量": "搭配：“热闹”形容情景或气氛，不能与“质量”搭配。", "作业": "语义：作业与婚礼的热闹情景无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "场面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动的场面是下午三点。", "explanation": "这里应该用〈时间〉。“场面”指看到的情景，说活动的时刻要用“时间”。"}, {"text": "我们约好的场面是车站。", "explanation": "这里应该用〈地点〉。“场面”不能用来指见面的地方，应说地点。"}, {"text": "这种场面很有效，值得推广。", "explanation": "这里应该用〈方式〉。“场面”指情景，不能说“有效”，有效的是方式、方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "场面", "is_correct": true, "explanation": "正确。句子说比赛结束时的情景十分感人，场面符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能“感人”，句子说的是比赛结束时的情景。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法不是能让人感动的情景，句子的意思说不通。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是入场的凭证，不能“感人”，句子说的是比赛结束时的情景。"}], "explanations": {"场面": "正确。句子说比赛结束时的情景十分感人，场面符合语境。", "天气": "语义：天气不能“感人”，句子说的是比赛结束时的情景。", "语法": "语义：语法不是能让人感动的情景，句子的意思说不通。", "门票": "语义：门票是入场的凭证，不能“感人”，句子说的是比赛结束时的情景。"}, "sentence_index": 6, "correct_answer": "场面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的场面很好听，大家都记住了。", "explanation": "这里应该用〈名字〉。“场面”指情景，不能说“好听”，好听的是名字。"}, {"text": "他的场面丢了，只好去补办。", "explanation": "这里应该用〈身份证〉。“场面”是情景，不能说“丢了”，要补办的是身份证。"}, {"text": "老师说明天要交场面。", "explanation": "这里应该用〈作业〉。“场面”指看到的情景，不能“交”，要交的是作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们拍到了一只很感人的场面。", "corrected_sentence": "我们拍到了一个很感人的场面。", "error_description": "量词错误：“场面”的量词是“个”，“只”用于动物等，不能修饰场面。错句“一只很感人的场面”应改为“一个很感人的场面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人最怀念的是那张全家团聚的场面。", "corrected_sentence": "老人最怀念的是那个全家团聚的场面。", "error_description": "量词错误：“场面”的量词是“个”，“张”用于纸、照片等平面的东西，不能修饰场面。错句“那张全家团聚的场面”应改为“那个全家团聚的场面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
