INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96853, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人想去哪就能去哪，没有人拦。", "primary_collocate": null, "pronunciation": "xíng dòng zì yóu", "ipa": "ɕiŋ˧˥ tʊŋ˥˩ tsɨ˥˩ joʊ˧˥", "syllable_count": 4, "sentences": [{"text": "退休以后，我有了行动自由，想去哪就去哪。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "腿好了以后，他又有了行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞出笼子，有了行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿受伤了，现在没有行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗用绳子拴着，没有行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生离开家，终于有了行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，想要更多的行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪封路，大家都没有行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢一个人旅行，因为有行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住进医院后，她失去了行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "想去哪就去哪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f797344-34e1-4b24-8621-ea8ced756a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行动自由", "is_correct": true, "explanation": "正确：“行动自由”指想去哪就去哪的自由，与“想去哪就去哪”的语境吻合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“有了体重”不能使人想去哪就去哪，句子语义不通。"}, {"text": "口音", "is_correct": false, "explanation": "语义：口音与能否想去哪没有因果关系，句子读起来不通。"}, {"text": "人品", "is_correct": false, "explanation": "搭配：“人品”不能作为想去哪就去哪的条件，“有了人品”与后句的因果关系不成立。"}], "explanations": {"行动自由": "正确：“行动自由”指想去哪就去哪的自由，与“想去哪就去哪”的语境吻合。", "体重": "语义：“有了体重”不能使人想去哪就去哪，句子语义不通。", "口音": "语义：口音与能否想去哪没有因果关系，句子读起来不通。", "人品": "搭配：“人品”不能作为想去哪就去哪的条件，“有了人品”与后句的因果关系不成立。"}, "sentence_index": 0, "correct_answer": "行动自由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月领到行动自由，全部寄给了父母。", "explanation": "这里应该用〈工资〉。〈行动自由〉是人身活动的权利，不能像钱一样领取、寄出。"}, {"text": "这条路的行动自由很大，车子很少。", "explanation": "这里应该用〈通行〉。“行动自由”只用于人，不用来形容道路。"}, {"text": "他的腿受伤了，行动自由很高。", "explanation": "搭配：“行动自由”的程度通常说“大”或“小”，“很高”不自然，应改为〈很小〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行动自由", "is_correct": true, "explanation": "正确：“想要更多的行动自由”指长大后希望获得更多的活动权利，语境吻合。"}, {"text": "纸张", "is_correct": false, "explanation": "语义：孩子长大后想要更多的“纸张”，语境不通，与“长大”的诉求无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不是孩子长大后会想要更多的东西，句子语义不通。"}, {"text": "体型", "is_correct": false, "explanation": "搭配：“想要更多的体型”不成立，“体型”不能像“自由”那样被追求更多。"}], "explanations": {"行动自由": "正确：“想要更多的行动自由”指长大后希望获得更多的活动权利，语境吻合。", "纸张": "语义：孩子长大后想要更多的“纸张”，语境不通，与“长大”的诉求无关。", "味道": "语义：“味道”不是孩子长大后会想要更多的东西，句子语义不通。", "体型": "搭配：“想要更多的体型”不成立，“体型”不能像“自由”那样被追求更多。"}, "sentence_index": 6, "correct_answer": "行动自由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "住进医院后，她的思想失去了行动自由。", "explanation": "这里应该用〈思想自由〉。“行动自由”指身体活动的权利，不指思想。"}, {"text": "住进医院后，她交了一笔行动自由。", "explanation": "这里应该用〈押金〉。〈行动自由〉是人身活动的权利，不是能交付的钱款。"}, {"text": "住进医院后，她用行动自由决定治疗方案。", "explanation": "这里应该用〈自主〉。〈行动自由〉指人身活动的权利，不能表示自行决定治疗的权力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她出院以后，又恢复着行动自由。", "corrected_sentence": "她出院以后，又恢复了行动自由。", "error_description": "体标错误：“恢复行动自由”是已经完成的变化，要用“了”，不能用表示持续的“着”。正确：“她出院以后，又恢复了行动自由。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他重新获得了大很的行动自由。", "corrected_sentence": "他重新获得了很大的行动自由。", "error_description": "错误：“很”应放在形容词“大”之前，应说〈很大的行动自由〉，不能说〈大很〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
