INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人身自由；可以自行活动的权利。", "primary_collocate": null, "pronunciation": "xíng dòng zì yóu", "ipa": "ɕiŋ˧˥ tʊŋ˥˩ tsɨ˥˩ joʊ˧˥", "syllable_count": 4, "sentences": [{"text": "法律保护每个公民的行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "犯人失去了行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宪法规定公民享有行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府应该尊重公民的行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐了三年牢，没有行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规定限制了学生的行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察不能随便限制别人的行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有行动自由的权利。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关押犯人会限制他们的行动自由。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有行动自由的人，生活很痛苦。", "target_word": "行动自由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人身自由的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f797344-34e1-4b24-8621-ea8ced756a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行动自由", "is_correct": true, "explanation": "正确：“行动自由”指人身自由、可以自行活动的权利，正是法律保护的对象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：法律保护的是公民的权利，“天气”不是可以被保护的权利，句子读起来不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的数值，不属于法律保护公民的权利范畴。"}, {"text": "老底", "is_correct": false, "explanation": "语域：“老底”是口语，指人的底细或隐私，与法律条文的书面语不搭。"}], "explanations": {"行动自由": "正确：“行动自由”指人身自由、可以自行活动的权利，正是法律保护的对象。", "天气": "语义：法律保护的是公民的权利，“天气”不是可以被保护的权利，句子读起来不通。", "体重": "语义：体重是身体的数值，不属于法律保护公民的权利范畴。", "老底": "语域：“老底”是口语，指人的底细或隐私，与法律条文的书面语不搭。"}, "sentence_index": 0, "correct_answer": "行动自由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末是我的行动自由，我可以睡到中午。", "explanation": "这里应该用〈自由时间〉。〈行动自由〉指人身活动的权利，不指一段空闲的时间。"}, {"text": "这个运动员的行动自由很好，动作很标准。", "explanation": "这里应该用〈行动灵活〉。“行动自由”指人身活动的权利，不用来形容身体动作灵巧。"}, {"text": "这辆汽车的行动自由很大，能去任何地方。", "explanation": "这里应该用〈机动性〉。“行动自由”只指人的活动权利，不能用来形容车辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行动自由", "is_correct": true, "explanation": "正确：“限制别人的行动自由”是常见搭配，指限制人身活动的权利。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是身体的数值，警察不能限制它，句子读起来不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“限制”一般不与“心情”搭配，人的心情无法被限制。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不能被警察限制，句子语义不通。"}], "explanations": {"行动自由": "正确：“限制别人的行动自由”是常见搭配，指限制人身活动的权利。", "体温": "语义：“体温”是身体的数值，警察不能限制它，句子读起来不通。", "心情": "搭配：“限制”一般不与“心情”搭配，人的心情无法被限制。", "天空": "语义：“天空”不能被警察限制，句子语义不通。"}, "sentence_index": 6, "correct_answer": "行动自由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有权用行动自由决定工作时间。", "explanation": "这里应该用〈自主〉。〈行动自由〉指人身活动的权利，不能用来表示自行决定事务的权力。"}, {"text": "他的思想很有行动自由。", "explanation": "这里应该用〈思想自由〉。“行动自由”只指身体的活动，不指思想。"}, {"text": "他把行动自由送给了朋友，朋友很感动。", "explanation": "这里应该用〈礼物〉。〈行动自由〉是人身活动的权利，不是能赠送的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人都应该享有一把基本的行动自由。", "corrected_sentence": "每个人都应该享有一项基本的行动自由。", "error_description": "错误：“一把”用于有柄的器具，“行动自由”是抽象权利，应该用〈一项〉。正确：一项基本的行动自由。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座小城的居民行动自由大很。", "corrected_sentence": "这座小城的居民行动自由很大。", "error_description": "错误：“很”应放在形容词“大”之前，应说〈行动自由很大〉，不能说〈大很〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
