INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96857, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在一行字和另一行字的中间。", "primary_collocate": null, "pronunciation": "háng jiān", "ipa": "xaŋ˧˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "两行字的行间有一个小图。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在行间加了一个词。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这页纸的行间很空。", "target_word": "行间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把新句子写在行间。", "target_word": "行间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行间太挤，字都连在一起了。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在书的行间画了小花。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，请不要在行间乱写。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行间只够写一个字。", "target_word": "行间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用红笔在行间做了记号。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行间的小字是老师的批语。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "行间距", "label": "复合"}, {"form": "字里行间", "label": "成语"}, {"form": "行間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一行字和另一行字的中间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad778c81-0308-42c1-ae9b-f236d49633da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行间", "is_correct": true, "explanation": "正确：行间，háng jiān，指一行字和另一行字的中间。"}, {"text": "航天", "is_correct": false, "explanation": "háng 相同，但 tiān 与 jiān 声母不同（t/j），意思是航天。"}, {"text": "房间", "is_correct": false, "explanation": "fáng 与 háng 声母不同（f/h），jiān 相同，意思是房间。"}, {"text": "行家", "is_correct": false, "explanation": "jiā 与 jiān 的韵尾不同（有无 n），意思是内行的人。"}, {"text": "阳间", "is_correct": false, "explanation": "yáng 与 háng 声母不同（y/h），意思是人间。"}], "explanations": {"行间": "正确：行间，háng jiān，指一行字和另一行字的中间。", "航天": "háng 相同，但 tiān 与 jiān 声母不同（t/j），意思是航天。", "房间": "fáng 与 háng 声母不同（f/h），jiān 相同，意思是房间。", "行家": "jiā 与 jiān 的韵尾不同（有无 n），意思是内行的人。", "阳间": "yáng 与 háng 声母不同（y/h），意思是人间。"}, "sentence_index": null, "correct_answer": "行间"}, "level_3": {"options": [{"text": "行间", "is_correct": true, "explanation": "正确：行间指两行字的中间，小图正位于此处。"}, {"text": "封面", "is_correct": false, "explanation": "语义：封面在书的外部，不在两行字之间。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音是听到的东西，不能“有一个小图”。"}, {"text": "段落", "is_correct": false, "explanation": "搭配：段落由多句组成，不说“两行字的段落”。"}], "explanations": {"行间": "正确：行间指两行字的中间，小图正位于此处。", "封面": "语义：封面在书的外部，不在两行字之间。", "声音": "语义：声音是听到的东西，不能“有一个小图”。", "段落": "搭配：段落由多句组成，不说“两行字的段落”。"}, "sentence_index": 0, "correct_answer": "行间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家和学校的行间有一个公园。", "explanation": "这里应该用〈中间〉。行间只指字行之间的空白，两个地方之间要用〈中间〉。"}, {"text": "这两座城市之间的行间很长，坐火车要一天。", "explanation": "这里应该用〈距离〉。行间只指字行之间的空白，城市之间的远近要用〈距离〉。"}, {"text": "这两棵树的行间站着一个人。", "explanation": "这里应该用〈中间〉。行间只用于文字的行与行之间，不能指树和树之间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96857, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行间", "is_correct": true, "explanation": "正确：行间是字行之间的空白，老师不让在这里乱写，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法乱写，“请不要在空气乱写”句意荒谬。"}, {"text": "微风", "is_correct": false, "explanation": "搭配：“乱写”不能以“微风”为对象，不成搭配。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：清晨是时间，不能作为乱写的地点。"}], "explanations": {"行间": "正确：行间是字行之间的空白，老师不让在这里乱写，句意通顺。", "空气": "语义：空气无法乱写，“请不要在空气乱写”句意荒谬。", "微风": "搭配：“乱写”不能以“微风”为对象，不成搭配。", "清晨": "语义：清晨是时间，不能作为乱写的地点。"}, "sentence_index": 6, "correct_answer": "行间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个字和那个字的行间只有一毫米。", "explanation": "这里应该用〈字间〉。行间指行与行之间的空白，字与字之间的空隙要用〈字间〉。"}, {"text": "这把椅子的行间很窄。", "explanation": "这里应该用〈空隙〉。行间只用于字行之间，椅子各部分之间的空隙要用〈空隙〉。"}, {"text": "上课和下课的行间，我们去喝水。", "explanation": "这里应该用〈间隙〉。行间指字行之间的空白，不能指时间上的空当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在作业的一只行间写了评语。", "corrected_sentence": "老师在作业的行间写了评语。", "error_description": "错误在于“行间”前用了量词“只”。“只”用于动物，行间是空白处，应去掉“一只”，改为“老师在作业的行间写了评语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师的批语写行间。", "corrected_sentence": "老师的批语写在行间。", "error_description": "漏掉了介词“在”。“写”后表示处所的“行间”要由“在”引出，应为“老师的批语写在行间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
