INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文字行与行之间。", "primary_collocate": null, "pronunciation": "háng jiān", "ipa": "xaŋ˧˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "请在行间写上你的名字。", "target_word": "行间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师在行间写了很多小字。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章的行间太窄了。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "行间的空白太小，看起来很累。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在行间画了一条线。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把注释写在行间。", "target_word": "行间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的行间有一些铅笔字。", "target_word": "行间", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "行间留得宽一点，字会更清楚。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的笔记行间全是红色的字。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打印时可以改行间的大小。", "target_word": "行间", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "行间距", "label": "复合"}, {"form": "字里行间", "label": "成语"}, {"form": "行間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "文字行与行之间的空处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad778c81-0308-42c1-ae9b-f236d49633da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行间", "is_correct": true, "explanation": "正确：行间，háng jiān，指字行之间的空白。"}, {"text": "航天", "is_correct": false, "explanation": "háng 相同，但 tiān 与 jiān 声母不同（t/j），意思是航天。"}, {"text": "房间", "is_correct": false, "explanation": "fáng 与 háng 声母不同（f/h），jiān 相同，意思是房间。"}, {"text": "行家", "is_correct": false, "explanation": "jiā 与 jiān 的韵尾不同（有无 n），意思是内行的人。"}, {"text": "阳间", "is_correct": false, "explanation": "yáng 与 háng 声母不同（y/h），意思是人间。"}], "explanations": {"行间": "正确：行间，háng jiān，指字行之间的空白。", "航天": "háng 相同，但 tiān 与 jiān 声母不同（t/j），意思是航天。", "房间": "fáng 与 háng 声母不同（f/h），jiān 相同，意思是房间。", "行家": "jiā 与 jiān 的韵尾不同（有无 n），意思是内行的人。", "阳间": "yáng 与 háng 声母不同（y/h），意思是人间。"}, "sentence_index": null, "correct_answer": "行间"}, "level_3": {"options": [{"text": "行间", "is_correct": true, "explanation": "正确：行间是字行之间的空白，适合在这里写名字。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法书写，“在空气写上你的名字”句意不通。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚是时间，不是可以书写的地方。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“写上”不以“阳光”为载体，“在阳光写字”不成搭配。"}], "explanations": {"行间": "正确：行间是字行之间的空白，适合在这里写名字。", "空气": "语义：空气无法书写，“在空气写上你的名字”句意不通。", "夜晚": "语义：夜晚是时间，不是可以书写的地方。", "阳光": "搭配：“写上”不以“阳光”为载体，“在阳光写字”不成搭配。"}, "sentence_index": 0, "correct_answer": "行间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公园在银行和学校的行间。", "explanation": "这里应该用〈中间〉。行间只指字行之间的空白，地点之间要用〈中间〉。"}, {"text": "两排座位的行间站满了人。", "explanation": "这里应该用〈过道〉。行间只用于文字的行与行之间，座位之间的通道要用〈过道〉。"}, {"text": "两次会议之间的行间很短。", "explanation": "这里应该用〈间隔〉。行间只指字行之间的空白，时间上的间隔要用〈间隔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行间", "is_correct": true, "explanation": "正确：书中行与行之间的空白处有铅笔字，符合句意。"}, {"text": "窗外", "is_correct": false, "explanation": "语义：窗外不在书上，与“书的”不相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是书的组成部分，句意荒谬。"}, {"text": "桌面", "is_correct": false, "explanation": "搭配：“书的桌面”不成立，桌面属于桌子。"}], "explanations": {"行间": "正确：书中行与行之间的空白处有铅笔字，符合句意。", "窗外": "语义：窗外不在书上，与“书的”不相符。", "天气": "语义：天气不是书的组成部分，句意荒谬。", "桌面": "搭配：“书的桌面”不成立，桌面属于桌子。"}, "sentence_index": 6, "correct_answer": "行间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个字的行间只有一毫米。", "explanation": "这里应该用〈字间〉。行间指行与行之间的空白，字与字之间的空隙要用〈字间〉。"}, {"text": "墙和柜子之间的行间很窄。", "explanation": "这里应该用〈空隙〉。行间只用于字行之间，墙与柜子之间的空隙要用〈空隙〉。"}, {"text": "两节课的行间可以休息十分钟。", "explanation": "这里应该用〈课间〉。行间指字行之间的空白，课与课之间的时间要用〈课间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在卷子的一只行间做了批改。", "corrected_sentence": "老师在卷子的行间做了批改。", "error_description": "错误在于“行间”前用了量词“只”。“只”用于动物，而行间是空白处，不能说“一只行间”。应去掉量词，改为“老师在卷子的行间做了批改”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈菜单的行间写了备注。", "corrected_sentence": "妈妈在菜单的行间写了备注。", "error_description": "漏掉了介词“在”。“菜单的行间”是处所，“写”后要用“在”引出地点，应为“妈妈在菜单的行间写了备注”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
