INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96861, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一边说话，一边笑。", "primary_collocate": null, "pronunciation": "shuō xiào", "ipa": "ʂwɔ˥ ɕjɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "她一边做饭，一边和妈妈说笑。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们说笑着走进了教室。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和朋友说笑着往家走。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐们在厨房里一边干活一边说笑。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家说笑着，把一天的累都忘了。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们说笑着吃完了晚饭。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一路上和同学说笑，不觉得远。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们说笑着从我身边走过。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友见面，说笑个不停。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们说笑着跑出了学校。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说笑着", "label": "体标"}, {"form": "说笑了", "label": "体标"}, {"form": "说笑过", "label": "体标"}], "register": "口语", "sense_fingerprint": "说话和笑同时进行，常伴随其他动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca46de64-fa79-4631-af35-c977a98316fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96861, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "语义：一边做饭时无法同时散步，两个动作互相冲突。"}, {"text": "说笑", "is_correct": true, "explanation": "说笑：一边说话、一边笑，与“一边做饭，一边和妈妈”的句式相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：做饭与睡觉不能同时进行，句中的两个动作互相矛盾。"}, {"text": "骂", "is_correct": false, "explanation": "配价：“骂”需要说明骂的对象，“和妈妈骂”缺少宾语，句子不完整。"}], "explanations": {"散步": "语义：一边做饭时无法同时散步，两个动作互相冲突。", "说笑": "说笑：一边说话、一边笑，与“一边做饭，一边和妈妈”的句式相符。", "睡觉": "语义：做饭与睡觉不能同时进行，句中的两个动作互相矛盾。", "骂": "配价：“骂”需要说明骂的对象，“和妈妈骂”缺少宾语，句子不完整。"}, "sentence_index": 0, "correct_answer": "说笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家公司为价格说笑不休。", "explanation": "这里应该用〈争论〉。说笑是轻松的，不能用于价格这类利益上的严肃争执。"}, {"text": "他一直在说笑，满脸都是愁容。", "explanation": "这里应该用〈发愁〉。说笑是热闹地说话和笑闹，与满脸愁容相矛盾，不能用来描写发愁。"}, {"text": "他一边说笑，一边安静地读书。", "explanation": "这里应该用〈沉思〉。说笑是热闹地说话和笑，与安静地读书相矛盾，不能与“安静”并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出发", "is_correct": false, "explanation": "搭配：“出发”是瞬时动作，不能与“一路上”这种持续的时段搭配。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”的悲伤情绪与“不觉得远”的轻松愉快相矛盾。"}, {"text": "拿", "is_correct": false, "explanation": "配价：“拿”需要宾语，“和同学拿”缺少所拿之物。"}, {"text": "说笑", "is_correct": true, "explanation": "说笑：一边说笑，一边赶路，与“不觉得远”的语境相符。"}], "explanations": {"出发": "搭配：“出发”是瞬时动作，不能与“一路上”这种持续的时段搭配。", "哭泣": "语义：“哭泣”的悲伤情绪与“不觉得远”的轻松愉快相矛盾。", "拿": "配价：“拿”需要宾语，“和同学拿”缺少所拿之物。", "说笑": "说笑：一边说笑，一边赶路，与“不觉得远”的语境相符。"}, "sentence_index": 6, "correct_answer": "说笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一想到父亲的去世，就忍不住说笑。", "explanation": "这里应该用〈哭泣〉。说笑是轻松愉快的，与“父亲的去世”的悲伤情绪不符。"}, {"text": "两个孩子为了一颗糖哭得直抽噎，还在说笑。", "explanation": "这里应该用〈哭闹〉。说笑是轻松愉快的，与哭得直抽噎的情绪相反，不能这样用。"}, {"text": "她一个人坐在窗前，一边说笑，一边叹息。", "explanation": "这里应该用〈流泪〉。说笑是热闹地说话和笑，与一边叹息的低落情绪相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
