INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家在饭厅里说笑着一会儿。", "corrected_sentence": "大家在饭厅里说笑了一会儿。", "error_description": "错误：“说笑着一会儿”。“着”表示持续的状态，与表示完整时段的“一会儿”搭配不自然；应改为“说笑了一会儿”，用“了”表示动作已完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
