INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说话并笑。", "primary_collocate": null, "pronunciation": "shuō xiào", "ipa": "ʂwɔ˥ ɕjɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他们坐在树下说笑。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在教室里说笑，很热闹。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听见隔壁有人说笑。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和朋友一路说笑着回家。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在门口说笑，没有听到电话响。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭后，一家人坐在一起说笑。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们说笑了一会儿，就去上课了。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们在公园里说笑，很开心。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里传来说笑的声音。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们见面后就说笑起来。", "target_word": "说笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说笑着", "label": "体标"}, {"form": "说笑了", "label": "体标"}, {"form": "说笑过", "label": "体标"}], "register": "口语", "sense_fingerprint": "人们聊天时说话并笑，气氛轻松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca46de64-fa79-4631-af35-c977a98316fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "语义：“散步”需要边走边动，与“坐在树下”的静止状态矛盾。"}, {"text": "奔跑", "is_correct": false, "explanation": "语义：“坐在树下”是静止的，与“奔跑”的动作冲突。"}, {"text": "说笑", "is_correct": true, "explanation": "说笑：说话并笑，符合“坐在树下”的轻松场景。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”需要水域，树下没有水，两者不能搭配。"}], "explanations": {"散步": "语义：“散步”需要边走边动，与“坐在树下”的静止状态矛盾。", "奔跑": "语义：“坐在树下”是静止的，与“奔跑”的动作冲突。", "说笑": "说笑：说话并笑，符合“坐在树下”的轻松场景。", "游泳": "搭配：“游泳”需要水域，树下没有水，两者不能搭配。"}, "sentence_index": 0, "correct_answer": "说笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题他说笑得很清楚。", "explanation": "这里应该用〈讲解〉。说笑指说话并笑，不能用来表示把题目讲清楚。"}, {"text": "他在会议上说笑，一言不发。", "explanation": "这里应该用〈沉默〉。说笑是热闹地说话和笑，与一言不发相矛盾，不能这样用。"}, {"text": "她一个人坐着，满脸愁容地说笑。", "explanation": "这里应该用〈发愁〉。说笑是热闹地说话、笑闹，与满脸愁容的状态矛盾，不能用来描写发愁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到达", "is_correct": false, "explanation": "搭配：“到达”是瞬时动作，不能与“了一会儿”这样的时段搭配。"}, {"text": "说笑", "is_correct": true, "explanation": "说笑：说话并笑，与“就去上课了”前的轻松相处相符。"}, {"text": "拿", "is_correct": false, "explanation": "配价：“拿”需要宾语，“他们拿了一会儿”缺少所拿之物。"}, {"text": "出发", "is_correct": false, "explanation": "搭配：“出发”是瞬时动作，不能与“一会儿”搭配，说“出发了一会儿”不自然。"}], "explanations": {"到达": "搭配：“到达”是瞬时动作，不能与“了一会儿”这样的时段搭配。", "说笑": "说笑：说话并笑，与“就去上课了”前的轻松相处相符。", "拿": "配价：“拿”需要宾语，“他们拿了一会儿”缺少所拿之物。", "出发": "搭配：“出发”是瞬时动作，不能与“一会儿”搭配，说“出发了一会儿”不自然。"}, "sentence_index": 6, "correct_answer": "说笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一想到父亲的去世，就忍不住说笑。", "explanation": "这里应该用〈哭泣〉。说笑是轻松愉快的，与“父亲的去世”的悲伤情绪完全不符。"}, {"text": "两个孩子为了一颗糖哭个不停，还在说笑。", "explanation": "这里应该用〈哭闹〉。说笑是轻松愉快的，与哭闹的情绪相反，不能用来描写哭闹。"}, {"text": "她一个人坐在窗前，一边说笑，一边叹气。", "explanation": "这里应该用〈流泪〉。说笑是热闹地说话和笑，与一边叹气的低落情绪相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在树下很说笑。", "corrected_sentence": "他们在树下说笑。", "error_description": "错误：“很说笑”。“说笑”是动词，前面不能直接加程度副词“很”，应说“在树下说笑”，“很说笑”不合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家在教室里说笑着一阵。", "corrected_sentence": "大家在教室里说笑了一阵。", "error_description": "错误：“说笑着一阵”。“着”表示持续的状态，与表示完整时段的“一阵”搭配不自然；应改为“说笑了一阵”，用“了”表示动作已完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
