INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96863, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古人记日子和年份用的十个字。", "primary_collocate": null, "pronunciation": "tiān gān", "ipa": "tʰiɛn˥ kan˥", "syllable_count": 2, "sentences": [{"text": "古人用天干和地支记年。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天干一共有十个字。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "甲是天干的第一个字。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人为什么用天干记日子？", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天干里的最后一个字是癸。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶会背天干。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天教我们背天干。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天干和地支合起来，可以记年份。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乙是天干里的第二个字。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲了古人记日子的天干。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天干地支", "label": "复合"}], "register": "中性", "sense_fingerprint": "古人记日子年份的十个字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f797344-34e1-4b24-8621-ea8ced756a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96863, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天干", "is_correct": true, "explanation": "正确：“天干”是古人记年用的十个符号，与“地支”并列使用。"}, {"text": "手指", "is_correct": false, "explanation": "语义：“手指”不是记年的符号系统，与“地支”并列语义不通。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“用乐器记年”不成立，记年要用符号体系，乐器无法与“地支”并列。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是记年的符号，与“地支”并列语义不通。"}], "explanations": {"天干": "正确：“天干”是古人记年用的十个符号，与“地支”并列使用。", "手指": "语义：“手指”不是记年的符号系统，与“地支”并列语义不通。", "乐器": "搭配：“用乐器记年”不成立，记年要用符号体系，乐器无法与“地支”并列。", "水果": "语义：水果不是记年的符号，与“地支”并列语义不通。"}, "sentence_index": 0, "correct_answer": "天干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的天干是双子座，很喜欢交朋友。", "explanation": "这里应该用〈星座〉。天干是历法符号，不能用来说人的星座。"}, {"text": "这个学生一天到晚都在做天干，累得不行。", "explanation": "这里应该用〈干活〉。天干指历法符号或天气干燥，不指劳动。"}, {"text": "天太热了，我想喝一杯天干。", "explanation": "这里应该用〈饮料〉。天干是古人记日子和年份的符号，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天干", "is_correct": true, "explanation": "正确：“背天干”指背诵记年用的十个符号，符合课堂学习的语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“背天空”不成立，天空不能被背诵，与课堂学习的内容不符。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：“背”后接“汤”不成立，汤不能被背诵。"}, {"text": "海鲜", "is_correct": false, "explanation": "语义：海鲜是食物，不能被背诵，与课堂学习内容无关。"}], "explanations": {"天干": "正确：“背天干”指背诵记年用的十个符号，符合课堂学习的语境。", "天空": "语义：“背天空”不成立，天空不能被背诵，与课堂学习的内容不符。", "汤": "搭配：“背”后接“汤”不成立，汤不能被背诵。", "海鲜": "语义：海鲜是食物，不能被背诵，与课堂学习内容无关。"}, "sentence_index": 6, "correct_answer": "天干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书讲了古人养的天干。", "explanation": "这里“天干”指记日子的符号，不是可以饲养的东西，与“养”搭配不成立。"}, {"text": "这本书讲了古人吃天干的习俗。", "explanation": "这里应该用〈饭菜〉。天干是历法符号，不能用来“吃”。"}, {"text": "这本书讲了古人穿天干的习俗。", "explanation": "这里应该用〈衣服〉。天干是历法符号，不能用来“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这十只天干，古人用来记日子。", "corrected_sentence": "这十个天干，古人用来记日子。", "error_description": "错误：“只”多用于动物或成对的东西，天干是一个个符号，应说〈十个〉。正确：这十个天干，古人用来记日子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生要先背会天干们，再学地支。", "corrected_sentence": "学生要先背会天干，再学地支。", "error_description": "错误：“们”只用于指人，不能加在“天干”后面。正确：先背会天干，再学地支。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
