INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中国古代历法中的十个符号：甲乙丙丁戊己庚辛壬癸。", "primary_collocate": null, "pronunciation": "tiān gān", "ipa": "tʰiɛn˥ kan˥", "syllable_count": 2, "sentences": [{"text": "中国古代历法里有天干和地支。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丙是十个天干中的第三个。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表上写着天干，没有写地支。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他能把十个天干从头背到尾。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天干排在地支的前面。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里讲了天干的顺序。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历法课上，老师写了十个天干。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戊和己都是天干里的符号。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看日历时，他认出了天干中的庚。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天干有甲乙丙丁戊己庚辛壬癸十个符号。", "target_word": "天干", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "天干地支", "label": "复合"}], "register": "中性", "sense_fingerprint": "古代历法的十个符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: 5 words above tier T3 (max 3): 丙 (Zipf 3.36), 戊 (Zipf 2.74), 庚 (Zipf 3.23), 壬 (Zipf 3.27), 癸 (Zipf 3.25)']::text[], '1f797344-34e1-4b24-8621-ea8ced756a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天干", "is_correct": true, "explanation": "正确：“天干”是历法中的十个符号，与“地支”并列。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是音乐记号，不属于历法体系，与“地支”不能并列。"}, {"text": "红酒", "is_correct": false, "explanation": "语义：红酒与历法无关，句子语义不通。"}, {"text": "方言", "is_correct": false, "explanation": "搭配：“历法里有方言”不成立，历法的组成部分不包括方言。"}], "explanations": {"天干": "正确：“天干”是历法中的十个符号，与“地支”并列。", "乐谱": "语义：乐谱是音乐记号，不属于历法体系，与“地支”不能并列。", "红酒": "语义：红酒与历法无关，句子语义不通。", "方言": "搭配：“历法里有方言”不成立，历法的组成部分不包括方言。"}, "sentence_index": 0, "correct_answer": "天干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家养了天干，每天喂食。", "explanation": "这里“天干”是历法符号，不是动物，不能饲养，应该说〈猫〉或〈狗〉。"}, {"text": "他能把乘法天干从头背到尾。", "explanation": "这里应该用〈公式〉。天干是历法符号，不能说成“乘法天干”。"}, {"text": "他的天干非常好，老是考第一。", "explanation": "这里应该用〈成绩〉。天干指历法符号或天气干燥，不指学习表现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天干", "is_correct": true, "explanation": "正确：“十个天干”指甲乙丙丁等十个历法符号，符合课堂语境。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：“十个鸡蛋”与历法课无关，句子语义不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“写”不能与“房间”搭配，写的是文字或符号。"}, {"text": "脚丫", "is_correct": false, "explanation": "语义：脚丫不能被写在黑板上作为课堂内容，语境不符。"}], "explanations": {"天干": "正确：“十个天干”指甲乙丙丁等十个历法符号，符合课堂语境。", "鸡蛋": "语义：“十个鸡蛋”与历法课无关，句子语义不通。", "房间": "搭配：“写”不能与“房间”搭配，写的是文字或符号。", "脚丫": "语义：脚丫不能被写在黑板上作为课堂内容，语境不符。"}, "sentence_index": 6, "correct_answer": "天干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的天干是白羊座，性格很活泼。", "explanation": "这里应该用〈星座〉。天干是历法符号，不能用来说人的星座。"}, {"text": "他每天都认真地做天干。", "explanation": "这里应该用〈工作〉。天干是历法符号，不能当作劳动来“做”。"}, {"text": "老师给我们讲了一个天干。", "explanation": "这里应该用〈故事〉。天干是十个历法符号，不能用来“讲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张表上写着十只天干，古人用来记年。", "corrected_sentence": "这张表上写着十个天干，古人用来记年。", "error_description": "错误：“只”多用于动物或成对的东西，天干是一个个符号，应说〈十个〉。正确：这张表上写着十个天干，古人用来记年。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "历法课上，老师教了我们十本天干。", "corrected_sentence": "历法课上，老师教了我们十个天干。", "error_description": "量词错误：“本”用于书，天干是一个个符号，应说〈十个〉。正确：老师教了我们十个天干。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
