INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96865, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老师带着我们学习的教室。", "primary_collocate": null, "pronunciation": "kè táng", "ipa": "kʰɤ˥˩ tʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我们在课堂上学英语。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课堂里的窗户很大。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在课堂上给我们讲故事。", "target_word": "课堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课堂里有三十个学生。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他迟到了，悄悄走进课堂。", "target_word": "课堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的课堂里有很多书，也很亮。", "target_word": "课堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课堂里的黑板是新的。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课后，大家都离开了课堂。", "target_word": "课堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带着我们走出课堂，去公园学习。", "target_word": "课堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课堂里坐满了学生。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "課堂", "label": "繁体"}, {"form": "课堂教学", "label": "复合"}], "register": "中性", "sense_fingerprint": "老师带学生学习的教室这个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f797344-34e1-4b24-8621-ea8ced756a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96865, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "课堂", "is_correct": true, "explanation": "「课堂」指老师带学生学习的教室，「在……上学英语」搭配正确，句意通顺。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是学英语的场所，句意不通。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房是给病人治疗休养的地方，与学英语无关。"}, {"text": "讲坛", "is_correct": false, "explanation": "语域：「讲坛」偏书面，指讲演台，口语里不说「在讲坛上学英语」。"}], "explanations": {"课堂": "「课堂」指老师带学生学习的教室，「在……上学英语」搭配正确，句意通顺。", "厨房": "语义：厨房是做饭的地方，不是学英语的场所，句意不通。", "病房": "语义：病房是给病人治疗休养的地方，与学英语无关。", "讲坛": "语域：「讲坛」偏书面，指讲演台，口语里不说「在讲坛上学英语」。"}, "sentence_index": 0, "correct_answer": "课堂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新来的课堂很认真，每天都早到。", "explanation": "这里应该用〈老师〉。「课堂」指教室，不指人，不能说「新来的课堂」。"}, {"text": "学校新建了一只课堂。", "explanation": "量词用错：课堂是房间，应用量词〈间〉，不用〈只〉。"}, {"text": "他一口气吃完了课堂。", "explanation": "「课堂」是地点，不能吃，这种用法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课堂", "is_correct": true, "explanation": "「课堂」指教室，「课堂里的黑板」指教室里的黑板，符合句意。"}, {"text": "泳池", "is_correct": false, "explanation": "语义：泳池是游泳的地方，不会摆放教学用的黑板，句意不通。"}, {"text": "浴室", "is_correct": false, "explanation": "语义：浴室是洗澡的地方，不会有教学用的黑板，句意不通。"}, {"text": "讲台", "is_correct": false, "explanation": "搭配：方位词「里」不与「讲台」搭配，应说「讲台上」。"}], "explanations": {"课堂": "「课堂」指教室，「课堂里的黑板」指教室里的黑板，符合句意。", "泳池": "语义：泳池是游泳的地方，不会摆放教学用的黑板，句意不通。", "浴室": "语义：浴室是洗澡的地方，不会有教学用的黑板，句意不通。", "讲台": "搭配：方位词「里」不与「讲台」搭配，应说「讲台上」。"}, "sentence_index": 6, "correct_answer": "课堂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从课堂毕业了。", "explanation": "这里应该用〈学校〉。毕业的对象是学校或学业，「课堂」只指教室，不能用来说毕业。"}, {"text": "我们把课堂放进了书包。", "explanation": "「课堂」是地点，不是可以装进书包的物品，这种用法不成立。"}, {"text": "这节课堂一共有四十五分钟。", "explanation": "这里应该用〈这节课〉。「课堂」指上课的地方，不能用「节」计量，也不表示时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在课堂下教我们唱歌。", "corrected_sentence": "老师在课堂上教我们唱歌。", "error_description": "方位词错误：表示在上课的地方要说「课堂上」，不说「课堂下」。正确：老师在课堂上教我们唱歌。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在课堂的里练习写字。", "corrected_sentence": "我们在课堂里练习写字。", "error_description": "助词错误：「课堂」和方位词「里」之间多加了「的」，「课堂里」是处所短语，中间不能加「的」。正确形式：「我们在课堂里练习写字。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96866, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "synonym", "options": [{"text": "课上", "is_correct": true, "explanation": "正确：「课上」指上课的时候，与「课堂上」意思相同。"}, {"text": "课后", "is_correct": false, "explanation": "「课后」指下课以后，不是上课时的情景。"}, {"text": "课间", "is_correct": false, "explanation": "「课间」指两节课之间的休息时间，不是上课时。"}, {"text": "课外", "is_correct": false, "explanation": "「课外」指上课以外的时间或活动，与课堂相对。"}], "correct_answer": "课上", "explanations": {"课上": "正确：「课上」指上课的时候，与「课堂上」意思相同。", "课后": "「课后」指下课以后，不是上课时的情景。", "课间": "「课间」指两节课之间的休息时间，不是上课时。", "课外": "「课外」指上课以外的时间或活动，与课堂相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96866, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "synonym", "options": [{"text": "课上", "is_correct": true, "explanation": "正确：「课上」指上课的时候，与「课堂上」意思相同。"}, {"text": "放学后", "is_correct": false, "explanation": "「放学后」指学校下课回家以后，不是上课时。"}, {"text": "假期", "is_correct": false, "explanation": "「假期」是不上课的日子，与课堂无关。"}, {"text": "课余", "is_correct": false, "explanation": "「课余」指上课以外的空闲时间，与课堂相对。"}], "correct_answer": "课上", "explanations": {"课上": "正确：「课上」指上课的时候，与「课堂上」意思相同。", "放学后": "「放学后」指学校下课回家以后，不是上课时。", "假期": "「假期」是不上课的日子，与课堂无关。", "课余": "「课余」指上课以外的空闲时间，与课堂相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "上课时的情景和气氛，指课上发生的事。", "primary_collocate": null, "pronunciation": "kè táng", "ipa": "kʰɤ˥˩ tʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "课堂上，同学们都在认真听讲。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在课堂上睡着了。", "target_word": "课堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的课堂很有意思。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课堂上不能玩手机。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在课堂上举手回答问题。", "target_word": "课堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课堂气氛很好，大家都笑了。", "target_word": "课堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课堂上他问了老师一个问题。", "target_word": "课堂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这种轻松的课堂。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课堂上要认真做笔记。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在课堂上，老师请我读课文。", "target_word": "课堂", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "課堂", "label": "繁体"}, {"form": "课堂教学", "label": "复合"}], "register": "中性", "sense_fingerprint": "上课时的情景和气氛，即课上发生的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f797344-34e1-4b24-8621-ea8ced756a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "课堂", "is_correct": true, "explanation": "「课堂上」指上课的时候，「课堂上同学们认真听讲」描述上课时的情景，句意通顺。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：处所名词「教室」后接「里」，说「教室里」，不说「教室上」。"}, {"text": "球场", "is_correct": false, "explanation": "语义：球场是比赛的场地，不是听讲的场合，与「认真听讲」冲突。"}, {"text": "饭桌", "is_correct": false, "explanation": "语义：饭桌是吃饭的地方，与「听讲」没有关系，句意不通。"}], "explanations": {"课堂": "「课堂上」指上课的时候，「课堂上同学们认真听讲」描述上课时的情景，句意通顺。", "教室": "搭配：处所名词「教室」后接「里」，说「教室里」，不说「教室上」。", "球场": "语义：球场是比赛的场地，不是听讲的场合，与「认真听讲」冲突。", "饭桌": "语义：饭桌是吃饭的地方，与「听讲」没有关系，句意不通。"}, "sentence_index": 0, "correct_answer": "课堂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们班最好的课堂。", "explanation": "这里应该用〈同学〉或〈老师〉。「课堂」指教室或上课的情景，不指人，不能用来形容人。"}, {"text": "我们班有一只很有意思的课堂。", "explanation": "量词用错：课堂指上课的情景，不能用动物量词〈只〉计量。"}, {"text": "这门课堂有三个学分。", "explanation": "这里把「课堂」当作课程用，学分计算的是课程，不是上课时的情景。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课堂", "is_correct": true, "explanation": "「课堂上」指上课的时候，「他问了老师一个问题」发生在上课时，句意通顺。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是提问的场合，句意不通。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房是治疗病人的地方，与向老师提问的情景不合。"}, {"text": "学府", "is_correct": false, "explanation": "搭配：处所词「学府」要与「里」搭配，说「学府里」，不说「学府上」。"}], "explanations": {"课堂": "「课堂上」指上课的时候，「他问了老师一个问题」发生在上课时，句意通顺。", "厨房": "语义：厨房是做饭的地方，不是提问的场合，句意不通。", "病房": "语义：病房是治疗病人的地方，与向老师提问的情景不合。", "学府": "搭配：处所词「学府」要与「里」搭配，说「学府里」，不说「学府上」。"}, "sentence_index": 6, "correct_answer": "课堂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天要完成两份课堂。", "explanation": "这里应该用〈作业〉。「课堂」指教室或上课的情景，不指要完成的作业；课上布置的要说「课堂作业」。"}, {"text": "他已经从课堂毕业了。", "explanation": "这里应该用〈学校〉。毕业的对象是学校或学业，「课堂」指上课的情景，不能用来说毕业。"}, {"text": "我们每天课堂两个小时。", "explanation": "这里应该用〈上课〉。「课堂」是名词，不能当动词用，表示上课要说「上课」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王老师得课堂很热闹。", "corrected_sentence": "王老师的课堂很热闹。", "error_description": "助词错误：表示领属，名词「王老师」和「课堂」之间要用「的」，不能用「得」。正确：王老师的课堂很热闹。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在课堂的上讲了一个故事。", "corrected_sentence": "老师在课堂上讲了一个故事。", "error_description": "助词错误：「课堂上」是方位短语，「课堂」和「上」之间多加了「的」，「在课堂的上」不成立。正确形式：「老师在课堂上讲了一个故事。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96867, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
