INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96867, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力把别人的东西拿过来。", "primary_collocate": null, "pronunciation": "duó qǔ", "ipa": "twɔ˧˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "小偷想夺取她手里的包。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他夺取了对方手中的刀。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察夺取了坏人的枪。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民警从歹徒手中夺取了凶器。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强盗夺取了老人的钱。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸手夺取歹徒手里的刀。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士夺取了敌人手中的刀。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人夺取了她的书包就跑。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游击队夺取了敌人的粮食。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵夺取了敌人的武器。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夺取了", "label": "体标"}, {"form": "夺取过", "label": "体标"}], "register": "书面", "sense_fingerprint": "用力从别人手中把具体的东西抢过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca46de64-fa79-4631-af35-c977a98316fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缝补", "is_correct": false, "explanation": "语义：缝补需要修复的意图，与小偷想拿走别人东西的动机不符。"}, {"text": "保护", "is_correct": false, "explanation": "语义：小偷想要包，不会去保护别人的包，与句中的动机矛盾。"}, {"text": "夺取", "is_correct": true, "explanation": "夺取：用力从别人手中抢过来，与小偷想抢包的动机相符。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”的对象是人，不能带“包”作宾语。"}], "explanations": {"缝补": "语义：缝补需要修复的意图，与小偷想拿走别人东西的动机不符。", "保护": "语义：小偷想要包，不会去保护别人的包，与句中的动机矛盾。", "夺取": "夺取：用力从别人手中抢过来，与小偷想抢包的动机相符。", "结婚": "配价：“结婚”的对象是人，不能带“包”作宾语。"}, "sentence_index": 0, "correct_answer": "夺取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我夺取了这个想法。", "explanation": "这里应该用〈想出〉。夺取是用力拿走别人手里的东西，想法是靠思考想出来的，不能说夺取。"}, {"text": "我夺取了妈妈的爱。", "explanation": "这里应该用〈得到〉。夺取是用力从别人手中抢来具体东西，爱是别人主动给的，不能说夺取。"}, {"text": "他夺取了老师的批评。", "explanation": "这里应该用〈接受〉。夺取指用力拿走别人手里的东西，批评不是可以抢的东西，应说接受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能与“敌人手中的刀”搭配。"}, {"text": "夺取", "is_correct": true, "explanation": "夺取：用力从别人手中拿过来，与战士从敌人手中拿走刀的情节相符。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“刀”作宾语。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”是情绪动作，不能以“刀”为对象，句子无法成立。"}], "explanations": {"吃": "搭配：“吃”的对象是食物，不能与“敌人手中的刀”搭配。", "夺取": "夺取：用力从别人手中拿过来，与战士从敌人手中拿走刀的情节相符。", "散步": "配价：“散步”是不及物动词，不能带“刀”作宾语。", "哭泣": "语义：“哭泣”是情绪动作，不能以“刀”为对象，句子无法成立。"}, "sentence_index": 6, "correct_answer": "夺取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我向朋友夺取了一支笔。", "explanation": "这里应该用〈借〉。夺取是用力抢来，借是对方同意的，不能用夺取。"}, {"text": "他花钱夺取了一台电脑。", "explanation": "这里应该用〈买〉。夺取是用力拿走，买是付钱交易的，不能用夺取。"}, {"text": "我夺取了朋友的帮助。", "explanation": "这里应该用〈得到〉。夺取是用力拿走别人手里的东西，帮助是别人主动给的，不能说夺取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小偷想夺取了她身上的钱包。", "corrected_sentence": "小偷想夺取她身上的钱包。", "error_description": "错误：“夺取了”。“想”表示打算，动作尚未发生，不能用“了”；应去掉“了”，说“想夺取她身上的钱包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一把夺取的我的伞。", "corrected_sentence": "他一把夺取了我的伞。", "error_description": "错误：“夺取的我的伞”。动作已完成应用“了”，写成“的”则“夺取的”成了修饰语，句子不通；正确是“一把夺取了我的伞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
