INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96868, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96868, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力量取得；强行拿到。", "primary_collocate": null, "pronunciation": "duó qǔ", "ipa": "twɔ˧˥ tɕʰy˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们一定要夺取最后的胜利。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想夺取这座城市。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队努力夺取冠军。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队夺取了对方的阵地。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用武力夺取了政权。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员为夺取金牌努力训练。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家想夺取别国的土地。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家团结起来，夺取比赛的胜利。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们夺取了河对岸的桥。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红队在最后一局夺取了主动权。", "target_word": "夺取", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "夺取了", "label": "体标"}, {"form": "夺取过", "label": "体标"}], "register": "书面", "sense_fingerprint": "用力量或斗争取得胜利、政权、阵地等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca46de64-fa79-4631-af35-c977a98316fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "失去", "is_correct": false, "explanation": "语义：“一定要”表示决心，“失去最后的胜利”与这种决心相反。"}, {"text": "夺取", "is_correct": true, "explanation": "夺取：用力量或斗争取得，与“最后的胜利”的竞争语境相符。"}, {"text": "浪费", "is_correct": false, "explanation": "搭配：“浪费”的对象多是时间、资源等，不能与“胜利”搭配。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“一定要”表示决心，“放弃最后的胜利”与之矛盾。"}], "explanations": {"失去": "语义：“一定要”表示决心，“失去最后的胜利”与这种决心相反。", "夺取": "夺取：用力量或斗争取得，与“最后的胜利”的竞争语境相符。", "浪费": "搭配：“浪费”的对象多是时间、资源等，不能与“胜利”搭配。", "放弃": "语义：“一定要”表示决心，“放弃最后的胜利”与之矛盾。"}, "sentence_index": 0, "correct_answer": "夺取"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们夺取了这次考试。", "explanation": "这里应该用〈参加〉。夺取是用力量或斗争取得胜利、政权，考试不是可以抢来的东西，应说参加。"}, {"text": "他夺取了老师的表扬。", "explanation": "这里应该用〈接受〉。夺取是用力强行取得，表扬是老师给予的，应说接受，不能用夺取。"}, {"text": "秋天我们夺取了很多苹果。", "explanation": "这里应该用〈收获〉。夺取是用力强行拿到，苹果是劳动的成果，应说收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能与“土地”搭配。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”的对象是人，不能带“土地”作宾语。"}, {"text": "夺取", "is_correct": true, "explanation": "夺取：用武力等强行取得，与“想……别国的土地”的语境相符。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”是情绪动作，不能以土地为对象，句子无法成立。"}], "explanations": {"吃": "搭配：“吃”的对象是食物，不能与“土地”搭配。", "结婚": "配价：“结婚”的对象是人，不能带“土地”作宾语。", "夺取": "夺取：用武力等强行取得，与“想……别国的土地”的语境相符。", "哭泣": "语义：“哭泣”是情绪动作，不能以土地为对象，句子无法成立。"}, "sentence_index": 6, "correct_answer": "夺取"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于夺取了游泳技巧。", "explanation": "这里应该用〈掌握〉。夺取是用力强行取得，技巧要靠练习掌握，不能说夺取。"}, {"text": "我们夺取了一个愉快的周末。", "explanation": "这里应该用〈度过〉。夺取是用力量或斗争取得胜利、政权，周末是过出来的，不能说夺取。"}, {"text": "我终于夺取了这份作业。", "explanation": "这里应该用〈完成〉。夺取是用力强行取得，作业要靠自己做完，不能说夺取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一定要夺取了这场比赛的胜利。", "corrected_sentence": "我们一定要夺取这场比赛的胜利。", "error_description": "错误：“夺取了”。“一定要”表示未来的决心，动作尚未发生，不能用“了”；应去掉“了”，说“夺取这场比赛的胜利”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们明天会夺取了冠军。", "corrected_sentence": "他们明天会夺取冠军。", "error_description": "错误：“夺取了”。“明天会”表示将来，动作尚未发生，不能用“了”；应去掉“了”，说“夺取冠军”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2218c5b-090d-47ff-84e8-904abb466fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
