INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96870, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专门深入调查并报道社会问题的记者。", "primary_collocate": null, "pronunciation": "diào chá jì zhě", "ipa": "tjɑʊ˥˩ ʈʂʰɑ˧˥ tɕi˥˩ ʈʂɤ˨˩˦", "syllable_count": 4, "sentences": [{"text": "调查记者深入农村，了解孩子上学的问题。", "target_word": "调查记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位有名的调查记者。", "target_word": "调查记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报社有三位调查记者。", "target_word": "调查记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查记者经常报道社会问题。", "target_word": "调查记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对调查记者的工作很感兴趣。", "target_word": "调查记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位调查记者写过很多关于环境的报道。", "target_word": "调查记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查记者为了写好报道，花了很多时间。", "target_word": "调查记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学毕业后她成了调查记者。", "target_word": "调查记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查记者需要很大的勇气。", "target_word": "调查记者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个电视节目请来一位调查记者。", "target_word": "调查记者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调查记者们", "label": "复数"}, {"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "专门深入调查并报道社会问题的记者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8adc1b-9d40-4b43-9a93-25a8a9f56bae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调查记者", "is_correct": true, "explanation": "正确。“调查记者”深入基层调查社会问题，符合句意。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”的工作是做饭，不会深入农村去了解教育问题。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：“裁判”负责判定比赛，与深入农村调查无关。"}, {"text": "农田", "is_correct": false, "explanation": "搭配：“农田”是地点，不能作“深入”的施事主语。"}], "explanations": {"调查记者": "正确。“调查记者”深入基层调查社会问题，符合句意。", "厨师": "语义：“厨师”的工作是做饭，不会深入农村去了解教育问题。", "裁判": "语义：“裁判”负责判定比赛，与深入农村调查无关。", "农田": "搭配：“农田”是地点，不能作“深入”的施事主语。"}, "sentence_index": 0, "correct_answer": "调查记者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位调查记者每天开公交车接送乘客。", "explanation": "这里应该用〈司机〉。调查记者指报道社会问题的记者，开公交车接送乘客的是司机，不能用调查记者。"}, {"text": "这位调查记者每天给病人打针。", "explanation": "这里应该用〈护士〉。调查记者指报道社会问题的记者，给病人打针的是护士，不能用调查记者。"}, {"text": "这位调查记者每天挨家挨户统计人口。", "explanation": "这里应该用〈统计员〉。调查记者指深入调查并报道社会问题的记者，挨家挨户统计人口的是统计员，不能用调查记者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调查记者", "is_correct": true, "explanation": "正确。“调查记者”需要为了写好报道花很多时间，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物品，不会写报道，句子读不通。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：“小猫”不会写报道，句子读不通。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“工厂”是机构，不能作“为了写好报道”的施事。"}], "explanations": {"调查记者": "正确。“调查记者”需要为了写好报道花很多时间，符合句意。", "桌子": "语义：“桌子”是物品，不会写报道，句子读不通。", "小猫": "语义：“小猫”不会写报道，句子读不通。", "工厂": "搭配：“工厂”是机构，不能作“为了写好报道”的施事。"}, "sentence_index": 6, "correct_answer": "调查记者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位调查记者每天在剧组拍戏。", "explanation": "这里应该用〈演员〉。调查记者指报道社会问题的记者，在剧组拍戏的是演员，不能用调查记者。"}, {"text": "这位调查记者在法庭上为当事人辩护。", "explanation": "这里应该用〈律师〉。调查记者指报道社会问题的记者，在法庭上为当事人辩护的是律师，不能用调查记者。"}, {"text": "这位调查记者昨天给病人做了手术。", "explanation": "这里应该用〈医生〉。调查记者指报道社会问题的记者，给病人做手术的是医生，不能用调查记者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家杂志社有三位调查记者们。", "corrected_sentence": "这家杂志社有三位调查记者。", "error_description": "“们”误用：有数量词修饰时不能再加“们”，应说“三位调查记者”，不能说“三位调查记者们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毕业以后他成了一只调查记者。", "corrected_sentence": "毕业以后他成了一名调查记者。", "error_description": "量词错误：“调查记者”指人，量词应用“名”或“位”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
