INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指妇女（口语，带有时代色彩）。", "primary_collocate": null, "pronunciation": "nǚ rén jiā", "ipa": "ny˨˩˦ ɻən˧˥ tɕia˥", "syllable_count": 3, "sentences": [{"text": "奶奶说，以前女人家很少上学。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个年代的女人家，都要在家做饭。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的女人家一起洗衣服，一起聊天。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷小时候，女人家很少坐火车。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那时候女人家一个人出远门很不容易。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外婆是个女人家，却养大了五个孩子。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在老房子里，女人家和孩子住在后面。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，过去女人家结婚以后，就不再工作了。", "target_word": "女人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个女人家，却一个人开着车去了西藏。", "target_word": "女人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村口站着几个女人家，正在说笑。", "target_word": "女人家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "旧时口语中指妇女，带有年代感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e8e5b6b-41e6-4dbe-82c6-698d5104ef7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女人家", "is_correct": true, "explanation": "正确。“女人家”指旧时的妇女，与“以前”“很少上学”的语境相合。"}, {"text": "女大学生", "is_correct": false, "explanation": "语义：大学生本身就在上学，与“很少上学”的句意矛盾。"}, {"text": "女司机", "is_correct": false, "explanation": "语义：“女司机”是现代职业，与“以前”的时代背景不符，句子说不通。"}, {"text": "女博士", "is_correct": false, "explanation": "语义：博士已接受长期教育，与“很少上学”的句意矛盾。"}], "explanations": {"女人家": "正确。“女人家”指旧时的妇女，与“以前”“很少上学”的语境相合。", "女大学生": "语义：大学生本身就在上学，与“很少上学”的句意矛盾。", "女司机": "语义：“女司机”是现代职业，与“以前”的时代背景不符，句子说不通。", "女博士": "语义：博士已接受长期教育，与“很少上学”的句意矛盾。"}, "sentence_index": 0, "correct_answer": "女人家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村口的老槐树下，坐着一个女人家，才七八岁。", "explanation": "这里应该用〈小女孩〉。女人家指成年妇女，不用来称呼七八岁的孩子。"}, {"text": "我爸爸是个女人家，每天开车上班。", "explanation": "这里应该用〈男人〉。女人家只指女性，不能用来指男性。"}, {"text": "那位老先生是个女人家，很会下棋。", "explanation": "这里应该用〈男人〉。女人家只指女性，不能用来指男性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女人家", "is_correct": true, "explanation": "正确。“女人家”指旧时的妇女，与“在老房子里”“住在后面”的家庭语境相合。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是人，不能和孩子住在老房子里。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不能和孩子住在一起。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不是人，不能和孩子住在一起。"}], "explanations": {"女人家": "正确。“女人家”指旧时的妇女，与“在老房子里”“住在后面”的家庭语境相合。", "钢琴": "语义：钢琴不是人，不能和孩子住在老房子里。", "石头": "语义：石头不是人，不能和孩子住在一起。", "咖啡": "语义：咖啡不是人，不能和孩子住在一起。"}, "sentence_index": 6, "correct_answer": "女人家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个女人家，很高，常常帮大家搬东西。", "explanation": "这里应该用〈男人〉。女人家只指女性，不能用来指男性。"}, {"text": "幼儿园里有个女人家，才五岁，很爱笑。", "explanation": "这里应该用〈小朋友〉。女人家指成年妇女，不用来称呼五岁的孩子。"}, {"text": "那个小学生是个女人家，每天背着书包上学。", "explanation": "这里应该用〈小女孩〉。女人家指成年妇女，不用来称呼还在读小学的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里那只女人家每天都去河边洗衣服。", "corrected_sentence": "村里那些女人家每天都去河边洗衣服。", "error_description": "量词错误：“只”用于动物，不能修饰人。应改为“那些女人家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老房子里那块女人家每天早上都做饭。", "corrected_sentence": "老房子里那些女人家每天早上都做饭。", "error_description": "量词错误：“块”用于成块的东西，不能修饰人。“那块女人家”应改为“那些女人家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96873, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96873, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96873, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "样子变得不一样了。", "primary_collocate": null, "pronunciation": "biàn xíng", "ipa": "pjɛn ɕiŋ", "syllable_count": 2, "sentences": [{"text": "他笑得太用力，脸都变形了。", "target_word": "变形", "complexity_tier": "T3", "furigana": "tā xiào de tài yònglì, liǎn dōu biànxíng le.", "sentence_source": "generated"}, {"text": "照片里的脸看起来变形了。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍得太近，人的脸都变形了。", "target_word": "变形", "complexity_tier": "T3", "furigana": "zhè zhāng zhàopiàn pāi de tài jìn, rén de liǎn dōu biànxíng le.", "sentence_source": "generated"}, {"text": "这面镜子会让人的样子变形。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "透过这块厚玻璃看外面，景物都变形了。", "target_word": "变形", "complexity_tier": "T3", "furigana": "tòuguò zhè kuài hòu bōli kàn wàimiàn, jǐngwù dōu biànxíng le.", "sentence_source": "generated"}, {"text": "人群一挤，他的脸就变形了。", "target_word": "变形", "complexity_tier": "T3", "furigana": "rénqún yì jǐ, tā de liǎn jiù biànxíng le.", "sentence_source": "generated"}, {"text": "那张画里的人看起来有点变形。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕上的字都变形了。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片放大以后，他的脸好像变形了。", "target_word": "变形", "complexity_tier": "T3", "furigana": "zhàopiàn fàngdà yǐhòu, tā de liǎn hǎoxiàng biànxíng le.", "sentence_source": "generated"}, {"text": "孩子做鬼脸，脸都变形了。", "target_word": "变形", "complexity_tier": "T3", "furigana": "háizi zuò guǐliǎn, liǎn dōu biànxíng le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "变形了", "label": "体标"}, {"form": "变形过", "label": "体标"}, {"form": "变形虫", "label": "复合"}], "register": "中性", "sense_fingerprint": "外观样子发生变化，和原来不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2b2c253-1912-4008-90c3-ad21f0ccc4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96873, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌是发出声音，不会让脸走样，句子不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗脸是动作，“脸都洗了”与“笑得太用力”无关，句子不通。"}, {"text": "变形", "is_correct": true, "explanation": "正确：变形指脸因用力而走样，填入后与“脸都……了”的句意相符。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：跑步是一种运动，与“脸因用力而走样”无关。"}], "explanations": {"唱歌": "语义：唱歌是发出声音，不会让脸走样，句子不通。", "洗": "语义：洗脸是动作，“脸都洗了”与“笑得太用力”无关，句子不通。", "变形": "正确：变形指脸因用力而走样，填入后与“脸都……了”的句意相符。", "跑步": "语义：跑步是一种运动，与“脸因用力而走样”无关。"}, "sentence_index": 0, "correct_answer": "变形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我最近的生活习惯变形了很多。", "explanation": "这里应该用〈改变〉。变形指物体外形走样，生活习惯的变化要用改变。"}, {"text": "这个月的天气变形得很快。", "explanation": "这里应该用〈变化〉。变形只用于外形扭曲，天气的变化要用变化。"}, {"text": "他的性格一下子变形了。", "explanation": "这里应该用〈转变〉。变形指外形走样，性格的改变要用转变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：游泳是水中的活动，画中人不会因此“看起来有点游泳”。"}, {"text": "推动", "is_correct": false, "explanation": "配价：“推动”需要带宾语，“看起来有点推动”不成立。"}, {"text": "变形", "is_correct": true, "explanation": "正确：指画中人的样子走样，填入后符合句意。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，不能用来形容画中人的样子。"}], "explanations": {"游泳": "语义：游泳是水中的活动，画中人不会因此“看起来有点游泳”。", "推动": "配价：“推动”需要带宾语，“看起来有点推动”不成立。", "变形": "正确：指画中人的样子走样，填入后符合句意。", "下雨": "语义：下雨是天气现象，不能用来形容画中人的样子。"}, "sentence_index": 6, "correct_answer": "变形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的体重这一年变形了三公斤。", "explanation": "这里应该用〈增加〉。变形指外形走样，体重的增加要用增加。"}, {"text": "这棵树一年变形了两米。", "explanation": "这里应该用〈生长〉。变形不表示长高，树木长高要用生长。"}, {"text": "这个城市的人口变形得很快。", "explanation": "这里应该用〈增长〉。变形指外观样子的改变，人口的增减要用增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张照片把他的脸拍了变形了。", "corrected_sentence": "这张照片把他的脸拍变形了。", "error_description": "多出的“了”：结果补语“变形”前面不能插“了”，应说“拍变形了”，不能说“拍了变形了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看过这张照片，人的脸都变形了过。", "corrected_sentence": "我看过这张照片，人的脸都变形了。", "error_description": "体标错误：“变形了”后面不能再加“过”，“了”和“过”不能同时用在同一个动词后，应说“变形了”，多余的“过”要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96874, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96874, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形状改变。", "primary_collocate": null, "pronunciation": "biàn xíng", "ipa": "pjɛn ɕiŋ", "syllable_count": 2, "sentences": [{"text": "铁在高温下会变形。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盒子太软，放重东西就会变形。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料杯一热就变形。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木桌放在水里会变形。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球一压就变形了。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮子变形了，车走不了。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包放在袋子里变形了。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球压了很久，已经变形了。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属受热后会变形。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的眼镜框变形了，戴着不舒服。", "target_word": "变形", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变形了", "label": "体标"}, {"form": "变形过", "label": "体标"}, {"form": "变形虫", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体受力或受热后形状发生改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2b2c253-1912-4008-90c3-ad21f0ccc4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96874, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "说话", "is_correct": false, "explanation": "语义：铁不会说话，句子说不通。"}, {"text": "洗", "is_correct": false, "explanation": "配价：“洗”需要带宾语，“铁在高温下会洗”不成立。"}, {"text": "变形", "is_correct": true, "explanation": "正确：铁受热后形状改变，填入后与句意相符。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：铁不会微笑，与“高温下”的物理变化无关。"}], "explanations": {"说话": "语义：铁不会说话，句子说不通。", "洗": "配价：“洗”需要带宾语，“铁在高温下会洗”不成立。", "变形": "正确：铁受热后形状改变，填入后与句意相符。", "微笑": "语义：铁不会微笑，与“高温下”的物理变化无关。"}, "sentence_index": 0, "correct_answer": "变形"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年的房价一下子变形了。", "explanation": "这里应该用〈上涨〉。变形指形状改变，价格的上升要用上涨。"}, {"text": "牛奶放久了会变形。", "explanation": "这里应该用〈变质〉。食物坏掉要用变质，变形只指形状改变。"}, {"text": "他最近的作息变形了很多。", "explanation": "这里应该用〈转变〉。变形指形状改变，作息的改变要用转变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96874, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "笑", "is_correct": false, "explanation": "语义：面包不会笑，句子不通。"}, {"text": "推开", "is_correct": false, "explanation": "配价：“推开”需要带宾语，“面包放在袋子里推开了”不成立。"}, {"text": "变形", "is_correct": true, "explanation": "正确：面包被袋子挤压后形状改变，填入后与句意相符。"}, {"text": "运动", "is_correct": false, "explanation": "语义：面包不能做运动，与“放在袋子里”的情境无关。"}], "explanations": {"笑": "语义：面包不会笑，句子不通。", "推开": "配价：“推开”需要带宾语，“面包放在袋子里推开了”不成立。", "变形": "正确：面包被袋子挤压后形状改变，填入后与句意相符。", "运动": "语义：面包不能做运动，与“放在袋子里”的情境无关。"}, "sentence_index": 6, "correct_answer": "变形"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工资一下子变形了。", "explanation": "这里应该用〈增加〉。变形指物体形状改变，工资的增减要用增加或上涨。"}, {"text": "河水到了冬天就变形了。", "explanation": "这里应该用〈结冰〉。水变成冰是状态的变化，不是形状走样，要用结冰。"}, {"text": "他的心情一下子变形了。", "explanation": "这里应该用〈变化〉。变形指物体形状改变，心情的起伏要用变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把尺子压了变形了。", "corrected_sentence": "我把尺子压变形了。", "error_description": "多出的“了”：结果补语“变形”前面不能插“了”，应说“压变形了”，不能说“压了变形了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我试过这块铁板，一热就变形了过。", "corrected_sentence": "我试过这块铁板，一热就变形了。", "error_description": "体标错误：“变形了”后面不能再加“过”，“了”和“过”不能同时用在同一个动词后，应说“变形了”，多余的“过”要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
