INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96875, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "挂在高处，人掉下来的时候能接住他的网。", "primary_collocate": null, "pronunciation": "ān quán wǎng", "ipa": "an˥ tɕʰyɛn˧˥ uɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "工人身下挂着一张安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼房外面挂了一层安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从高处掉下来，安全网接住了他。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马戏团的表演者下面有安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在高处干活，必须挂好安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安全网挂在三楼外面，很结实。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子差点掉下去，幸好有安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张安全网是新买的。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把安全网挂在房子旁边。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看，那张安全网上有一只鞋。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张安全网", "label": "量词"}, {"form": "一层安全网", "label": "量词"}], "register": "中性", "sense_fingerprint": "挂在高处、用来接住坠落者的实物网", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e1032ad-a31c-4565-a75f-700a2b65743c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安全网", "is_correct": true, "explanation": "安全网：挂在高处、用来接住坠落者的网，与“工人身下挂着”的场景相合。"}, {"text": "渔网", "is_correct": false, "explanation": "语义：渔网用来捕鱼，挂在工人身下接不住人。"}, {"text": "蚊帐", "is_correct": false, "explanation": "搭配：蚊帐挂在床上防蚊，不会挂在工人身下，与“挂着”的场所不搭配。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：窗帘挂在窗户上遮光，不会挂在人的身下。"}], "explanations": {"安全网": "安全网：挂在高处、用来接住坠落者的网，与“工人身下挂着”的场景相合。", "渔网": "语义：渔网用来捕鱼，挂在工人身下接不住人。", "蚊帐": "搭配：蚊帐挂在床上防蚊，不会挂在工人身下，与“挂着”的场所不搭配。", "窗帘": "搭配：窗帘挂在窗户上遮光，不会挂在人的身下。"}, "sentence_index": 0, "correct_answer": "安全网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "司机开车时必须系好安全网。", "explanation": "这里应该用〈安全带〉。系的是安全带，安全网是挂在高处接人的网，不能系在身上。"}, {"text": "夏天他在窗户上装了一张安全网，蚊子就进不来了。", "explanation": "这里应该用〈纱窗〉。安全网是用来接住坠落之人的网，挡蚊子要用纱窗。"}, {"text": "渔民把安全网撒进河里捕鱼。", "explanation": "这里应该用〈渔网〉。安全网用来接住坠落的人，捕鱼要用渔网。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安全网", "is_correct": true, "explanation": "安全网：能接住掉下去的孩子，与“差点掉下去”“幸好有”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能接住掉下去的孩子，“幸好有桌子”语义不通。"}, {"text": "滑梯", "is_correct": false, "explanation": "搭配：滑梯是孩子滑下去玩的设施，不能接住掉下去的孩子，与“掉下去”后的“幸好有”不搭配。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包用来装东西，不能接住掉下去的孩子。"}], "explanations": {"安全网": "安全网：能接住掉下去的孩子，与“差点掉下去”“幸好有”相合。", "桌子": "语义：桌子不能接住掉下去的孩子，“幸好有桌子”语义不通。", "滑梯": "搭配：滑梯是孩子滑下去玩的设施，不能接住掉下去的孩子，与“掉下去”后的“幸好有”不搭配。", "书包": "语义：书包用来装东西，不能接住掉下去的孩子。"}, "sentence_index": 6, "correct_answer": "安全网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他怕冷，晚上把安全网盖在身上睡觉。", "explanation": "这里应该用〈被子〉。安全网是挂在高处接人的网，不能拿来盖身子保暖。"}, {"text": "她在客厅地上铺了一张安全网。", "explanation": "这里应该用〈地毯〉。安全网是挂在高处接人的网，不能铺在地上当地毯。"}, {"text": "天冷，他把安全网围在脖子上。", "explanation": "这里应该用〈围巾〉。安全网是接人的网，不能围在脖子上保暖，保暖要用围巾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "楼房外面挂了一把安全网。", "corrected_sentence": "楼房外面挂了一张安全网。", "error_description": "量词错误：“把”用于有柄的物件，安全网是面状物，应说“一张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口挂着一本安全网。", "corrected_sentence": "门口挂着一张安全网。", "error_description": "量词错误：“本”用于书册，安全网是面状物，应说“一张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
