INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比喻在遇到困难或风险时起保护、兜底作用的措施。", "primary_collocate": null, "pronunciation": "ān quán wǎng", "ipa": "an˥ tɕʰyɛn˧˥ uɑŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这份奖学金是他求学路上的安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保险是家庭生活的一张安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会保障是穷人的安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了存款，就像有了一张安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区里的互助小组，是独居老人的安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱是我们的安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给失业的人织了一张安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换工作以前，先给自己准备了安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有积蓄的家庭，经不起一场大病，缺少一张安全网。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗保险像一张安全网，让人放心。", "target_word": "安全网", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张安全网", "label": "量词"}, {"form": "一道安全网", "label": "量词"}], "register": "中性", "sense_fingerprint": "比喻保护人免受风险的保障措施", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e1032ad-a31c-4565-a75f-700a2b65743c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安全网", "is_correct": true, "explanation": "安全网：比喻保障措施，与“奖学金”的语境相合。"}, {"text": "广告牌", "is_correct": false, "explanation": "语义：广告牌是宣传用的，不能比喻保障措施。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是要付的钱，不能比喻保障措施。"}, {"text": "横幅", "is_correct": false, "explanation": "语义：横幅用于宣传，不能比喻保障措施。"}], "explanations": {"安全网": "安全网：比喻保障措施，与“奖学金”的语境相合。", "广告牌": "语义：广告牌是宣传用的，不能比喻保障措施。", "账单": "语义：账单是要付的钱，不能比喻保障措施。", "横幅": "语义：横幅用于宣传，不能比喻保障措施。"}, "sentence_index": 0, "correct_answer": "安全网"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他系上一张安全网，开始做饭。", "explanation": "这里应该用〈围裙〉。系上的是围裙；安全网比喻遇到困难时起保护作用的措施，不是系在身上的东西。"}, {"text": "他戴上一张安全网，走进了雪地。", "explanation": "这里应该用〈手套〉。戴的是手套；安全网比喻起兜底作用的保障措施，不能戴在手上。"}, {"text": "她用安全网装了满满一袋青菜回家。", "explanation": "这里应该用〈购物袋〉。安全网比喻遇到风险时起兜底作用的保障措施，不是装东西的袋子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安全网", "is_correct": true, "explanation": "安全网：保障措施，与“政府给失业的人”的语境相合，“织”的是网状的保障。"}, {"text": "饭票", "is_correct": false, "explanation": "搭配：“织”用于织物，不搭配饭票。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是纸上标示路线的，不能织给失业的人。"}, {"text": "凳子", "is_correct": false, "explanation": "语义：凳子是用来坐的家具，不能织给失业的人作保障。"}], "explanations": {"安全网": "安全网：保障措施，与“政府给失业的人”的语境相合，“织”的是网状的保障。", "饭票": "搭配：“织”用于织物，不搭配饭票。", "地图": "语义：地图是纸上标示路线的，不能织给失业的人。", "凳子": "语义：凳子是用来坐的家具，不能织给失业的人作保障。"}, "sentence_index": 6, "correct_answer": "安全网"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面安全网挡住了子弹。", "explanation": "这里应该用〈护盾〉。安全网比喻遇到风险时兜底的保障措施，不是挡子弹的东西。"}, {"text": "下雨的时候，他撑起了一张安全网。", "explanation": "这里应该用〈雨伞〉。撑起的是雨伞；安全网比喻生活中的保障措施，不能拿来挡雨。"}, {"text": "这条绳子是他的安全网，用来晾衣服。", "explanation": "这里应该用〈晾衣绳〉。安全网是保障措施或接人的网，不能拿来晾衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "存款是老人生活的一根安全网。", "corrected_sentence": "存款是老人生活的一张安全网。", "error_description": "量词错误：“根”用于条状物，安全网是面状的，应说“一张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他退休以前，先给自己戴了安全网。", "corrected_sentence": "他退休以前，先给自己备了安全网。", "error_description": "搭配错误：“安全网”不能戴，应说“备了安全网”。“戴”用于帽子、手套等可以穿戴的物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2ec46b-d715-4cbe-b7d4-c5a953083d1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96877, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吵闹", "is_correct": false, "explanation": "“吵闹”形容声音或环境嘈杂，与“走心”不构成反义关系。"}, {"text": "马虎", "is_correct": true, "explanation": "马虎：做事不认真、不用心，与“走心”（认真用心）意义相反，是这一义项的反义词。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外表好看，与“走心”的用心、感人之义无关。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”形容空间宽度小，与“走心”的意思没有关系。"}], "correct_answer": "马虎", "explanations": {"吵闹": "“吵闹”形容声音或环境嘈杂，与“走心”不构成反义关系。", "马虎": "马虎：做事不认真、不用心，与“走心”（认真用心）意义相反，是这一义项的反义词。", "漂亮": "“漂亮”形容外表好看，与“走心”的用心、感人之义无关。", "狭窄": "“狭窄”形容空间宽度小，与“走心”的意思没有关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96877, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高大", "is_correct": false, "explanation": "“高大”形容身材或体型，与“走心”不构成反义关系。"}, {"text": "草率", "is_correct": true, "explanation": "草率：做事不慎重、不细致，与“走心”（用心、认真）意义相反，是这一义项的反义词。"}, {"text": "嘈杂", "is_correct": false, "explanation": "“嘈杂”形容声音杂乱，与“走心”的用心、感人之义无关。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线强或颜色鲜亮，与“走心”没有反义关系。"}], "correct_answer": "草率", "explanations": {"高大": "“高大”形容身材或体型，与“走心”不构成反义关系。", "草率": "草率：做事不慎重、不细致，与“走心”（用心、认真）意义相反，是这一义项的反义词。", "嘈杂": "“嘈杂”形容声音杂乱，与“走心”的用心、感人之义无关。", "明亮": "“明亮”形容光线强或颜色鲜亮，与“走心”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96877, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很认真，用心做，很能让人觉得感动。", "primary_collocate": null, "pronunciation": "zǒu xīn", "ipa": "tsou˨˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这份生日礼物很走心。", "target_word": "走心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的信非常走心，我看哭了。", "target_word": "走心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个广告很走心，大家都喜欢。", "target_word": "走心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做的每一道菜都很走心。", "target_word": "走心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话不长，但是很走心。", "target_word": "走心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做事太不走心了。", "target_word": "走心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给我唱了一首走心的歌。", "target_word": "走心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的服务很走心，客人都愿意再来。", "target_word": "走心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的道歉一点也不走心。", "target_word": "走心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡片虽然简单，可是很走心。", "target_word": "走心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不走心", "label": "否定"}], "register": "口语", "sense_fingerprint": "认真用心，让人感动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3663726-c4db-4604-891f-260c0732ed66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96877, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”形容人的待人态度，不能用来形容礼物。"}, {"text": "走心", "is_correct": true, "explanation": "走心：形容礼物用心准备、能打动人，与“很”搭配，符合句意。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”多形容声音或环境，不说礼物吵闹。"}, {"text": "年轻", "is_correct": false, "explanation": "体貌：“年轻”形容人的年龄样子，礼物没有年龄。"}], "explanations": {"冷淡": "语义：“冷淡”形容人的待人态度，不能用来形容礼物。", "走心": "走心：形容礼物用心准备、能打动人，与“很”搭配，符合句意。", "吵闹": "搭配：“吵闹”多形容声音或环境，不说礼物吵闹。", "年轻": "体貌：“年轻”形容人的年龄样子，礼物没有年龄。"}, "sentence_index": 0, "correct_answer": "走心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱很走心，制冷特别快。", "explanation": "〈走心〉形容人做事用心，或礼物、话语能打动人，不用来说家电的制冷效果。这里应该说〈这台冰箱很好用〉。"}, {"text": "我今天很走心，心情好得很。", "explanation": "〈走心〉形容做的事情用心、能打动人，不用来说自己的心情。这里应该用〈开心〉。"}, {"text": "他走心地跑完了三公里。", "explanation": "这里把〈走心〉当成了“认真、努力”来修饰“跑”。〈走心〉只形容用心做的事或能打动人的话，不表示体力上的努力。这里应说〈他跑完了三公里〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材体型，不用来形容歌曲。"}, {"text": "走心", "is_correct": true, "explanation": "走心：形容歌曲用心、能打动人，修饰“歌”，符合句意。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材或体型偏小，不用于歌曲。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”指地势或坡度很陡，歌曲没有陡峭可言。"}], "explanations": {"高大": "体貌：“高大”形容人或物的身材体型，不用来形容歌曲。", "走心": "走心：形容歌曲用心、能打动人，修饰“歌”，符合句意。", "矮小": "体貌：“矮小”形容身材或体型偏小，不用于歌曲。", "陡峭": "语义：“陡峭”指地势或坡度很陡，歌曲没有陡峭可言。"}, "sentence_index": 6, "correct_answer": "走心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气很走心，很适合出去玩。", "explanation": "〈走心〉形容人用心做事，或话语、礼物能打动人，不能用来形容天气。这里想说“天气好”，应说〈天气很好〉。"}, {"text": "这张椅子很走心，坐起来很舒服。", "explanation": "〈走心〉形容人做事用心或礼物、话语能打动人，椅子没有用心可言。这里应该说〈这张椅子坐起来很舒服〉。"}, {"text": "他的体重很走心，比去年轻了三公斤。", "explanation": "〈走心〉形容用心做的事或能打动人的话，不能用来形容体重。这里想说体重下降，应说〈他比去年瘦了三公斤〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师的建议走心。", "corrected_sentence": "这位老师的建议很走心。", "error_description": "错误：形容词“走心”作谓语时前面漏了“很”，应说“很走心”，不能直接说“建议走心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友送了我一首走心地歌。", "corrected_sentence": "朋友送了我一首走心的歌。", "error_description": "形容词“走心”修饰名词“歌”时要用“的”，“地”只用于修饰动词，这里误用“地”，应说“走心的歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45e0f6af-1e14-4aed-833e-4339be456985') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
