INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经人类驯化饲养的马，与野马相对。", "primary_collocate": null, "pronunciation": "jiā mǎ", "ipa": "tɕia˥ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "家马是人类驯化的，野马生活在野外。", "target_word": "家马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家马和野马长得有点不一样。", "target_word": "家马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类很早就开始驯养家马了。", "target_word": "家马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家马比野马温顺，容易骑。", "target_word": "家马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究了家马的来源。", "target_word": "家马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家马是由野马慢慢驯化来的。", "target_word": "家马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上的家马有很多种。", "target_word": "家马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代人用家马打仗和运货。", "target_word": "家马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家马跟人生活久了，不怕人。", "target_word": "家马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些家马跑得很快，可以参加比赛。", "target_word": "家马", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "匹", "label": "量词"}, {"form": "家馬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "家马：经人类驯化的马，与野马相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8adc1b-9d40-4b43-9a93-25a8a9f56bae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家马", "is_correct": true, "explanation": "“家马”是经人类驯化的马，与“是人类驯化的，野马生活在野外”相符。"}, {"text": "野马", "is_correct": false, "explanation": "语义：野马不是人类驯化的，“野马是人类驯化的”与后半句“生活在野外”矛盾。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎一般不被人类驯化，句子前半部分说不通。"}, {"text": "鲸鱼", "is_correct": false, "explanation": "搭配：“驯化”一般用于可以饲养的动物，“鲸鱼是人类驯化的”搭配不当。"}], "explanations": {"家马": "“家马”是经人类驯化的马，与“是人类驯化的，野马生活在野外”相符。", "野马": "语义：野马不是人类驯化的，“野马是人类驯化的”与后半句“生活在野外”矛盾。", "老虎": "语义：老虎一般不被人类驯化，句子前半部分说不通。", "鲸鱼": "搭配：“驯化”一般用于可以饲养的动物，“鲸鱼是人类驯化的”搭配不当。"}, "sentence_index": 0, "correct_answer": "家马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些家马从来没在人身边生活过，一见人就跑。", "explanation": "这里应该用〈野马〉。家马是经人驯化饲养的马，句中说它从未和人生活，意思矛盾。"}, {"text": "家马一直生活在野外，没有人能骑它。", "explanation": "这里应该用〈野马〉。家马经人驯化，可以骑，句中描述的是野马。"}, {"text": "动物园里的家马是最后一批没被驯化的马。", "explanation": "这里应该用〈野马〉。家马本身就是被驯化的马，说它没被驯化自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家马", "is_correct": true, "explanation": "“世界上的家马有很多种”指经人驯化的马有许多品种，与句子相符。"}, {"text": "大熊猫", "is_correct": false, "explanation": "搭配：“大熊猫”通常只说一种，“有很多种”与它的类别不搭。"}, {"text": "黄河", "is_correct": false, "explanation": "语义：黄河只有一条，“世界上的黄河有很多种”说不通。"}, {"text": "长江", "is_correct": false, "explanation": "语义：长江只有一条，“世界上的长江有很多种”说不通。"}], "explanations": {"家马": "“世界上的家马有很多种”指经人驯化的马有许多品种，与句子相符。", "大熊猫": "搭配：“大熊猫”通常只说一种，“有很多种”与它的类别不搭。", "黄河": "语义：黄河只有一条，“世界上的黄河有很多种”说不通。", "长江": "语义：长江只有一条，“世界上的长江有很多种”说不通。"}, "sentence_index": 6, "correct_answer": "家马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这群家马从来没有被人类驯化过，都生活在野外。", "explanation": "这里应该用〈野马〉。家马是经人类驯化饲养的，句中说它从未被驯化，意思矛盾。"}, {"text": "家马是野生动物，人类从未驯化过它。", "explanation": "这里应该用〈野马〉。家马已经被人类驯化，句中说它是野生的，与家马的意思矛盾。"}, {"text": "人类从来没有驯养过家马，它们从不跟人生活。", "explanation": "这里应该用〈野马〉。家马是经人驯养、与人一起生活的马，句中说它从不跟人生活，意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只家马已经被人类驯服了。", "corrected_sentence": "这匹家马已经被人类驯服了。", "error_description": "“家马”的量词应为“匹”，不能用“只”，应说“这匹家马”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农场里养着三匹家马们。", "corrected_sentence": "农场里养着三匹家马。", "error_description": "“们”误用：有数量词“三匹”修饰时不能再加“们”，应说“三匹家马”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2975145d-ec5c-4acc-89f6-1575fae15c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
