INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96881, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "快快地走，到了那里。", "primary_collocate": null, "pronunciation": "gǎn dào", "ipa": "kan˨˩ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "听说妈妈生病了，我马上赶到医院。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一路小跑，很快赶到了车站。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们快步赶到了前面的亭子。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "接到电话，警察十分钟后赶到现场。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从公司一路跑，赶到了家门口。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到孩子哭，妈妈急忙赶到房间。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑车赶到了山脚下的小村子。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家听说老人摔倒了，都赶到了路边。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天快黑了，我们要赶到山下的小镇。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一路走得飞快，终于赶到了朋友家。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赶到了", "label": "完成体"}, {"form": "赶到过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "加快脚步或速度，到达某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d88c77-461f-4c74-96b2-9f5f37a1c376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96881, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赶到", "is_correct": true, "explanation": "正确答案：赶到（gǎn dào），快速到达某地。"}, {"text": "搞到", "is_correct": false, "explanation": "gǎo（第三声）与 gǎn 韵尾不同（-o 与 -n），意思是“弄到、得到”。"}, {"text": "砍到", "is_correct": false, "explanation": "kǎn（第三声）与 gǎn 声母不同，g 不送气而 k 送气，意思是“用刀斧砍”。"}, {"text": "赶掉", "is_correct": false, "explanation": "diào（第四声）与 dào 韵母不同，多一个 i 介音，意思是“赶走、除掉”。"}, {"text": "喊到", "is_correct": false, "explanation": "hǎn（第三声）与 gǎn 声母不同，h 与 g 发音部位不同，意思是“大声叫”。"}], "explanations": {"赶到": "正确答案：赶到（gǎn dào），快速到达某地。", "搞到": "gǎo（第三声）与 gǎn 韵尾不同（-o 与 -n），意思是“弄到、得到”。", "砍到": "kǎn（第三声）与 gǎn 声母不同，g 不送气而 k 送气，意思是“用刀斧砍”。", "赶掉": "diào（第四声）与 dào 韵母不同，多一个 i 介音，意思是“赶走、除掉”。", "喊到": "hǎn（第三声）与 gǎn 声母不同，h 与 g 发音部位不同，意思是“大声叫”。"}, "sentence_index": null, "correct_answer": "赶到"}, "level_3": {"options": [{"text": "赶到", "is_correct": true, "explanation": "“赶到”表示快速到达某处，与“马上”和“医院”相符。"}, {"text": "探望", "is_correct": false, "explanation": "搭配：“探望”的对象须是人，不能探望医院。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开”与“妈妈生病了”的担忧相矛盾，此时不会马上离开医院。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”表示庆贺，不表示到达，“马上祝贺医院”语义不通。"}], "explanations": {"赶到": "“赶到”表示快速到达某处，与“马上”和“医院”相符。", "探望": "搭配：“探望”的对象须是人，不能探望医院。", "离开": "语义：“离开”与“妈妈生病了”的担忧相矛盾，此时不会马上离开医院。", "祝贺": "语义：“祝贺”表示庆贺，不表示到达，“马上祝贺医院”语义不通。"}, "sentence_index": 0, "correct_answer": "赶到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我终于赶到了最后一班车。", "explanation": "这里应该用〈赶上〉。“赶到”后面接地点，“赶上”才能接班车、时间等。"}, {"text": "我在抽屉里赶到了丢失的钥匙。", "explanation": "这里应该用〈找到〉。“赶到”表示及时到达某处，不能接钥匙这类物品作宾语。"}, {"text": "他听说了这件事，终于赶到了好消息。", "explanation": "这里应该用〈得到〉。“赶到”不能接“消息”这类抽象事物，“得到消息”才正确。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96881, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赶到", "is_correct": true, "explanation": "正确答案：赶到（gǎn dào），快速到达某地。"}, {"text": "改到", "is_correct": false, "explanation": "gǎi（第三声）与 gǎn 韵尾不同（-i 与 -n），意思是“改成、改到”。"}, {"text": "干到", "is_correct": false, "explanation": "gàn（第四声）与 gǎn 声调不同，意思是“做、干到”。"}, {"text": "管到", "is_correct": false, "explanation": "guǎn 比 gǎn 多一个 u 介音，意思是“管辖到”。"}], "explanations": {"赶到": "正确答案：赶到（gǎn dào），快速到达某地。", "改到": "gǎi（第三声）与 gǎn 韵尾不同（-i 与 -n），意思是“改成、改到”。", "干到": "gàn（第四声）与 gǎn 声调不同，意思是“做、干到”。", "管到": "guǎn 比 gǎn 多一个 u 介音，意思是“管辖到”。"}, "sentence_index": null, "correct_answer": "赶到"}, "level_3": {"options": [{"text": "赶到", "is_correct": true, "explanation": "“赶到”表示到达某地，与“骑车”和“山脚下的小村子”搭配。"}, {"text": "翻过", "is_correct": false, "explanation": "搭配：“翻过”的宾语是山、岭、墙等，不能说翻过村子。"}, {"text": "俯瞰", "is_correct": false, "explanation": "语义：“俯瞰”需要站在高处往下看，与骑车在地面行进相矛盾。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”的对象须是人，不能嘲笑村子。"}], "explanations": {"赶到": "“赶到”表示到达某地，与“骑车”和“山脚下的小村子”搭配。", "翻过": "搭配：“翻过”的宾语是山、岭、墙等，不能说翻过村子。", "俯瞰": "语义：“俯瞰”需要站在高处往下看，与骑车在地面行进相矛盾。", "嘲笑": "搭配：“嘲笑”的对象须是人，不能嘲笑村子。"}, "sentence_index": 6, "correct_answer": "赶到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把家具赶到了新房子里。", "explanation": "这里应该用〈搬〉。“赶到”的“赶”指驱赶或急忙前往，不能用于搬运家具。"}, {"text": "我们坐了十个小时的车，终于赶到了两个小时。", "explanation": "这里应该用〈花〉。“赶到”后面只能接地点，不能接“两个小时”这样的时间段。"}, {"text": "听完这个消息，他赶到了悲伤。", "explanation": "这里应该用〈陷入〉。“赶到”只接地点，不能接“悲伤”这类抽象的心理状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下课铃一响，我马上赶到过车站。", "corrected_sentence": "下课铃一响，我马上赶到车站。", "error_description": "错误：“马上”表示即刻，与表示已完成经历的“过”冲突，应去掉“过”。正确：“马上赶到车站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨下得很大，他们却赶到了雨。", "corrected_sentence": "雨下得很大，他们却赶到了码头。", "error_description": "错误：“赶到”的宾语须是地点，“雨”不是地点，不能说“赶到雨”。正确：“赶到了码头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
