INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96882, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "及时到达。", "primary_collocate": null, "pronunciation": "gǎn dào", "ipa": "kan˨˩ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "电影还没开始，我就赶到了电影院。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好他赶到了，会议刚好开始。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我赶到机场时，飞机还没起飞。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生及时赶到，病人得救了。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在婚礼开始前赶到了教堂。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他九点前赶到公司，没有迟到。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们赶到车站，火车正好进站。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员三分钟就赶到了，火很快灭了。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在考试前五分钟赶到了学校。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你明天能赶到吗？我们等你吃饭。", "target_word": "赶到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赶到了", "label": "完成体"}, {"form": "赶到过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "在规定或需要的时间之前到达，没有迟到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d88c77-461f-4c74-96b2-9f5f37a1c376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96882, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赶到", "is_correct": true, "explanation": "正确答案：赶到（gǎn dào），及时到达某地。"}, {"text": "搞到", "is_correct": false, "explanation": "gǎo（第三声）与 gǎn 韵尾不同（-o 与 -n），意思是“弄到、得到”。"}, {"text": "砍到", "is_correct": false, "explanation": "kǎn（第三声）与 gǎn 声母不同，g 不送气而 k 送气，意思是“用刀斧砍”。"}, {"text": "赶掉", "is_correct": false, "explanation": "diào（第四声）与 dào 韵母不同，多一个 i 介音，意思是“赶走、除掉”。"}, {"text": "喊到", "is_correct": false, "explanation": "hǎn（第三声）与 gǎn 声母不同，h 与 g 发音部位不同，意思是“大声叫”。"}], "explanations": {"赶到": "正确答案：赶到（gǎn dào），及时到达某地。", "搞到": "gǎo（第三声）与 gǎn 韵尾不同（-o 与 -n），意思是“弄到、得到”。", "砍到": "kǎn（第三声）与 gǎn 声母不同，g 不送气而 k 送气，意思是“用刀斧砍”。", "赶掉": "diào（第四声）与 dào 韵母不同，多一个 i 介音，意思是“赶走、除掉”。", "喊到": "hǎn（第三声）与 gǎn 声母不同，h 与 g 发音部位不同，意思是“大声叫”。"}, "sentence_index": null, "correct_answer": "赶到"}, "level_3": {"options": [{"text": "赶到", "is_correct": true, "explanation": "“赶到”表示及时到达，与“电影还没开始”的语境相符。"}, {"text": "错过", "is_correct": false, "explanation": "语义：“错过”是没有赶上，与“电影还没开始”的语境矛盾。"}, {"text": "预订", "is_correct": false, "explanation": "语义：“预订”是事先订下，与“电影还没开始，我就……”所表达的到场之意不符。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：“莅临”是敬辞，与这段口语叙述的语气不符。"}], "explanations": {"赶到": "“赶到”表示及时到达，与“电影还没开始”的语境相符。", "错过": "语义：“错过”是没有赶上，与“电影还没开始”的语境矛盾。", "预订": "语义：“预订”是事先订下，与“电影还没开始，我就……”所表达的到场之意不符。", "莅临": "语域：“莅临”是敬辞，与这段口语叙述的语气不符。"}, "sentence_index": 0, "correct_answer": "赶到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天赶到了一封信。", "explanation": "这里应该用〈收到〉。“赶到”表示及时到达，不能接“信”作宾语。"}, {"text": "他按时赶到了作业，老师很满意。", "explanation": "这里应该用〈完成〉。“赶到”不能接“作业”这类任务作宾语。"}, {"text": "我们在超市赶到了牛奶。", "explanation": "这里应该用〈买到〉。“赶到”的宾语必须是地点，不能接“牛奶”这类物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96882, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赶到", "is_correct": true, "explanation": "正确答案：赶到（gǎn dào），及时到达某地。"}, {"text": "改到", "is_correct": false, "explanation": "gǎi（第三声）与 gǎn 韵尾不同（-i 与 -n），意思是“改成、改到”。"}, {"text": "干到", "is_correct": false, "explanation": "gàn（第四声）与 gǎn 声调不同，意思是“做、干到”。"}, {"text": "管到", "is_correct": false, "explanation": "guǎn 比 gǎn 多一个 u 介音，意思是“管辖到”。"}], "explanations": {"赶到": "正确答案：赶到（gǎn dào），及时到达某地。", "改到": "gǎi（第三声）与 gǎn 韵尾不同（-i 与 -n），意思是“改成、改到”。", "干到": "gàn（第四声）与 gǎn 声调不同，意思是“做、干到”。", "管到": "guǎn 比 gǎn 多一个 u 介音，意思是“管辖到”。"}, "sentence_index": null, "correct_answer": "赶到"}, "level_3": {"options": [{"text": "赶到", "is_correct": true, "explanation": "“赶到”表示及时到达车站，与“火车正好进站”的语境相符。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的对象不能是车站，且与“火车正好进站”的语境不符。"}, {"text": "登记", "is_correct": false, "explanation": "搭配：“登记”的对象是人、票或信息，不能说登记车站。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”的对象须是人，不能嘲笑车站。"}], "explanations": {"赶到": "“赶到”表示及时到达车站，与“火车正好进站”的语境相符。", "吃掉": "搭配：“吃掉”的对象不能是车站，且与“火车正好进站”的语境不符。", "登记": "搭配：“登记”的对象是人、票或信息，不能说登记车站。", "嘲笑": "搭配：“嘲笑”的对象须是人，不能嘲笑车站。"}, "sentence_index": 6, "correct_answer": "赶到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "货车把货物赶到了仓库。", "explanation": "这里应该用〈运〉。“赶到”的“赶”指驱赶或急忙前往，不能用于运送货物。"}, {"text": "我们终于赶到了一个好办法。", "explanation": "这里应该用〈想到〉。“赶到”的宾语须是地点，不能接“办法”这类抽象事物。"}, {"text": "我们三点前赶到了这本书。", "explanation": "这里应该用〈找到〉。“赶到”不能接“书”这类物品作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我十点前赶到着教室，老师还没进来。", "corrected_sentence": "我十点前赶到了教室，老师还没进来。", "error_description": "错误：结果补语“到”后面误用了“着”，写成“赶到着教室”。正确：“赶到了教室”，“到”之后应用表示完成的“了”，“着”不能用于完成的结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她七点半前赶到到学校，没有迟到。", "corrected_sentence": "她七点半前赶到学校，没有迟到。", "error_description": "错误：“到”被重复，写成“赶到到学校”。正确：“赶到学校”，“赶到”只用一个“到”，后面直接接地点“学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96883, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贫穷", "is_correct": true, "explanation": "贫穷指没有钱、生活困难，与“很有钱”的意思相反。"}, {"text": "热闹", "is_correct": false, "explanation": "无关：“热闹”形容场面喧闹，与富裕没有反义关系。"}, {"text": "平坦", "is_correct": false, "explanation": "无关：“平坦”形容地面不起伏，与富裕无关。"}, {"text": "清晰", "is_correct": false, "explanation": "无关：“清晰”形容清楚、分明，不与富裕互为反义。"}], "correct_answer": "贫穷", "explanations": {"贫穷": "贫穷指没有钱、生活困难，与“很有钱”的意思相反。", "热闹": "无关：“热闹”形容场面喧闹，与富裕没有反义关系。", "平坦": "无关：“平坦”形容地面不起伏，与富裕无关。", "清晰": "无关：“清晰”形容清楚、分明，不与富裕互为反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96883, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贫困", "is_correct": true, "explanation": "贫困指财物少、生活艰难，与富裕的意思相反。"}, {"text": "整齐", "is_correct": false, "explanation": "无关：“整齐”形容排列有序，与富裕没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "无关：“复杂”形容情况繁多、不简单，与富裕无关。"}, {"text": "响亮", "is_correct": false, "explanation": "无关：“响亮”形容声音大而清楚，不与富裕互为反义。"}], "correct_answer": "贫困", "explanations": {"贫困": "贫困指财物少、生活艰难，与富裕的意思相反。", "整齐": "无关：“整齐”形容排列有序，与富裕没有反义关系。", "复杂": "无关：“复杂”形容情况繁多、不简单，与富裕无关。", "响亮": "无关：“响亮”形容声音大而清楚，不与富裕互为反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96883, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很有钱，生活过得很好。", "primary_collocate": null, "pronunciation": "fù yù", "ipa": "fu˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "他的邻居非常富裕，住着大房子。", "target_word": "富裕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个富裕的家庭有三辆车。", "target_word": "富裕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她嫁给了一个富裕的商人。", "target_word": "富裕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们城市里的人比较富裕。", "target_word": "富裕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠做生意富裕了。", "target_word": "富裕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "富裕的人也会有烦恼。", "target_word": "富裕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这对夫妻很富裕，常常去国外旅游。", "target_word": "富裕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就生活得很富裕。", "target_word": "富裕", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "住在这个小区的人都很富裕。", "target_word": "富裕", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想让父母过得更富裕。", "target_word": "富裕", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "富裕起来", "label": "补语形式"}, {"form": "富裕户", "label": "复合"}], "register": "中性", "sense_fingerprint": "很有钱、生活过得好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad778c81-0308-42c1-ae9b-f236d49633da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "富裕", "is_correct": true, "explanation": "富裕指很有钱、生活过得好，与“住着大房子”相符。"}, {"text": "贫穷", "is_correct": false, "explanation": "语义：贫穷指没钱，与“住着大房子”互相矛盾。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”多形容天气或物体，不用来形容人。"}, {"text": "遥远", "is_correct": false, "explanation": "搭配：“遥远”说距离或时间，不用来形容人。"}], "explanations": {"富裕": "富裕指很有钱、生活过得好，与“住着大房子”相符。", "贫穷": "语义：贫穷指没钱，与“住着大房子”互相矛盾。", "干燥": "搭配：“干燥”多形容天气或物体，不用来形容人。", "遥远": "搭配：“遥远”说距离或时间，不用来形容人。"}, "sentence_index": 0, "correct_answer": "富裕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的知识很富裕。", "explanation": "这里应该用〈丰富〉。丰富指种类、数量多；富裕指财物充足，不用来形容知识。"}, {"text": "班里的气氛很富裕，大家都积极发言。", "explanation": "这里应该用〈活跃〉。活跃指气氛热烈、有生气；富裕指财物充足，不用来形容气氛。"}, {"text": "这首歌很富裕，听起来很舒服。", "explanation": "这里应该用〈动听〉。动听指声音好听；富裕指财物充足，不用来形容歌曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "富裕", "is_correct": true, "explanation": "富裕指很有钱、生活好，与“常常去国外旅游”相符。"}, {"text": "贫困", "is_correct": false, "explanation": "语义：贫困指生活艰难、没钱，与“常常去国外旅游”互相矛盾。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”形容空间，不用来形容夫妻。"}, {"text": "凉爽", "is_correct": false, "explanation": "搭配：“凉爽”形容天气或感觉，不用来形容人。"}], "explanations": {"富裕": "富裕指很有钱、生活好，与“常常去国外旅游”相符。", "贫困": "语义：贫困指生活艰难、没钱，与“常常去国外旅游”互相矛盾。", "狭窄": "搭配：“狭窄”形容空间，不用来形容夫妻。", "凉爽": "搭配：“凉爽”形容天气或感觉，不用来形容人。"}, "sentence_index": 6, "correct_answer": "富裕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房间很富裕。", "explanation": "这里应该用〈宽敞〉。宽敞指空间大；富裕指财物充足，不用来形容房间。"}, {"text": "她的身材很富裕。", "explanation": "这里应该用〈丰满〉。丰满指人的身体饱满匀称；富裕指财物充足，不用来形容身材。"}, {"text": "他的睡眠很富裕。", "explanation": "这里应该用〈充足〉。充足指数量够多；富裕指财物充足，不用来形容睡眠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年，他们靠种茶富裕下来了。", "corrected_sentence": "这几年，他们靠种茶富裕起来了。", "error_description": "错误形式：“富裕下来了”；正确形式：“富裕起来了”。表示状态逐渐变好，趋向补语应用“起来”，不用“下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全家人都过得很富裕着。", "corrected_sentence": "全家人都过得很富裕。", "error_description": "错误形式：“很富裕着”；正确形式：“很富裕”。“富裕”表示生活状态时一般不带“着”，应直接说“过得很富裕”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
