INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从高的地方掉下来，或者摔倒。", "primary_collocate": null, "pronunciation": "diē", "ipa": "tie˥", "syllable_count": 1, "sentences": [{"text": "孩子从床上跌下来了。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心跌了一跤。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路太滑，她跌在地上了。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫从桌子上跌了下去。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从梯子上跌下来，腿受了伤。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在楼梯上跌过一次，现在还害怕。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟从树上跌下来了。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑车跌进了小河里。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹学滑冰，跌了好几次。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在浴室里跌得很重，住了几天院。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跌了", "label": "体标"}, {"form": "跌过", "label": "体标"}, {"form": "跌倒", "label": "复合"}], "register": "中性", "sense_fingerprint": "跌：人从高处掉下来或摔倒在地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c091977-6e47-4361-b22e-fc75be886fea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跌", "is_correct": true, "explanation": "跌：diē（第一声），指从高处掉下或摔倒。"}, {"text": "叠", "is_correct": false, "explanation": "叠 dié（第二声）与跌 diē（第一声）声调不同，意思是折叠。"}, {"text": "贴", "is_correct": false, "explanation": "贴 tiē 与 diē 声母送气不同（t 送气，d 不送气），意思是粘住。"}, {"text": "捏", "is_correct": false, "explanation": "捏 niē 与 diē 声母不同（n 与 d），意思是用手指夹住或按压。"}, {"text": "低", "is_correct": false, "explanation": "低 dī 与 diē 韵母不同（少了 e），意思是位置或高度在下。"}], "explanations": {"跌": "跌：diē（第一声），指从高处掉下或摔倒。", "叠": "叠 dié（第二声）与跌 diē（第一声）声调不同，意思是折叠。", "贴": "贴 tiē 与 diē 声母送气不同（t 送气，d 不送气），意思是粘住。", "捏": "捏 niē 与 diē 声母不同（n 与 d），意思是用手指夹住或按压。", "低": "低 dī 与 diē 韵母不同（少了 e），意思是位置或高度在下。"}, "sentence_index": null, "correct_answer": "跌"}, "level_3": {"options": [{"text": "跌", "is_correct": true, "explanation": "跌：从高处掉下，与“从床上”“下来”搭配，符合语境。"}, {"text": "升", "is_correct": false, "explanation": "语义：“升”表示向上，与句中“下来”的方向相反。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”需要带宾语，“扔下来”缺少宾语，句子不成立。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用液体，不能说“从床上喝下来”。"}], "explanations": {"跌": "跌：从高处掉下，与“从床上”“下来”搭配，符合语境。", "升": "语义：“升”表示向上，与句中“下来”的方向相反。", "扔": "配价：“扔”需要带宾语，“扔下来”缺少宾语，句子不成立。", "喝": "语义：“喝”指饮用液体，不能说“从床上喝下来”。"}, "sentence_index": 0, "correct_answer": "跌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把水温跌到了零度。", "explanation": "这里应该用〈降〉。跌指人或东西自己从高处掉下、摔倒，不能用“把”表示人主动把水温降低。"}, {"text": "他用力把杯子跌到了地上。", "explanation": "这里应该用〈摔〉。跌指物体自己掉落，人用力把杯子扔到地上要用“摔”。"}, {"text": "他为了省事，把垃圾跌进了垃圾桶。", "explanation": "这里应该用〈扔〉。跌指物体自己掉落，人有意把垃圾放进桶里要用“扔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96885, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跌", "is_correct": true, "explanation": "跌：diē（第一声），指从高处掉下或摔倒。"}, {"text": "碟", "is_correct": false, "explanation": "碟 dié（第二声）与跌 diē（第一声）声调不同，意思是盘子。"}, {"text": "帖", "is_correct": false, "explanation": "帖 tiē 与 diē 声母送气不同（t 送气，d 不送气），意思是帖子或字帖。"}, {"text": "滴", "is_correct": false, "explanation": "滴 dī 与 diē 韵母不同（少了 e），意思是液体一点一点落下。"}], "explanations": {"跌": "跌：diē（第一声），指从高处掉下或摔倒。", "碟": "碟 dié（第二声）与跌 diē（第一声）声调不同，意思是盘子。", "帖": "帖 tiē 与 diē 声母送气不同（t 送气，d 不送气），意思是帖子或字帖。", "滴": "滴 dī 与 diē 韵母不同（少了 e），意思是液体一点一点落下。"}, "sentence_index": null, "correct_answer": "跌"}, "level_3": {"options": [{"text": "跌", "is_correct": true, "explanation": "跌：从树上掉下，与“小鸟”“树上”“下来”搭配，符合语境。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中行进，与“树上”“下来”的情境不符。"}, {"text": "脱", "is_correct": false, "explanation": "搭配：“脱”多指脱去衣物，不能说小鸟“脱下来”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能说小鸟“从树上吃下来”。"}], "explanations": {"跌": "跌：从树上掉下，与“小鸟”“树上”“下来”搭配，符合语境。", "游": "语义：“游”指在水中行进，与“树上”“下来”的情境不符。", "脱": "搭配：“脱”多指脱去衣物，不能说小鸟“脱下来”。", "吃": "语义：“吃”指进食，不能说小鸟“从树上吃下来”。"}, "sentence_index": 6, "correct_answer": "跌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为了救人，把绳子跌进了井里。", "explanation": "这里应该用〈投〉。跌表示物体自己掉落，不能表示人有意把绳子投进井里。"}, {"text": "他用力把门跌开了。", "explanation": "这里应该用〈推〉。跌是不及物动词，不能带宾语表示人施力使门移动。"}, {"text": "他把皮球跌给了弟弟。", "explanation": "这里应该用〈抛〉。跌只表示物体自己掉落，不能表示人主动把东西投给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在路上跌了地上，裤子磨破了。", "corrected_sentence": "他在路上跌到了地上，裤子磨破了。", "error_description": "错误形式：“跌了地上”；正确形式：“跌到了地上”。“跌”后接处所要用介词“到”或“在”，直接说“跌了地上”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人在台阶上跌了上去，扶住了栏杆。", "corrected_sentence": "老人在台阶上跌了下去，扶住了栏杆。", "error_description": "错误形式：“跌了上去”；正确形式：“跌了下去”。“跌”指从高处掉落，方向补语应为“下去”，“上去”与语义相反。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96886, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "涨", "is_correct": true, "explanation": "涨：与“跌”构成反义，表示价格上升。"}, {"text": "读", "is_correct": false, "explanation": "读：与价格变动无关，不是“跌”的反义词。"}, {"text": "唱", "is_correct": false, "explanation": "唱：与价格变动无关，不是“跌”的反义词。"}, {"text": "吃", "is_correct": false, "explanation": "吃：与价格变动无关，不是“跌”的反义词。"}], "correct_answer": "涨", "explanations": {"涨": "涨：与“跌”构成反义，表示价格上升。", "读": "读：与价格变动无关，不是“跌”的反义词。", "唱": "唱：与价格变动无关，不是“跌”的反义词。", "吃": "吃：与价格变动无关，不是“跌”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
