INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96886, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "价格、股价或行情等数值下降。", "primary_collocate": null, "pronunciation": "diē", "ipa": "tie˥", "syllable_count": 1, "sentences": [{"text": "今天苹果的价格跌了不少。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只股票三天跌了一成。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变热，菜价一直在跌。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机价格跌到了一千元。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房价跌了，很多人想买房。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饮料的价格前两天跌了一块钱。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天股市大跌，大家都很担心。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油价格跌得很快。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年大豆的价格跌了两成。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月牛奶的价钱跌过一次。", "target_word": "跌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跌了", "label": "体标"}, {"form": "跌过", "label": "体标"}, {"form": "跌价", "label": "复合"}], "register": "中性", "sense_fingerprint": "跌：价格、股价或行情等数值下降", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c091977-6e47-4361-b22e-fc75be886fea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96886, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跌", "is_correct": true, "explanation": "跌：diē（第一声），指价格下降。"}, {"text": "叠", "is_correct": false, "explanation": "叠 dié（第二声）与跌 diē（第一声）声调不同，意思是折叠。"}, {"text": "贴", "is_correct": false, "explanation": "贴 tiē 与 diē 声母送气不同（t 送气，d 不送气），意思是粘住。"}, {"text": "捏", "is_correct": false, "explanation": "捏 niē 与 diē 声母不同（n 与 d），意思是用手指夹住或按压。"}, {"text": "低", "is_correct": false, "explanation": "低 dī 与 diē 韵母不同（少了 e），意思是位置或数量在下。"}], "explanations": {"跌": "跌：diē（第一声），指价格下降。", "叠": "叠 dié（第二声）与跌 diē（第一声）声调不同，意思是折叠。", "贴": "贴 tiē 与 diē 声母送气不同（t 送气，d 不送气），意思是粘住。", "捏": "捏 niē 与 diē 声母不同（n 与 d），意思是用手指夹住或按压。", "低": "低 dī 与 diē 韵母不同（少了 e），意思是位置或数量在下。"}, "sentence_index": null, "correct_answer": "跌"}, "level_3": {"options": [{"text": "跌", "is_correct": true, "explanation": "跌：价格下降，与“价格”搭配，“跌了不少”符合语境。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指快速移动，不能用于描述价格的变化。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与价格无关，句子不通。"}, {"text": "读", "is_correct": false, "explanation": "语义：“读”指看文字发出声音，与价格无关，句子不通。"}], "explanations": {"跌": "跌：价格下降，与“价格”搭配，“跌了不少”符合语境。", "跑": "语义：“跑”指快速移动，不能用于描述价格的变化。", "吃": "语义：“吃”指进食，与价格无关，句子不通。", "读": "语义：“读”指看文字发出声音，与价格无关，句子不通。"}, "sentence_index": 0, "correct_answer": "跌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力把石头跌过了河。", "explanation": "这里应该用〈扔〉。跌表示物体自己掉落，不能表示人用力把石头扔过河。"}, {"text": "我们把价格跌到了最低。", "explanation": "这里应该用〈降〉。跌指价格自然下降，不能表示卖方主动降价，“把价格”的说法应用降。"}, {"text": "商店把衣服跌了八折。", "explanation": "这里应该用〈打〉。跌表示价格自然下降，不能表示商店主动给商品打折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96886, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跌", "is_correct": true, "explanation": "跌：diē（第一声），指价格下降。"}, {"text": "碟", "is_correct": false, "explanation": "碟 dié（第二声）与跌 diē（第一声）声调不同，意思是盘子。"}, {"text": "帖", "is_correct": false, "explanation": "帖 tiē 与 diē 声母送气不同（t 送气，d 不送气），意思是帖子或字帖。"}, {"text": "滴", "is_correct": false, "explanation": "滴 dī 与 diē 韵母不同（少了 e），意思是液体一点一点落下。"}], "explanations": {"跌": "跌：diē（第一声），指价格下降。", "碟": "碟 dié（第二声）与跌 diē（第一声）声调不同，意思是盘子。", "帖": "帖 tiē 与 diē 声母送气不同（t 送气，d 不送气），意思是帖子或字帖。", "滴": "滴 dī 与 diē 韵母不同（少了 e），意思是液体一点一点落下。"}, "sentence_index": null, "correct_answer": "跌"}, "level_3": {"options": [{"text": "跌", "is_correct": true, "explanation": "跌：股市下降，与“股市大”搭配，符合语境。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”的主体应是人，不能说“股市大哭”。"}, {"text": "喊", "is_correct": false, "explanation": "搭配：“喊”的主体应是人，不能说“股市大喊”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声歌唱，与股市的情况不符。"}], "explanations": {"跌": "跌：股市下降，与“股市大”搭配，符合语境。", "哭": "搭配：“哭”的主体应是人，不能说“股市大哭”。", "喊": "搭配：“喊”的主体应是人，不能说“股市大喊”。", "唱": "语义：“唱”指发声歌唱，与股市的情况不符。"}, "sentence_index": 6, "correct_answer": "跌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "银行把利率跌到了百分之五。", "explanation": "这里应该用〈调〉（调低）。跌指价格、行情自然下降，银行主动调整利率要用“调”。"}, {"text": "两个人把桌子跌进了屋。", "explanation": "这里应该用〈抬〉。跌不能带宾语表示人搬动东西，“把桌子”的动作要用抬。"}, {"text": "他一脚把球跌进了网。", "explanation": "这里应该用〈踢〉。跌表示物体自己掉落，不能表示人用脚把球踢进去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电脑的价格跌在了五千块。", "corrected_sentence": "这台电脑的价格跌到了五千块。", "error_description": "错误形式：“跌在了五千块”；正确形式：“跌到了五千块”。表示价格下降到某个数额要用补语“到”，“在”不能表示结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年冬天，柴油的价格跌地很厉害。", "corrected_sentence": "去年冬天，柴油的价格跌得很厉害。", "error_description": "错误：程度补语的标记应为“得”，误用了状语标记“地”；正确形式：“跌得很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
