INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96890, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "车的前面。", "primary_collocate": null, "pronunciation": "chē qián", "ipa": "ʈʂʰɤ˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他走到车前，打开了门。", "target_word": "车前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车前放着两个大箱子。", "target_word": "车前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑到车前不走了。", "target_word": "车前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车前有人在大声说话。", "target_word": "车前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在车前玩。", "target_word": "车前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察站在车前，让我们停车。", "target_word": "车前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车前的路上有很多水。", "target_word": "车前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把牌子放在车前。", "target_word": "车前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车前贴着一张红纸。", "target_word": "车前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只鸟飞到车前。", "target_word": "车前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "车的前面这个方位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2b2c253-1912-4008-90c3-ad21f0ccc4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96890, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "车前", "is_correct": true, "explanation": "车前：车子前面，正确答案。"}, {"text": "茶钱", "is_correct": false, "explanation": "chá（第二声）与 chē（第一声）韵母、声调都不同，意思是喝茶的费用。"}, {"text": "出钱", "is_correct": false, "explanation": "chū 与 chē 韵母不同（u 与 e），意思是拿出钱来付款。"}, {"text": "差钱", "is_correct": false, "explanation": "chā 与 chē 韵母不同（a 与 e），意思是缺钱。"}], "explanations": {"车前": "车前：车子前面，正确答案。", "茶钱": "chá（第二声）与 chē（第一声）韵母、声调都不同，意思是喝茶的费用。", "出钱": "chū 与 chē 韵母不同（u 与 e），意思是拿出钱来付款。", "差钱": "chā 与 chē 韵母不同（a 与 e），意思是缺钱。"}, "sentence_index": null, "correct_answer": "车前"}, "level_3": {"options": [{"text": "车前", "is_correct": true, "explanation": "车前：车子前面，可以作“走到”的地点。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“走到”后要接具体地点，“方向”不能作到达的地点。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不是可以走到并打开门的地点。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是可以走过去的地点。"}], "explanations": {"车前": "车前：车子前面，可以作“走到”的地点。", "方向": "搭配：“走到”后要接具体地点，“方向”不能作到达的地点。", "水": "语义：水不是可以走到并打开门的地点。", "书包": "语义：书包不是可以走过去的地点。"}, "sentence_index": 0, "correct_answer": "车前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车前明天要去上班。", "explanation": "这里应该用〈司机〉。车前指车子前面的位置，不能作有生命的人的主语。"}, {"text": "学校的车前有一片树林。", "explanation": "这里应该用〈前面〉。车前只用于车辆的前方，学校的前方要用“前面”或“门前”。"}, {"text": "车前发动了。", "explanation": "这里应该用〈车〉。车前指车子前面的位置，不能作“发动”的主语，发动的是整辆车，应说“车发动了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96890, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "出钱", "is_correct": false, "explanation": "chū 与 chē 韵母不同（u 与 e），意思是拿出钱来付款。"}, {"text": "车前", "is_correct": true, "explanation": "车前：车子前面，正确答案。"}, {"text": "赊钱", "is_correct": false, "explanation": "shē（第一声）与 chē 声母不同，意思是赊账。"}, {"text": "车帘", "is_correct": false, "explanation": "lián（第二声）与 qián（第二声）声母不同，意思是车子上的帘子。"}], "explanations": {"出钱": "chū 与 chē 韵母不同（u 与 e），意思是拿出钱来付款。", "车前": "车前：车子前面，正确答案。", "赊钱": "shē（第一声）与 chē 声母不同，意思是赊账。", "车帘": "lián（第二声）与 qián（第二声）声母不同，意思是车子上的帘子。"}, "sentence_index": null, "correct_answer": "车前"}, "level_3": {"options": [{"text": "车前", "is_correct": true, "explanation": "车前：车子前面，可以指“路上”的位置。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是处所，“手机的路上”说不通。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是处所，不能指路上。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是处所，“电脑的路上”说不通。"}], "explanations": {"车前": "车前：车子前面，可以指“路上”的位置。", "手机": "语义：手机不是处所，“手机的路上”说不通。", "饼干": "语义：饼干不是处所，不能指路上。", "电脑": "语义：电脑不是处所，“电脑的路上”说不通。"}, "sentence_index": 6, "correct_answer": "车前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的车前有三个。", "explanation": "这里把〈车前〉当成了可以计数的车子部件，但车前只指车子前面的位置，不能用“三个”计算。"}, {"text": "车前我去过北京。", "explanation": "车前只表示空间位置，不能表示时间上的“以前”。"}, {"text": "他买了一个车前送给朋友。", "explanation": "这里应该用〈车前灯〉之类的车身部件。车前指车子前面的位置，不是可以买卖的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她站在车前了拍照。", "corrected_sentence": "她站在车前拍照。", "error_description": "“了”位置错误：“了”不能紧跟在“车前”之后、动词之前，应删去“了”，说“站在车前拍照”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们走车前了。", "corrected_sentence": "我们走到车前了。", "error_description": "“走”后直接接“车前”不通，此处应加补语“到”，说“走到车前了”，不能说“走车前了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b2ac531-1a42-412a-8594-0a97b4befe47') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
