INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手的第五指，最短最细的手指。", "primary_collocate": null, "pronunciation": "xiǎo zhǐ", "ipa": "ɕiau˨˩˦ ʈʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "五根手指中，小指最细。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小指是手上的第五根手指。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的小指比无名指短一点。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了我左手的小指。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹钢琴时，小指不太有力。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的左手小指戴着一枚戒指。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我摔了一跤，小指肿了。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手冷的时候，小指先发麻。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根小指又短又细。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的右手小指弯不了。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "右小指", "label": "复合"}], "register": "中性", "sense_fingerprint": "小指：手的第五指，最短最细", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e8e5b6b-41e6-4dbe-82c6-698d5104ef7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96892, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小指", "is_correct": true, "explanation": "正确。小指是手的第五指，最短最细。"}, {"text": "小职", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是小职位。"}, {"text": "校址", "is_correct": false, "explanation": "xiào（第四声）与 xiǎo（第三声）声调不同，意思是学校所在的地址。"}, {"text": "小枝", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是小的树枝。"}], "explanations": {"小指": "正确。小指是手的第五指，最短最细。", "小职": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是小职位。", "校址": "xiào（第四声）与 xiǎo（第三声）声调不同，意思是学校所在的地址。", "小枝": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是小的树枝。"}, "sentence_index": null, "correct_answer": "小指"}, "level_3": {"options": [{"text": "小指", "is_correct": true, "explanation": "正确。“五根手指”之中最细的是小指。"}, {"text": "手掌", "is_correct": false, "explanation": "语义：手掌不是“五根手指”之一。"}, {"text": "手腕", "is_correct": false, "explanation": "语义：手腕不是手指，不属于“五根手指”。"}, {"text": "指甲", "is_correct": false, "explanation": "搭配：“五根手指中”只与手指名称搭配，指甲不是手指。"}], "explanations": {"小指": "正确。“五根手指”之中最细的是小指。", "手掌": "语义：手掌不是“五根手指”之一。", "手腕": "语义：手腕不是手指，不属于“五根手指”。", "指甲": "搭配：“五根手指中”只与手指名称搭配，指甲不是手指。"}, "sentence_index": 0, "correct_answer": "小指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一双手有十根小指。", "explanation": "这里应该用〈手指〉。一只手有五根手指，小指只是其中一根，不能数作十根。"}, {"text": "他用一根小指搬起了一张大桌子。", "explanation": "这里应该用〈双手〉。小指又短又细，没有力气搬起大桌子。"}, {"text": "我每天早上穿小指。", "explanation": "这里应该用〈袜子〉。“穿”搭配衣服、鞋袜，小指是身体部位，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96892, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小指", "is_correct": true, "explanation": "正确。小指是手的第五指，最短最细。"}, {"text": "小吃", "is_correct": false, "explanation": "chī 与 zhǐ 声母（ch／zh）和声调都不同，意思是简单的食品。"}, {"text": "小史", "is_correct": false, "explanation": "shǐ（第三声）与 zhǐ（第三声）仅声母不同（sh／zh），意思是简略的史书。"}, {"text": "小子", "is_correct": false, "explanation": "zi 是平舌音，zhǐ 是翘舌音，意思是男孩子。"}], "explanations": {"小指": "正确。小指是手的第五指，最短最细。", "小吃": "chī 与 zhǐ 声母（ch／zh）和声调都不同，意思是简单的食品。", "小史": "shǐ（第三声）与 zhǐ（第三声）仅声母不同（sh／zh），意思是简略的史书。", "小子": "zi 是平舌音，zhǐ 是翘舌音，意思是男孩子。"}, "sentence_index": null, "correct_answer": "小指"}, "level_3": {"options": [{"text": "小指", "is_correct": true, "explanation": "正确。摔伤后肿起来的是小指，它是身体部位。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯不会肿。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“肿”用于身体部位，不用于物品。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不会肿。"}], "explanations": {"小指": "正确。摔伤后肿起来的是小指，它是身体部位。", "灯": "语义：灯不会肿。", "手机": "搭配：“肿”用于身体部位，不用于物品。", "蛋糕": "语义：蛋糕不会肿。"}, "sentence_index": 6, "correct_answer": "小指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他戴上了小指，然后去开车。", "explanation": "这里应该用〈手套〉。“戴”搭配手套、手表，小指是身体部位，不能戴上。"}, {"text": "他吹响了小指。", "explanation": "这里应该用〈哨子〉。“吹”搭配哨子、乐器，小指不能被吹响。"}, {"text": "他脱掉了小指。", "explanation": "这里应该用〈鞋子〉。“脱”搭配鞋袜、衣服，小指不能脱掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
