INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96893, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一天接着一天，接连不断地。", "primary_collocate": null, "pronunciation": "lián tiān", "ipa": "ljɛn˧˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "连天下雨，我们没法出去玩。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期连天加班，他累坏了。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连天大雪，山路很难走。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连天没睡好觉，今天很没精神。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连天吃面条，我现在不想看到面条了。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈连天做饭，今天想休息一下。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里连天刮大风，门都关不上。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子连天发烧，爸爸妈妈都很着急。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连天练习写字，写得好多了。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连天不见太阳，大家心情都不太好。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連天", "label": "繁体"}], "register": "通用", "sense_fingerprint": "副词，放在动词前，表示一天接着一天地持续做某事或出现某种情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连天", "is_correct": true, "explanation": "正确：“连天”表示一天接一天，与句中“下雨、没法出去玩”的持续情形相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指偶然发生，与“没法出去玩”所说的持续阴雨不一致。"}, {"text": "当场", "is_correct": false, "explanation": "搭配：“当场”指就在当时当地，持续的雨天不能“当场”发生。"}, {"text": "顺便", "is_correct": false, "explanation": "搭配：“顺便”表示附带做某事，不能修饰“下雨”这类自然现象。"}], "explanations": {"连天": "正确：“连天”表示一天接一天，与句中“下雨、没法出去玩”的持续情形相符。", "偶尔": "语义：“偶尔”指偶然发生，与“没法出去玩”所说的持续阴雨不一致。", "当场": "搭配：“当场”指就在当时当地，持续的雨天不能“当场”发生。", "顺便": "搭配：“顺便”表示附带做某事，不能修饰“下雨”这类自然现象。"}, "sentence_index": 0, "correct_answer": "连天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子连天很胆小。", "explanation": "此处误把“连天”当作“一直”之义，用来修饰表示性格的“很胆小”。连天指一天接一天地持续发生的动作或情况，不能直接描述性格。"}, {"text": "他连天是老师。", "explanation": "此处误把“连天”当成“一直”的意思，用于“是……”的判断句。连天只修饰表示持续动作的动词，不能用于判断句。"}, {"text": "他连天参加了一次面试。", "explanation": "这里误把“连天”当成“一下子”的意思。连天指一天接一天地持续，不能用于“参加了一次面试”这样一次性的事件，应删去“连天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连天", "is_correct": true, "explanation": "正确：“连天”表示一天接一天地刮风，与“门都关不上”的情形相符。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”指有意为之，风不能有意刮，句意不通。"}, {"text": "连忙", "is_correct": false, "explanation": "搭配：“连忙”表示急速地做某事，不用来修饰刮风这类自然现象。"}, {"text": "尽量", "is_correct": false, "explanation": "语义：“尽量”指竭尽力量去做，风无法“尽量”去刮。"}], "explanations": {"连天": "正确：“连天”表示一天接一天地刮风，与“门都关不上”的情形相符。", "特意": "语义：“特意”指有意为之，风不能有意刮，句意不通。", "连忙": "搭配：“连忙”表示急速地做某事，不用来修饰刮风这类自然现象。", "尽量": "语义：“尽量”指竭尽力量去做，风无法“尽量”去刮。"}, "sentence_index": 6, "correct_answer": "连天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他连天很聪明，成绩总是第一。", "explanation": "此处误把“连天”当成“一直”的意思，用来修饰表示性质的“很聪明”。连天表示一天接一天地持续发生，不能修饰形容词所描述的性质。"}, {"text": "我连天买了一台新电脑。", "explanation": "这里误把“连天”当成“一下子”的意思。连天指一天接一天地持续，不能修饰一次性的购买行为，应删去“连天”。"}, {"text": "他连天在床上躺了三秒钟。", "explanation": "此处误把“连天”当成“很短”的意思。本条“连天”指一天接一天地持续，不能与“三秒钟”这样的极短时段并用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很连天下雪，路都封住了。", "corrected_sentence": "连天下雪，路都封住了。", "error_description": "错误在“连天”前加了“很”。“连天”是副词，要直接修饰动词，不能被程度副词“很”修饰，应说“连天下雪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个村子连天的下雨，庄稼都坏了。", "corrected_sentence": "那个村子连天下雨，庄稼都坏了。", "error_description": "错误在“连天”后加了“的”。作副词时要直接修饰动词，不能加“的”变成定语结构，应说“连天下雨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
