INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96894, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96894, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "连续不断的天，形容很长时间；形容声势大。", "primary_collocate": null, "pronunciation": "lián tiān", "ipa": "ljɛn˧˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "战火连天，很多人离开了家。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炮火连天的那几年，大家都很苦。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到涨价的消息，市场里怨声连天。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，村里哭声连天。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杀声连天，战士们冲了上去。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球场上欢呼声连天，大家都站起来了。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天阴雨连天，衣服总是干不了。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梅雨季节阴雨连天，家里很潮。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几年战争不断，炮火连天，人人都想要和平。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的新工作太累，大家怨声连天。", "target_word": "连天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連天", "label": "繁体"}], "register": "书面", "sense_fingerprint": "形容词，放在炮火、怨声、阴雨等名词后作谓语，形容声势很大或持续很久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7078aa78-807e-46f0-8c99-774549f95561') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连天", "is_correct": true, "explanation": "正确：“连天”形容战火声势很大、持续很久，与“很多人离开了家”的语境相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声响，与“战火”的猛烈形象矛盾。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：“美丽”形容好看，不能用来形容战火的声势。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多用于水、眼睛等，不能修饰“战火”。"}], "explanations": {"连天": "正确：“连天”形容战火声势很大、持续很久，与“很多人离开了家”的语境相符。", "安静": "语义：“安静”指没有声响，与“战火”的猛烈形象矛盾。", "美丽": "语义：“美丽”形容好看，不能用来形容战火的声势。", "清澈": "搭配：“清澈”多用于水、眼睛等，不能修饰“战火”。"}, "sentence_index": 0, "correct_answer": "连天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆里安静连天。", "explanation": "此处误把“连天”当成“一直”的意思，用来描述无声的安静状态。本条“连天”形容长时间或声势大，多用于炮火、哭声、阴雨，不能用于安静的场合。"}, {"text": "书架上连天摆满了书。", "explanation": "这里误把“连天”当成“到处”的意思，用来描述书架上的摆放。本条“连天”形容声势大或时间长，不能用于静态的摆放。"}, {"text": "这张桌子连天干净。", "explanation": "这里误把“连天”当成“一直”的意思，用来描述桌子的整洁状态。本条“连天”只形容声势大或持续久，不能修饰“干净”这类性质形容词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连天", "is_correct": true, "explanation": "正确：“连天”形容阴雨持续很久，与“衣服总是干不了”的情形相符。"}, {"text": "晴朗", "is_correct": false, "explanation": "语义：“晴朗”指天气好，与“阴雨”及“衣服干不了”矛盾。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”多用于光线、房间，不用来形容阴雨。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”与“衣服总是干不了”的潮湿情形矛盾，句意不通。"}], "explanations": {"连天": "正确：“连天”形容阴雨持续很久，与“衣服总是干不了”的情形相符。", "晴朗": "语义：“晴朗”指天气好，与“阴雨”及“衣服干不了”矛盾。", "明亮": "搭配：“明亮”多用于光线、房间，不用来形容阴雨。", "干燥": "语义：“干燥”与“衣服总是干不了”的潮湿情形矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "连天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个广场连天很热闹。", "explanation": "这里误把“连天”当成“非常”的意思，当作程度副词修饰“很热闹”。本条“连天”形容声势大或持续久，多用于炮火、哭声、阴雨，不能当作程度副词。"}, {"text": "他连天走了五分钟。", "explanation": "此处误把“连天”当成“很短”的意思。本条“连天”形容很长时间，不能与“五分钟”这样的短时段并用。"}, {"text": "这条路连天很平坦。", "explanation": "这里误把“连天”当成“一直”的意思，用来修饰“很平坦”。本条“连天”形容长时间或声势大，不能用于描述道路的平坦程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "炮火连天了的年代，人们过得很艰难。", "corrected_sentence": "炮火连天的年代，人们过得很艰难。", "error_description": "错误在“连天”后加了“了”。作形容词修饰名词时，应用“的”连接，说“炮火连天的年代”，不能在“连天”后直接用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革以后，街上怨声了连天。", "corrected_sentence": "这次改革以后，街上怨声连天。", "error_description": "错误在“怨声”与“连天”之间多加了“了”。“连天”作谓语时直接接在主语之后，中间不能插入“了”，应说“怨声连天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71980b55-de49-40c6-829b-1f37f1159ea8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
