INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96895, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究东西怎么动的学问。", "primary_collocate": null, "pronunciation": "yùn dòng xué", "ipa": "yn˥˩ tʊŋ˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "他在大学学运动学。", "target_word": "运动学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动学研究东西怎么动。", "target_word": "运动学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对运动学很有兴趣。", "target_word": "运动学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动学老师今天讲了一道新题。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是讲运动学的。", "target_word": "运动学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想学运动学，所以读了物理系。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动学可以说明球是怎么飞的。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动学课很难，我听不懂。", "target_word": "运动学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学了运动学，我知道车怎么动。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动学是物理的一部分。", "target_word": "运动学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "運動學", "label": "繁体"}], "register": "书面", "sense_fingerprint": "研究东西怎么动的一门学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f797344-34e1-4b24-8621-ea8ced756a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96895, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "运动学", "is_correct": true, "explanation": "「运动学」是研究物体怎么动的学问，与听到的读音一致。"}, {"text": "运动鞋", "is_correct": false, "explanation": "韵母不同：「xué」是 -üe，「xié」是 -ie，声调相同，意思是运动鞋。"}, {"text": "运动靴", "is_correct": false, "explanation": "声调不同：「xuē」是第一声，「xué」是第二声，意思是运动靴。"}, {"text": "运筹学", "is_correct": false, "explanation": "中间一个音节不同：「chóu」不是「dòng」。运筹学研究怎么安排和计划，不是研究物体运动的学问。"}], "explanations": {"运动学": "「运动学」是研究物体怎么动的学问，与听到的读音一致。", "运动鞋": "韵母不同：「xué」是 -üe，「xié」是 -ie，声调相同，意思是运动鞋。", "运动靴": "声调不同：「xuē」是第一声，「xué」是第二声，意思是运动靴。", "运筹学": "中间一个音节不同：「chóu」不是「dòng」。运筹学研究怎么安排和计划，不是研究物体运动的学问。"}, "sentence_index": null, "correct_answer": "运动学"}, "level_3": {"options": [{"text": "运动学", "is_correct": true, "explanation": "「运动学」是学科名，「学运动学」表示学习这门学问，句意通顺。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是吃饭的地方，不是可以学习的学科，句意不通。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：「学历」要说「取得」或「拿到」，不说「学学历」。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：宿舍是住的地方，不能用来学习，句意不通。"}], "explanations": {"运动学": "「运动学」是学科名，「学运动学」表示学习这门学问，句意通顺。", "食堂": "语义：食堂是吃饭的地方，不是可以学习的学科，句意不通。", "学历": "搭配：「学历」要说「取得」或「拿到」，不说「学学历」。", "宿舍": "语义：宿舍是住的地方，不能用来学习，句意不通。"}, "sentence_index": 0, "correct_answer": "运动学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他学了一只运动学，很难。", "explanation": "量词用错：学科要用「门」，不用「只」，应说「一门运动学」。"}, {"text": "运动学研究为什么物体会动。", "explanation": "这里应该用〈动力学〉。运动学只描述物体怎么动，不问为什么动；「为什么动」属于动力学。"}, {"text": "这场运动学比赛很精彩，大家都在看。", "explanation": "「运动学」是学科名，没有体育活动的意思；这里应说「运动比赛」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运动学", "is_correct": true, "explanation": "「运动学」研究物体怎么动，可以说明球的运动，句意通顺。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是收录词语的工具书，不能说明球为什么会飞，句意不通。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱讲做菜的方法，与球的飞行无关，句意不通。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法讲词句的组合规则，不能说明球的飞行，句意不通。"}], "explanations": {"运动学": "「运动学」研究物体怎么动，可以说明球的运动，句意通顺。", "词典": "语义：词典是收录词语的工具书，不能说明球为什么会飞，句意不通。", "菜谱": "语义：菜谱讲做菜的方法，与球的飞行无关，句意不通。", "语法": "语义：语法讲词句的组合规则，不能说明球的飞行，句意不通。"}, "sentence_index": 6, "correct_answer": "运动学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动学用公式写出图形的面积。", "explanation": "这里应该用〈几何学〉。运动学只研究物体怎么动，图形的面积属于几何学。"}, {"text": "我每天下午去运动学一个小时。", "explanation": "这里应该用〈锻炼〉。「运动学」是学问名词，不能当动词表示做体育活动。"}, {"text": "他把运动学放进了书包里。", "explanation": "「运动学」是学问，不是可以装进书包的实物，这种用法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她大学时选了一只运动学课。", "corrected_sentence": "她大学时选了一门运动学课。", "error_description": "量词错误：「运动学课」是课程，应用量词「门」，不用「只」。正确说法是「选了一门运动学课」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这学期我们学得运动学课。", "corrected_sentence": "这学期我们学了运动学课。", "error_description": "助词错误：表示动作已经完成要用「了」，不用「得」（「得」后面要接补语）。正确说法是「这学期我们学了运动学课」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
