INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "力学的分支，研究物体运动而不管力。", "primary_collocate": null, "pronunciation": "yùn dòng xué", "ipa": "yn˥˩ tʊŋ˥˩ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "运动学是力学的一个分支。", "target_word": "运动学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动学只看物体怎么动，不管力。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动学和动力学不一样。", "target_word": "运动学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在运动学里，我们先看速度和位置。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文是关于运动学的。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人的手臂要先用运动学来算位置。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动学不问物体为什么动。", "target_word": "运动学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学运动学要先懂速度和加速度。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门运动学课要用很多数学。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动学用公式写出球的位置。", "target_word": "运动学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "運動學", "label": "繁体"}], "register": "书面", "sense_fingerprint": "力学的分支，只研究物体运动，不考虑力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f797344-34e1-4b24-8621-ea8ced756a77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96896, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "运动学", "is_correct": true, "explanation": "「运动学」是力学的分支，只研究物体怎么动，与听到的读音一致。"}, {"text": "运动鞋", "is_correct": false, "explanation": "韵母不同：「xué」是 -üe，「xié」是 -ie，声调相同，意思是运动鞋。"}, {"text": "运动靴", "is_correct": false, "explanation": "声调不同：「xuē」是第一声，「xué」是第二声，意思是运动靴。"}, {"text": "运筹学", "is_correct": false, "explanation": "中间一个音节不同：「chóu」不是「dòng」。运筹学研究怎么安排和计划，不是力学的分支。"}], "explanations": {"运动学": "「运动学」是力学的分支，只研究物体怎么动，与听到的读音一致。", "运动鞋": "韵母不同：「xué」是 -üe，「xié」是 -ie，声调相同，意思是运动鞋。", "运动靴": "声调不同：「xuē」是第一声，「xué」是第二声，意思是运动靴。", "运筹学": "中间一个音节不同：「chóu」不是「dòng」。运筹学研究怎么安排和计划，不是力学的分支。"}, "sentence_index": null, "correct_answer": "运动学"}, "level_3": {"options": [{"text": "运动学", "is_correct": true, "explanation": "「运动学」是力学的分支，与「是……的一个分支」搭配，句意通顺。"}, {"text": "天文学", "is_correct": false, "explanation": "语义：天文学研究天体，不是力学的分支，句意不对。"}, {"text": "生物学", "is_correct": false, "explanation": "语义：生物学研究生命现象，与力学不是分支关系，句意不对。"}, {"text": "工程", "is_correct": false, "explanation": "语义：工程是应用技术领域，不是力学的分支，句意不对。"}], "explanations": {"运动学": "「运动学」是力学的分支，与「是……的一个分支」搭配，句意通顺。", "天文学": "语义：天文学研究天体，不是力学的分支，句意不对。", "生物学": "语义：生物学研究生命现象，与力学不是分支关系，句意不对。", "工程": "语义：工程是应用技术领域，不是力学的分支，句意不对。"}, "sentence_index": 0, "correct_answer": "运动学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这学期他选了一只运动学。", "explanation": "量词用错：学科要用「门」，不用「只」，应说「一门运动学」。"}, {"text": "运动学要先分析力，再算运动。", "explanation": "这里应该用〈动力学〉。运动学不管力，只看运动本身；分析力要用〈动力学〉。"}, {"text": "这位运动学选手跑得很快。", "explanation": "「运动学」是学问，不指运动员，这里的用法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运动学", "is_correct": true, "explanation": "「运动学」只研究物体怎么动，不问为什么动，与句意一致。"}, {"text": "动力学", "is_correct": false, "explanation": "语义：动力学研究力与运动的原因，本来就要问「为什么动」，与句意相反。"}, {"text": "力学", "is_correct": false, "explanation": "语义：力学研究力和运动的关系，要讲力，与「不问为什么动」的句意冲突。"}, {"text": "语法", "is_correct": false, "explanation": "语义：语法研究词句规则，不研究物体为什么动，句意不通。"}], "explanations": {"运动学": "「运动学」只研究物体怎么动，不问为什么动，与句意一致。", "动力学": "语义：动力学研究力与运动的原因，本来就要问「为什么动」，与句意相反。", "力学": "语义：力学研究力和运动的关系，要讲力，与「不问为什么动」的句意冲突。", "语法": "语义：语法研究词句规则，不研究物体为什么动，句意不通。"}, "sentence_index": 6, "correct_answer": "运动学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动学用显微镜观察细胞的结构。", "explanation": "这里应该用〈生物学〉。运动学研究物体怎么动，观察细胞结构属于生物学。"}, {"text": "这门运动学很甜。", "explanation": "这里把「运动学」当成了食物，它是学问，不能用「甜」来形容。"}, {"text": "他把运动学切成了三块。", "explanation": "「运动学」是学问，不能像东西一样切成块，这种用法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校开了一只运动学课。", "corrected_sentence": "我们学校开了一门运动学课。", "error_description": "量词错误：「运动学课」的量词应用「门」，不用「只」。正确说法是「一门运动学课」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校开得运动学课。", "corrected_sentence": "我们学校开了运动学课。", "error_description": "助词错误：表示动作已经完成要用「了」，不用「得」（「得」后面要接补语）。正确说法是「我们学校开了运动学课」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6a6feb-06fc-406e-a75c-3d171fa52990') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
