INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96897, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "量东西时用来比的长度，或者做事的分寸。", "primary_collocate": null, "pronunciation": "chǐ dù", "ipa": "ʈʂʰɨ˨˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "做衣服时要先确定尺度。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这个尺度量出来的长度是一米。", "target_word": "尺度", "complexity_tier": "T3", "furigana": "yòng zhè ge chǐ dù liáng chū lái de cháng dù shì yí mǐ。", "sentence_source": "generated"}, {"text": "这个玩笑开得超过了尺度。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用同一个尺度来量桌子。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管孩子也要注意尺度。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人用手臂的长度做尺度。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话没有尺度，大家都不高兴。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个尺度不能放在一起比。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的关系近，说话也要有尺度。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批评员工要掌握尺度，别太过分。", "target_word": "尺度", "complexity_tier": "T3", "furigana": "pī píng yuán gōng yào zhǎng wò chǐ dù, bié tài guò fèn。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个尺度", "label": "量词"}], "register": "通用", "sense_fingerprint": "量东西用来比的长度，或做事的分寸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96897, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尺度", "is_correct": true, "explanation": "正确：做衣服要先定好量取的长度标准，“尺度”指衡量长度的标准，符合句意。"}, {"text": "口味", "is_correct": false, "explanation": "语义：做衣服时要先定的是尺寸等，“口味”与裁剪无关，句子不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“确定”可接“颜色、款式”等，不能接“心情”。"}, {"text": "名誉", "is_correct": false, "explanation": "语义：名誉与做衣服的先后步骤无关，句子不通。"}], "explanations": {"尺度": "正确：做衣服要先定好量取的长度标准，“尺度”指衡量长度的标准，符合句意。", "口味": "语义：做衣服时要先定的是尺寸等，“口味”与裁剪无关，句子不通。", "心情": "搭配：“确定”可接“颜色、款式”等，不能接“心情”。", "名誉": "语义：名誉与做衣服的先后步骤无关，句子不通。"}, "sentence_index": 0, "correct_answer": "尺度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的尺度很好，每次考试都得第一。", "explanation": "这里应该用〈成绩〉。“尺度”指衡量的标准或做事的分寸，不指成绩好坏，说成绩要用“成绩”。"}, {"text": "这个工程的尺度比原计划快了一周。", "explanation": "这里应该用〈进度〉。“尺度”指衡量的标准或做事的分寸，不指工作的快慢，说工程进展的快慢要用“进度”。"}, {"text": "今天的尺度有三十度，很热。", "explanation": "这里应该用〈温度〉。“尺度”指衡量的标准或做事的分寸，不指冷热，说气温要用“温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尺度", "is_correct": true, "explanation": "正确：“没有尺度”指说话不知分寸，符合句意。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”与“没有”搭配不成说法，说话的分寸要说“没有尺度”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的重量，与说话的分寸无关，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的高矮，与说话的分寸无关，句子不通。"}], "explanations": {"尺度": "正确：“没有尺度”指说话不知分寸，符合句意。", "速度": "搭配：“速度”与“没有”搭配不成说法，说话的分寸要说“没有尺度”。", "体重": "语义：体重是人的重量，与说话的分寸无关，句子不通。", "身高": "语义：身高是人的高矮，与说话的分寸无关，句子不通。"}, "sentence_index": 6, "correct_answer": "尺度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的尺度太小，我穿不上。", "explanation": "这里应该用〈尺码〉。“尺度”指衡量的标准或做事的分寸，不指衣服的大小，说衣服大小要用“尺码”。"}, {"text": "他一个小时跑完了十公里，尺度真快。", "explanation": "这里应该用〈速度〉。“尺度”指衡量的标准或做事的分寸，不指快慢，说跑步的快慢要用“速度”。"}, {"text": "他用尺度画出了一条直线。", "explanation": "这里应该用〈直尺〉。“尺度”指标准，不是画线的工具，画线要用直尺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家工厂约定了一座统一的尺度，零件才能通用。", "corrected_sentence": "两家工厂约定了一个统一的尺度，零件才能通用。", "error_description": "量词错误：“尺度”是抽象的标准，应用量词“个”，不能用“座”（“座”用于山、桥等大型固定物）。应改为“一个统一的尺度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父母要把握管教孩子尺度。", "corrected_sentence": "父母要把握管教孩子的尺度。", "error_description": "结构助词缺失：“管教孩子”修饰“尺度”时中间要加“的”，应为“管教孩子的尺度”；错句“管教孩子尺度”少了“的”，表达不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
