INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96898, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "衡量长度的标准；比喻掌握事物的分寸。", "primary_collocate": null, "pronunciation": "chǐ dù", "ipa": "ʈʂʰɨ˨˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "古代的尺度和现在不一样。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话要掌握好尺度。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家统一了长度的尺度。", "target_word": "尺度", "complexity_tier": "T3", "furigana": "kē xué jiā tǒng yī le cháng dù de chǐ dù。", "sentence_source": "generated"}, {"text": "开玩笑也要有尺度。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评学生，尺度很重要。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事总是把握不好尺度。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁缝按照统一的尺度量布。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对孩子的爱要有一定的尺度。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去各地用的尺度不一样。", "target_word": "尺度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上发言也要有尺度，不能说伤人的话。", "target_word": "尺度", "complexity_tier": "T3", "furigana": "zài wǎng shàng fā yán yě yào yǒu chǐ dù, bù néng shuō shāng rén de huà。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个尺度", "label": "量词"}], "register": "通用", "sense_fingerprint": "衡量长度的标准，也比喻做事的分寸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45695071-d032-44f9-b33f-c22aa16dc98b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尺度", "is_correct": true, "explanation": "正确：古代与现在的衡量标准不同，“尺度”指长度的标准，符合句意。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：古代没有电脑，与“古代”矛盾，句子不通。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”指将来，与“古代”的时间方向相反，句子不通。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来的时间，与“古代”矛盾，句子不通。"}], "explanations": {"尺度": "正确：古代与现在的衡量标准不同，“尺度”指长度的标准，符合句意。", "电脑": "语义：古代没有电脑，与“古代”矛盾，句子不通。", "未来": "语义：“未来”指将来，与“古代”的时间方向相反，句子不通。", "明天": "语义：“明天”指将来的时间，与“古代”矛盾，句子不通。"}, "sentence_index": 0, "correct_answer": "尺度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的尺度很好，考试得了满分。", "explanation": "这里应该用〈状态〉。“尺度”指衡量长度的标准或做事的分寸，不指身心状况，说状态好要用“状态”。"}, {"text": "这个西瓜的尺度很甜，一口咬下去全是汁。", "explanation": "这里应该用〈甜度〉。“尺度”指衡量长度的标准或做事的分寸，不指味道，说甜的程度要用“甜度”。"}, {"text": "他写作的尺度真快，一小时写完了三篇文章。", "explanation": "这里应该用〈速度〉。“尺度”指衡量长度的标准或做事的分寸，不指快慢，说做事快慢要用“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尺度", "is_correct": true, "explanation": "正确：“统一的尺度”指统一的长度标准，裁缝按它量布，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“量”用于长短、多少，不能量颜色，“量布”的对象是布的长度。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是量布的标准，与“量布”的意思不符。"}, {"text": "手艺", "is_correct": false, "explanation": "语义：手艺是技能，不能作为量布的标准，句子不通。"}], "explanations": {"尺度": "正确：“统一的尺度”指统一的长度标准，裁缝按它量布，符合句意。", "颜色": "搭配：“量”用于长短、多少，不能量颜色，“量布”的对象是布的长度。", "价格": "语义：价格不是量布的标准，与“量布”的意思不符。", "手艺": "语义：手艺是技能，不能作为量布的标准，句子不通。"}, "sentence_index": 6, "correct_answer": "尺度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间的尺度很大，能住五个人。", "explanation": "这里应该用〈面积〉。“尺度”指衡量长度的标准或做事的分寸，不指房间大小，说房间大小要用“面积”。"}, {"text": "这辆车的尺度很快，一小时能开一百公里。", "explanation": "这里应该用〈速度〉。“尺度”指衡量的标准或做事的分寸，不指快慢，说车跑得快慢要用“速度”。"}, {"text": "我用尺度买了三斤苹果。", "explanation": "这里应该用〈秤〉。“尺度”指衡量长度的标准或分寸，称重量要用秤，不能用尺度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师定了一粒统一的尺度，大家都按它来评分。", "corrected_sentence": "老师定了一个统一的尺度，大家都按它来评分。", "error_description": "量词错误：“尺度”是抽象的标准，应用量词“个”，不能用“粒”（“粒”多用于细小的颗粒）。应改为“一个统一的尺度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "家长定了一座管教孩子的尺度。", "corrected_sentence": "家长定了一个管教孩子的尺度。", "error_description": "量词错误：“尺度”是抽象的标准，应用量词“个”，不能用“座”（“座”用于山、桥等大型固定物）。应改为“一个管教孩子的尺度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a15363-8990-417e-9a11-d1a821c060bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
