INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96899, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96899, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人死去以后留下的身体。", "primary_collocate": null, "pronunciation": "yí tǐ", "ipa": "i˧˥ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "家人在医院见到了老人的遗体。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在门口向老人的遗体鞠躬。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在河边发现了一具遗体。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "亲人们为他的遗体盖上了白布。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把遗体送到了另一个房间。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的遗体将在下周三火化。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在老师的遗体前流下眼泪。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员小心地抬起遗体。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人决定把爷爷的遗体送回老家。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殡仪馆的工作人员为遗体整理了仪容。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一具遗体", "label": "量词"}, {"form": "遗体告别", "label": "复合"}, {"form": "遺體", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人去世后留下的身体，多用于庄重场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d88c77-461f-4c74-96b2-9f5f37a1c376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遗体", "is_correct": true, "explanation": "“遗体”指人死后留下的身体，与“老人的”和“医院”的语境相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：在医院里“见到”的不会是老人的房子，与语境不符。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“见到”的宾语须是可见之物，“声音”不能用“见到”。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”通常用“听到”，不能用“见到”。"}], "explanations": {"遗体": "“遗体”指人死后留下的身体，与“老人的”和“医院”的语境相符。", "房子": "语义：在医院里“见到”的不会是老人的房子，与语境不符。", "声音": "搭配：“见到”的宾语须是可见之物，“声音”不能用“见到”。", "脚步": "搭配：“脚步”通常用“听到”，不能用“见到”。"}, "sentence_index": 0, "correct_answer": "遗体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位画家给后人留下了很多遗体。", "explanation": "这里应该用〈遗产〉。“遗体”指死者的身体，不能指留给后人的财产或作品。"}, {"text": "这片古城的遗体吸引了很多游客。", "explanation": "这里应该用〈遗址〉。“遗体”指死者的身体，不能指古代留下的建筑或地方。"}, {"text": "爷爷在病房里休息，我们去看他的遗体。", "explanation": "这里应该用〈身体〉。“遗体”只指死去的人的身体，不能指还活着的人的身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遗体", "is_correct": true, "explanation": "“遗体”指死者的身体，与“老师的”和流泪的悲伤情境相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”看不见摸不着，人不能“站在”声音前面。"}, {"text": "意见", "is_correct": false, "explanation": "语义：“意见”是抽象的想法，不能作“站在……前”的处所。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“习惯”是抽象的行为方式，人不能站在它前面。"}], "explanations": {"遗体": "“遗体”指死者的身体，与“老师的”和流泪的悲伤情境相符。", "声音": "语义：“声音”看不见摸不着，人不能“站在”声音前面。", "意见": "语义：“意见”是抽象的想法，不能作“站在……前”的处所。", "习惯": "语义：“习惯”是抽象的行为方式，人不能站在它前面。"}, "sentence_index": 6, "correct_answer": "遗体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的遗体挂在客厅的墙上，每天都有人来看。", "explanation": "这里应该用〈遗像〉。遗体是尸体本身，不能挂在墙上供人观看。"}, {"text": "这台旧电脑是爷爷留下的遗体。", "explanation": "这里应该用〈遗物〉。“遗体”指死者的身体，不能指遗留的物品。"}, {"text": "大家把他的遗体撒在大海里，纪念他。", "explanation": "这里应该用〈骨灰〉。遗体是完整的尸体，不能撒进大海。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员在火灾现场找到了一个遗体。", "corrected_sentence": "消防员在火灾现场找到了一具遗体。", "error_description": "错误：遗体的量词用“个”，写成“一个遗体”。正确：“一具遗体”，遗体的量词是“具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "殡仪馆的工作人员把一位遗体推进了火化室。", "corrected_sentence": "殡仪馆的工作人员把一具遗体推进了火化室。", "error_description": "错误：遗体的量词用“位”，写成“一位遗体”。正确：“一具遗体”。“位”用于活着的人，遗体的量词是“具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
