INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "死者的身体。", "primary_collocate": null, "pronunciation": "yí tǐ", "ipa": "i˧˥ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "他生前决定，死后把遗体捐给医院。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方正在查看遗体上的伤。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这具遗体已经确认是失踪的男子。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗体保存得很好，没有变化。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们在山里找到了登山者的遗体。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遗体运回国那天，很多人来接。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家属在殡仪馆看了最后一眼遗体。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老先生的遗体安放在鲜花丛中。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把战士的遗体送回了家乡。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了遗体，没发现别的问题。", "target_word": "遗体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一具遗体", "label": "量词"}, {"form": "遗体告别", "label": "复合"}, {"form": "遺體", "label": "繁体"}], "register": "书面", "sense_fingerprint": "死者的身体，指被查看、安放或处理的对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d88c77-461f-4c74-96b2-9f5f37a1c376') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遗体", "is_correct": true, "explanation": "“遗体”指死者的身体，与“他生前决定，死后”和“捐给医院”的语境相符。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：“捐”的对象是物品或器官，不能把孩子捐给医院。"}, {"text": "遗嘱", "is_correct": false, "explanation": "搭配：“捐”不接“遗嘱”这类文书，遗嘱是写下的意愿。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“捐”的对象不能是“体温”这类无形的状态。"}], "explanations": {"遗体": "“遗体”指死者的身体，与“他生前决定，死后”和“捐给医院”的语境相符。", "孩子": "语义：“捐”的对象是物品或器官，不能把孩子捐给医院。", "遗嘱": "搭配：“捐”不接“遗嘱”这类文书，遗嘱是写下的意愿。", "体温": "搭配：“捐”的对象不能是“体温”这类无形的状态。"}, "sentence_index": 0, "correct_answer": "遗体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台旧收音机是爷爷留下的遗体。", "explanation": "这里应该用〈遗物〉。遗体指死者的身体，不能指遗留的物品。"}, {"text": "这片古城的遗体吸引了很多游客。", "explanation": "这里应该用〈遗址〉。“遗体”指死者的身体，不能指古代留下的建筑或地方。"}, {"text": "这个小孩的遗体很健康，每天都去上学。", "explanation": "这里应该用〈身体〉。遗体只指死者的身体，不能形容活着的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遗体", "is_correct": true, "explanation": "“遗体”指死者的身体，与“最后一眼”和殡仪馆告别的语境相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：在殡仪馆告别时看“最后一眼”的不是房子，与语境不符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”的宾语须是可见之物，“味道”不能用“看”。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”的宾语须是可见之物，“声音”不能用“看”。"}], "explanations": {"遗体": "“遗体”指死者的身体，与“最后一眼”和殡仪馆告别的语境相符。", "房子": "语义：在殡仪馆告别时看“最后一眼”的不是房子，与语境不符。", "味道": "搭配：“看”的宾语须是可见之物，“味道”不能用“看”。", "声音": "搭配：“看”的宾语须是可见之物，“声音”不能用“看”。"}, "sentence_index": 6, "correct_answer": "遗体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座古城的遗体很多，都被列入了世界文化遗产。", "explanation": "这里应该用〈遗迹〉。“遗体”指死者的身体，不能指古城中的遗址或建筑。"}, {"text": "他的遗体挂在客厅墙上，每天都有人来看。", "explanation": "这里应该用〈遗像〉。遗体是尸体本身，不能挂在墙上。"}, {"text": "亲人把他的遗体撒在江面上，纪念他。", "explanation": "这里应该用〈骨灰〉。遗体是完整的尸体，不能撒进江里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作人员把一个遗体放进了棺材。", "corrected_sentence": "工作人员把一具遗体放进了棺材。", "error_description": "错误：遗体的量词用“个”，写成“一个遗体”。正确：“一具遗体”，遗体的量词是“具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救护人员把一位遗体抬上了担架。", "corrected_sentence": "救护人员把一具遗体抬上了担架。", "error_description": "错误：遗体的量词用“位”，写成“一位遗体”。正确：“一具遗体”。“位”用于活着的人，遗体的量词是“具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8b1d133-fcf0-4c5d-b03b-104e404cd29b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
