INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用可可豆制成的甜食。", "primary_collocate": null, "pronunciation": "qiǎo kè lì", "ipa": "tɕʰiau˨˩˦ kʰɤ˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "巧克力是用可可豆做的。", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "巧克力比一般的糖贵，因为可可豆不便宜。", "target_word": "巧克力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盒巧克力里有牛奶和可可。", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "可可豆磨成粉，再做成巧克力。", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "巧克力是棕色的，由可可做成，味道又苦又甜。", "target_word": "巧克力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块巧克力有可可的香味，有一点苦。", "target_word": "巧克力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太热，她把巧克力放进冰箱，怕它化了。", "target_word": "巧克力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瑞士的巧克力在世界上很出名。", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋糕上的巧克力是黑色的，有点苦。", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "情人节那天，他送给女朋友一盒巧克力。", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "盒", "label": "量词"}, {"form": "黑巧克力", "label": "复合"}], "register": "中性", "sense_fingerprint": "以可可豆为原料制成的食品，味道微苦而甜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e8e5b6b-41e6-4dbe-82c6-698d5104ef7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巧克力", "is_correct": true, "explanation": "正确。“巧克力”是用可可豆做成的食品，与“用可可豆做的”相合。"}, {"text": "咖啡豆", "is_correct": false, "explanation": "语义：咖啡豆是咖啡的原料，与可可豆无关，“用可可豆做的”说法不通。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥不是食物，不可能用可可豆做成。"}, {"text": "面粉", "is_correct": false, "explanation": "搭配：面粉通常由小麦等磨成，不说“用可可豆做”。"}], "explanations": {"巧克力": "正确。“巧克力”是用可可豆做成的食品，与“用可可豆做的”相合。", "咖啡豆": "语义：咖啡豆是咖啡的原料，与可可豆无关，“用可可豆做的”说法不通。", "水泥": "语义：水泥不是食物，不可能用可可豆做成。", "面粉": "搭配：面粉通常由小麦等磨成，不说“用可可豆做”。"}, "sentence_index": 0, "correct_answer": "巧克力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天穿着巧克力去上学。", "explanation": "这里应该用〈衣服〉。巧克力是食品，不能穿在身上。"}, {"text": "妈妈每天给花浇巧克力。", "explanation": "这里应该用〈水〉。浇花要用水，巧克力是食品，不能用来浇花。"}, {"text": "他用巧克力给自行车打气。", "explanation": "这里应该用〈气筒〉。打气要用气筒，巧克力是食品，不能用来打气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巧克力", "is_correct": true, "explanation": "正确。“巧克力”会因天热而化，放进冰箱是为了防止它化掉。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会化，“怕它化了”的说法与石头不相符。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子不会化开，与“怕它化了”的句意冲突。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“化”不搭配“面包”，面包不会化开，只会变硬或发霉。"}], "explanations": {"巧克力": "正确。“巧克力”会因天热而化，放进冰箱是为了防止它化掉。", "石头": "语义：石头不会化，“怕它化了”的说法与石头不相符。", "沙子": "语义：沙子不会化开，与“怕它化了”的句意冲突。", "面包": "搭配：“化”不搭配“面包”，面包不会化开，只会变硬或发霉。"}, "sentence_index": 6, "correct_answer": "巧克力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在车站排队，手里拿着巧克力当作通行证。", "explanation": "这里应该用〈车票〉。巧克力是食品，不能用来代替车票。"}, {"text": "他在教室里大声朗读巧克力。", "explanation": "这里应该用〈课文〉。巧克力是食品，不能用来朗读。"}, {"text": "他用巧克力给汽车加油。", "explanation": "这里应该用〈汽油〉。加油用汽油，巧克力是食品，不能给汽车加油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只巧克力吃起来很香滑。", "corrected_sentence": "这块巧克力吃起来很香滑。", "error_description": "“巧克力”是食品，量词应用“块”。“只”用于动物，不能修饰巧克力。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了三张巧克力送给妈妈。", "corrected_sentence": "他买了三盒巧克力送给妈妈。", "error_description": "量词错误：成盒的“巧克力”用“盒”，不用“张”（“张”用于纸、桌子等扁平的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb122871-ef5a-4b57-9e38-e0f8f7beb505') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
