INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对相貌英俊的男子的称呼。", "primary_collocate": null, "pronunciation": "shuài gē", "ipa": "ʂuaɪ˥˩ kɤ˥", "syllable_count": 2, "sentences": [{"text": "帅哥，请问地铁站怎么走？", "target_word": "帅哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "帅哥，你的手机掉了。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "帅哥，要不要来一杯咖啡？", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务员笑着说：“帅哥，您要点什么？”", "target_word": "帅哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板叫我帅哥，我有点不好意思。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "帅哥，能帮我拍张照片吗？", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出租车司机对我说：“帅哥，到了。”", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "卖水果的大姐笑着喊我：“帅哥，买点苹果吧！”", "target_word": "帅哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帅哥，这件衣服很适合你，试试吧。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友们都叫他帅哥，他很高兴。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "帅哥们", "label": "复数"}, {"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "小帅哥", "label": "复合"}, {"form": "帥哥", "label": "繁体"}], "register": "口语", "sense_fingerprint": "称呼相貌英俊的男子的招呼语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9ae9251-8b31-482e-a2a6-0c86b6f51a65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帅哥", "is_correct": true, "explanation": "正确。“帅哥”是对男子的称呼，与“请问地铁站怎么走”的礼貌问路语境相符。"}, {"text": "手套", "is_correct": false, "explanation": "语义：“手套”是物品，不能用来称呼人，放在句首作称呼说不通。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：“钱包”是物品，不能用来称呼人，放在句首作称呼说不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物品，不能用来称呼人，放在句首作称呼说不通。"}], "explanations": {"帅哥": "正确。“帅哥”是对男子的称呼，与“请问地铁站怎么走”的礼貌问路语境相符。", "手套": "语义：“手套”是物品，不能用来称呼人，放在句首作称呼说不通。", "钱包": "语义：“钱包”是物品，不能用来称呼人，放在句首作称呼说不通。", "手机": "语义：“手机”是物品，不能用来称呼人，放在句首作称呼说不通。"}, "sentence_index": 0, "correct_answer": "帅哥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对收银的阿姨说：“帅哥，请问结账在哪儿？”", "explanation": "这里用“帅哥”称呼一位女性。“帅哥”作称呼时只用于男子，称呼女性应改用〈美女〉之类的称呼。"}, {"text": "我对卖花的小姑娘说：“帅哥，这束花多少钱？”", "explanation": "这里用“帅哥”称呼一位女孩。“帅哥”作称呼时只用于男子，称呼女性应改用〈美女〉之类的称呼。"}, {"text": "我对办公室里的女同事说：“帅哥，帮我复印一下文件吧。”", "explanation": "这里用“帅哥”称呼一位女性同事。“帅哥”作称呼时只用于男子，称呼女性应改用〈美女〉之类的称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帅哥", "is_correct": true, "explanation": "正确。“帅哥”是司机招呼乘客的称呼，与“到了”的语境相符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是物品，不能用来称呼人，说“雨伞，到了”不通。"}, {"text": "车票", "is_correct": false, "explanation": "语义：“车票”是物品，不能用来称呼人，说“车票，到了”不通。"}, {"text": "出租车", "is_correct": false, "explanation": "语义：“出租车”是交通工具，不能用来称呼人，说“出租车，到了”不通。"}], "explanations": {"帅哥": "正确。“帅哥”是司机招呼乘客的称呼，与“到了”的语境相符。", "雨伞": "语义：“雨伞”是物品，不能用来称呼人，说“雨伞，到了”不通。", "车票": "语义：“车票”是物品，不能用来称呼人，说“车票，到了”不通。", "出租车": "语义：“出租车”是交通工具，不能用来称呼人，说“出租车，到了”不通。"}, "sentence_index": 6, "correct_answer": "帅哥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对那个女孩说：“帅哥，能借我一支笔吗？”", "explanation": "这里应该用〈美女〉。“帅哥”只称呼男子，称呼女子要用“美女”。"}, {"text": "我对那位老奶奶说：“帅哥，您慢点走。”", "explanation": "这里用“帅哥”称呼一位老年女性。“帅哥”作称呼时只用于男子，不能用来称呼女性。"}, {"text": "我对前台的女服务员说：“帅哥，请给我一杯水。”", "explanation": "这里用“帅哥”称呼一位女性。“帅哥”作称呼时只用于男子，称呼女性应改用〈美女〉之类的称呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只帅哥，请问地铁站怎么走？", "corrected_sentence": "这位帅哥，请问地铁站怎么走？", "error_description": "“帅哥”指人，量词应用“位”或“个”，不能用“只”（“只”多用于动物及某些物件）。错误形式：这只帅哥；正确形式：这位帅哥。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个帅哥们，你们的手机掉了。", "corrected_sentence": "帅哥们，你们的手机掉了。", "error_description": "“帅哥们”已经表示复数，前面不能再加表示单数的“一个”，应直接说“帅哥们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9735ef9-4bd9-4c6c-8dfa-0c059bb4e0a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
