INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96905, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请别人来，一起做事或去玩。", "primary_collocate": null, "pronunciation": "yāo", "ipa": "jɑʊ˥", "syllable_count": 1, "sentences": [{"text": "小王邀我周末去爬山。", "target_word": "邀", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我邀朋友一起去看电影。", "target_word": "邀", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她邀我去她家玩。", "target_word": "邀", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天我想邀同学去公园玩。", "target_word": "邀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他邀了几个朋友一起去海边。", "target_word": "邀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同事邀我下班以后去吃火锅。", "target_word": "邀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末天气好，姐姐邀我们去骑自行车。", "target_word": "邀", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想邀你和我一起去旅行，你有时间吗？", "target_word": "邀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有邀过我去他家做客。", "target_word": "邀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都有空，我想邀他们来家里玩。", "target_word": "邀", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "邀了", "label": "体标"}, {"form": "邀过", "label": "体标"}], "register": "中性", "sense_fingerprint": "请人一起去玩或一起做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad778c81-0308-42c1-ae9b-f236d49633da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "邀", "is_correct": true, "explanation": "邀（yāo）：请别人来一起做事或去玩，即本词。"}, {"text": "摇", "is_correct": false, "explanation": "yáo（第二声）与 yāo（第一声）声调不同，意思是摇动。"}, {"text": "咬", "is_correct": false, "explanation": "yǎo（第三声）与 yāo（第一声）声调不同，意思是咬住。"}, {"text": "窑", "is_correct": false, "explanation": "yáo（第二声）与 yāo（第一声）声调不同，意思是烧砖瓦的窑。"}, {"text": "优", "is_correct": false, "explanation": "yōu 与 yāo 韵母不同（ōu 与 āo），意思是优秀。"}], "explanations": {"邀": "邀（yāo）：请别人来一起做事或去玩，即本词。", "摇": "yáo（第二声）与 yāo（第一声）声调不同，意思是摇动。", "咬": "yǎo（第三声）与 yāo（第一声）声调不同，意思是咬住。", "窑": "yáo（第二声）与 yāo（第一声）声调不同，意思是烧砖瓦的窑。", "优": "yōu 与 yāo 韵母不同（ōu 与 āo），意思是优秀。"}, "sentence_index": null, "correct_answer": "邀"}, "level_3": {"options": [{"text": "邀", "is_correct": true, "explanation": "语义相合：邀是请人一起去做事，与“周末去爬山”的邀约相符。"}, {"text": "吓", "is_correct": false, "explanation": "语义：吓是使人害怕，不能表示请人去爬山。"}, {"text": "逗", "is_correct": false, "explanation": "搭配：逗是戏弄、逗乐，不能带“去爬山”这类动作小句作宾语。"}, {"text": "骂", "is_correct": false, "explanation": "语义：骂是责备，与“周末去爬山”的邀约意思不合。"}], "explanations": {"邀": "语义相合：邀是请人一起去做事，与“周末去爬山”的邀约相符。", "吓": "语义：吓是使人害怕，不能表示请人去爬山。", "逗": "搭配：逗是戏弄、逗乐，不能带“去爬山”这类动作小句作宾语。", "骂": "语义：骂是责备，与“周末去爬山”的邀约意思不合。"}, "sentence_index": 0, "correct_answer": "邀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想邀老板批准我的申请。", "explanation": "这里应该用〈请〉。邀是请人来参加活动，不用于请人批准事情；请老板批准要说“请”。"}, {"text": "我想邀假回家看父母。", "explanation": "这里应该用〈请假〉。邀是请人来参加活动，不能跟“假”搭配；请假才是向单位请求准假。"}, {"text": "我邀朋友借我一百块钱。", "explanation": "这里应该用〈请求〉。邀是请人来参加活动，不用于请人帮忙借钱，这种场合要说“请求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96905, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "邀", "is_correct": true, "explanation": "邀（yāo）：请别人来一起做事或去玩，即本词。"}, {"text": "遥", "is_correct": false, "explanation": "yáo（第二声）与 yāo（第一声）声调不同，意思是遥远。"}, {"text": "药", "is_correct": false, "explanation": "yào（第四声）与 yāo（第一声）声调不同，意思是药物。"}, {"text": "忧", "is_correct": false, "explanation": "yōu 与 yāo 韵母不同（ōu 与 āo），意思是忧愁。"}, {"text": "谣", "is_correct": false, "explanation": "yáo（第二声）与 yāo（第一声）声调不同，意思是谣言。"}], "explanations": {"邀": "邀（yāo）：请别人来一起做事或去玩，即本词。", "遥": "yáo（第二声）与 yāo（第一声）声调不同，意思是遥远。", "药": "yào（第四声）与 yāo（第一声）声调不同，意思是药物。", "忧": "yōu 与 yāo 韵母不同（ōu 与 āo），意思是忧愁。", "谣": "yáo（第二声）与 yāo（第一声）声调不同，意思是谣言。"}, "sentence_index": null, "correct_answer": "邀"}, "level_3": {"options": [{"text": "邀", "is_correct": true, "explanation": "语义相合：邀是请人一起去骑车，与“周末天气好”的语境相符。"}, {"text": "砸", "is_correct": false, "explanation": "语义：砸是用力撞击，不能表示请人去骑自行车。"}, {"text": "打", "is_correct": false, "explanation": "语义：打是击打，与“去骑自行车”的邀约意思不合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，不能表示请人去骑自行车。"}], "explanations": {"邀": "语义相合：邀是请人一起去骑车，与“周末天气好”的语境相符。", "砸": "语义：砸是用力撞击，不能表示请人去骑自行车。", "打": "语义：打是击打，与“去骑自行车”的邀约意思不合。", "咬": "语义：咬是用牙齿夹住，不能表示请人去骑自行车。"}, "sentence_index": 6, "correct_answer": "邀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校邀了一场比赛。", "explanation": "这里应该用〈举办〉。邀的对象是人，不能用来指“举行比赛”。"}, {"text": "他在比赛中邀了一个奖。", "explanation": "这里应该用〈获得〉。邀的宾语应是人，不能跟“奖”搭配。"}, {"text": "我邀了一张电影票。", "explanation": "这里应该用〈买〉。邀的对象是人，不能用来指“买票”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不邀过他去玩。", "corrected_sentence": "我没邀过他去玩。", "error_description": "表示经历过的否定要用“没”，不能用“不”，应说“我没邀过他去玩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从来没有邀了我一起吃饭。", "corrected_sentence": "她从来没有邀过我一起吃饭。", "error_description": "“没有”后面表示经历时要用“过”，不能用“了”，应说“没有邀过我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7313a3a-3bfd-48d2-8c6e-cf7d4929a45d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
