INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96907, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "按一下，就能打出字或打开机器的小块。", "primary_collocate": null, "pronunciation": "jiàn", "ipa": "tɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "请按这个键开机。", "target_word": "键", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "键盘上的这个键坏了。", "target_word": "键", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电脑上哪个键可以删除字？", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我按了一下那个键，屏幕就亮了。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机右边有一个键，按它可以关机。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打字很快，手指在键上飞快地动。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个键太硬了，我每次都要用力按。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你按住这个键三秒，机器就会打开。", "target_word": "键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "键盘上有一个键掉了，我没办法打这个字。", "target_word": "键", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按错了键，写好的字都不见了。", "target_word": "键", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "键盘", "label": "复合"}, {"form": "按键", "label": "复合"}, {"form": "鍵", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电脑、手机等机器上按一下起作用的按键", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad778c81-0308-42c1-ae9b-f236d49633da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
